quests[27289] = { id = 27289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mumms Bericht", description = "Ihr habt gute Arbeit geleistet, {name}, die Beste, die ich je von einem Amateur sah.\n\nLady Prachtmeer bat mich, sie über diese delikate Situation auf dem Laufenden zu halten, aber ich habe eine Weile nicht mit ihr gesprochen.\n\nIch wollte ihr meinen Bericht später bringen, aber es scheint mir passender, wenn Ihr mit ihr darüber sprecht. Ihr könnt ihre Fragen wahrscheinlich besser beantworten als ich.", sourceObjective = "Bringt Mumms Bericht zu Lady Jaina Prachtmeer in Theramore.", sourceObjectiveStatus = "unverified-source-field" }
quests[27290] = { id = 27290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Gefechtsstand der Verlassenen", description = "Die Zeit, Crowley, Blutfang und jeden Hund unter ihrem Kommando zu töten, ist gekommen. Dazu muss man so gerissen und genau planen, wie wir es uns nie haben träumen lassen!\n\nAls einer der Soldaten, denen ich am meisten vertraue, müsst Ihr, {name}, zum Gefechtsstand der Verlassenen in Gilneas gehen und Euch bei Todespirscherkommandant Belmont melden. Ich habe Belmont bereits mit meinen Plänen vorausgeschickt. Er erwartet Eure Ankunft.\n\nArthura wird Euch zum Gefechtsstand der Verlassenen begleiten. Sagt mir, wenn Ihr bereit seid, und ich werde Euch auf den Weg bringen.", sourceObjective = "Meldet Euch in Gilneas am Gefechtsstand der Verlassenen bei Todespirscherkommandant Belmont.", sourceObjectiveStatus = "unverified-source-field" }
quests[27291] = { id = 27291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endlich Frieden", description = "Ich wünschte, wir könnten James Hyals Ehefrau und Sohn wissen lassen, dass ihre Mörder Gerechtigkeit erfahren haben.\n\n<Hauptmann Mumm holt einen kleinen Blumenkranz hervor.>\n\nManche sagen, dass ihre Geister dennoch die Wahrheit erfahren, auch, wenn wir sie nicht selbst kontaktieren können. Es ist nicht viel, aber könntet Ihr diesen Kranz beim Monument der Familie Hyal niederlegen? Es ist einer der größeren Grabsteine auf dem Friedhof nördlich der Tore von Theramore.", sourceObjective = "Hauptmann Garran Mumm bei der Wehrzitadelle möchte, dass Ihr den Kranz bei dem Monument der Familie Hyal niederlegt.", completion = "<Hauptmann Mumm hat ein kleines Lächeln im Gesicht, als Ihr von den Ereignissen am Familiengrab der Hyal berichtet.>\n\nEs beruhigt mich zu wissen, dass sie es verstanden haben. Ihr habt aber nichts von James gesagt, oder?\n\nIch werde ihm die Nachricht seiner Frau ausrichten, aber ich bezweifle, dass er sie verstehen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[27292] = { id = 27292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Krog", description = "Hoffentlich konnte ich Euch weiterhelfen. Es tut mir leid, dass ich Euch keine bessere Auskunft geben konnte. Meine Lehrlinge und ich fertigen solch eine große Menge an Waffen und Rüstungen an, dass es fast unmöglich ist, sich an detaillierte Informationen zu jedem Stück zu erinnern.\n\nWir statten nicht nur die mutigen Verteidiger der Taurenländer aus, nein, auch die Grimmtotem hegen eine besondere Vorliebe für meine Arbeit. Ein erfahrener Krieger erkennt gutes Handwerk, wenn er es sieht.", sourceObjective = "Sprecht mit Krog in Brackenwall.", completion = "Er hat wirklich gesagt, dass die Grimmtotem seine besten Kunden sind? Mosarn hat uns weit mehr geholfen, als er ahnt. Mit dieser Menge an Hinweisen, die die Grimmtotem belasten, dürften wir unsere Hauptverdächtigen gefunden haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27293] = { id = 27293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verschwörung der Grimmtotem", description = "Nachdem die Aktivitäten der Grimmtotem in Tausend Nadeln ans Licht gekommen sind, werden sie von mehr und mehr Tauren mit Argwohn betrachtet. Wir haben gesehen, wie sich hochrangige Vertreter der Grimmtotem an Morden und Entführungen beteiligten, um ihre eigenen Interessen voranzutreiben. Ich fürchte, wir könnten ihr nächstes Ziel sein.\n\nDas Dorf der Schwarzhufe im Nordosten, in der Nähe von Blaumoor, ist eine große neue Siedlung der Grimmtotem. Alle ihre Anführer, die Ältesten, dürften Anordnungen von Donnerfels bei sich tragen. Versucht, an die Pläne heranzukommen und setzt sie zusammen, um mehr über die Verschwörung der Grimmtotem zu erfahren.", sourceObjective = "Erlangt 4 Notizen der Grimmtotem von den Ältesten der Grimmtotem. Setzt die Teile zusammen, um die Schlachtpläne der Grimmtotem ganz zu sehen.", progress = "Konntet Ihr die Befehle ausfindig machen?", completion = "<Krog überfliegt die Schlachtpläne.>\n\nIch bin mir sicher, dass die Grimmtotem einen Angriff auf die Menschen planen. Allerdings weiß ich nicht, was ihre Absichten uns gegenüber sind. Wir wussten nichts von diesen Plänen und bedauern deswegen nun den Verlust eines guten Mannes. Ich kann mich nicht darauf verlassen, dass wir nicht auch auf ihrer Liste sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[27294] = { id = 27294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein bloßer Zufall", description = "Wir haben die Ruinen des Gasthauses so gut es ging nach Beweisen abgesucht. Die Ergebnisse unserer Ermittlungen beunruhigen mich, aber wir müssen die Wahrheit erfahren.\n\nDie Hufabdrücke und der Schild mit Mosarns Prägung deuten darauf hin, dass die Grimmtotem ihre Finger im Spiel haben. Sie haben erst kürzlich eine Siedlung im Sumpf errichtet, das Dorf der Schwarzhufe nordöstlich von hier. Reist zum Dorf der Schwarzhufe und sucht nach weiteren Waffen, die von Mosarn angefertigt wurden.", sourceObjective = "Sammelt 7 Waffen der Schwarzhufe im Dorf der Schwarzhufe.", progress = "Was konntet Ihr im Dorf der Schwarzhufe finden?", completion = "<Krog betrachtet die Waffen und die Rüstung, die Ihr aus dem Dorf der Schwarzhufe mitgebracht habt.>\n\nDas ist ganz unverkennbar die Arbeit von Mosarn. Ihn weiter auszufragen würde zu viel Aufmerksamkeit erregen, aber bei Angelegenheiten mit den Grimmtotem haben wir etwas mehr Handlungsfreiheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[27295] = { id = 27295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht Tabetha auf", description = "Die Waffen, die Ihr im Dorf der Schwarzhufe gefunden habt, wurden außer zu Übungszwecken noch nie im Kampf eingesetzt. Dies bedeutet, dass die Grimmtotem, die für das Feuer im Gasthaus \"Zur Süßen Ruh\" verantwortlich sind, noch immer auf freiem Fuß sind.\n\nIm Süden, im Herzen des Morasts, lebt die Hexe Tabetha. Sie ist zwar ein Mensch, doch in der Vergangenheit hat sie uns treue Dienste geleistet und einige unserer Magier ausgebildet.\n\nBittet sie, Euch beim Aufspüren der Grimmtotem, die für den Überfall auf das Gasthaus verantwortlich sind, zu helfen. Die Allianz soll nicht auf den Gedanken kommen, dass wir etwas damit zu tun hätten.", sourceObjective = "Sprecht mit Tabetha auf ihrem Hof im Morast.", completion = "<Tabetha lächelt.>\n\nKrog möchte, dass ich die Grimmtotem ausfindig mache, ja? Nun gut, dafür braucht es aber keine Magie.\n\nAnscheinend haben wir einen gemeinsamen Feind. Die Grimmtotem haben in der Nähe einen Außenposten errichtet und sind mir und meinen Schülern ein ständiger Dorn im Auge.", sourceObjectiveStatus = "unverified-source-field" }
quests[27296] = { id = 27296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennt den Grollhornposten nieder!", description = "Man muss nicht Hellsehen können, um zu wissen, welche Schwierigkeiten meine neuen \"Nachbarn\" hier heraufbeschwören. Falls es sich bei ihnen wirklich um diejenigen handelt, die das Gasthaus \"Zur Süßen Ruh\" niedergebrannt haben, dann gibt es keinen Grund mehr, sie hier noch länger zu dulden.\n\nNehmt diese Fackel und brennt ihr Lager nieder! Der Grollhornposten liegt nördlich von meinem Hof, in der Nähe der Straße. Ihr könnt ihn nicht verfehlen, wirklich. Die Grimmtotem haben ganze Arbeit geleistet und ihre Anwesenheit durch das Aufstellen ihrer Totems förmlich angekündigt.", sourceObjective = "Benutzt Tabethas Fackel, um das nördliche Zelt, das östliche Zelt und das nordöstliche Zelt am Grollhornposten in Flammen zu setzen.", progress = "Hat die Fackel ihren Zweck erfüllt?", completion = "Unsere Nachricht dürfte bei den Grimmtotem problemlos angekommen sein.\n\nWas Euch betrifft, so solltet Ihr Eurer Kontaktperson in Brackenwall von Eurem Erfolg berichten. So wie ich ihn kenne, wird ihm der Nachgeschmack der Rache gefallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27297] = { id = 27297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Walten der Gerechtigkeit", description = "Ich bezweifle, dass die Grimmtotem ihren Plan, die Menschen aus den Marschen zu vertreiben, aufgeben werden, allerdings habe ich den Eindruck, dass Euch das nicht weiter stört. Zumindest haben wir die Schuldigen für ihre Verbrechen am Gasthaus \"Zur Süßen Ruh\" bestraft.\n\nGeht und berichtet Eurem Anführer, dass die Rache gestillt wurde.", sourceObjective = "Kehrt zu Krog in Brackenwall zurück.", completion = "<Krog hört sich Euren Bericht an.>\n\nIch bin beeindruckt, {name}. Ich hatte vermutet, dass die verbrecherischen Grimmtotem nicht so einfach auszumachen sind. Die Allianz ist wirklich unfähig.\n\nUm ehrlich zu sein wollte ich eigentlich nur eine Antwort auf den Tod einer meiner Männer, aber in diesem Fall hatte ich wohl mehr Glück, als ich erwartet hatte. Falls die Grimmtotem sich rächen wollen, wird dies wohl durch einen Schlag gegen die Allianz passieren. Vielleicht haben wir sogar bald genügend Streitmächte, um diesen Haufen Dreck ein für alle Mal von unseren Küsten zu vertreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27298] = { id = 27298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht Meister Pyreanor auf", description = "Meister Pyreanor, ein erfahrener Blutritter und Berater des Kriegshäuptlings, verlangt nach Eurer Anwesenheit in Orgrimmar. Er zeigt Interesse an Eurer Ausbildung, {name}, und es ist von äußerster Wichtigkeit, dass Ihr sofort mit ihm sprecht.\n\nDie Nachricht, die ich erhalten habe, gibt keinen Grund für Euren Besuch an, aber Ihr solltet Euch umgehend nach Orgrimmar aufmachen. Ihr könnt Meister Pyreanor in der Burg im Zentrum vom Tal der Stärke finden.", sourceObjective = "Sprecht mit Meister Pyreanor im Tal der Stärke in Orgrimmar.", completion = "Ich habe viel von Euch gehört, {name}. Ihr habt in der Horde eine strahlende Zukunft vor Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[27299] = { id = 27299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerrissener Boden", description = "Ihr werdet nich' viel Überzeugungsarbeit leisten müss'n, um uns gegen den Schattenhammer aufzubringen - wir mögen die eh nicht. Wir sind aber schon wegen 'ner Schlacht hier, also brauchen wir vielleicht Eure Hilfe, bevor wir uns der Festung zuwenden können.\n\nDie Schattenhammerkultisten haben Iso'rath schon aus dem Boden im Süden geholt, habt Ihr sicher bemerkt. Seine Tentakel sind überall um uns 'rum aus dem Boden geschossen. Wir könnten 'ne helfende Hand gebrauchen, um sie niederzuschlagen. Was meint Ihr?", sourceObjective = "Tötet 3 Tentakel von Iso'rath.", completion = "Danke, {class}. 'N bisschen Platz zum Atmen hilft wirklich.", sourceObjectiveStatus = "unverified-source-field" }
quests[27300] = { id = 27300, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurückstoßen", description = "Die Schattenhammerkultisten haben 'ne Siedlung des Drachenmals im Süden zerstört und halten von dort aus Beschwörungsrituale ab. Gebt ihnen keine Gelegenheit, zur Ruhe zu kommen und zu ihren Zaubern zurückzukehren. Bringt die Schlacht zu ihnen!", sourceObjective = "Tötet 12 Schattenhammer in den Ruinen des Lagers der Drakgor.", completion = "Rache is' bittersüß, aber ich bin froh, dass jemand so mächtig wie Ihr die Sache in die Hand nimmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27301] = { id = 27301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungebrochen", description = "Wir bereiten ein Ritual vor, dass dabei helfen könnte, Iso'rath zu zerstören, die alte, von den Göttern gezüchtete Monstrosität, die vom Schattenhammer aus den Tiefen geholt wurde. Die Zeit läuft uns jedoch davon, denn unsere mächtigste Mitstreiterin wurde bei dem Angriff auf ihr Lager festgehalten.\n\nErdenruferin Yevaa befindet sich in den Ruinen südlich von hier. Sie ist noch am Leben, davon bin ich überzeugt. Bitte, rettet sie. Wenn einer von uns Eure Hilfe verdient, dann ist sie es.", sourceObjective = "Findet Erdenruferin Yevaa in den Ruinen von Drakgor.", completion = "Den Elementen sei Dank, dass Ihr gekommen seid. Haben meine Brüder Euch geschickt?", sourceObjectiveStatus = "unverified-source-field" }
quests[27302] = { id = 27302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfache Lösungen", description = "Ich bin neu hier. Ganz neu. Aber wisst Ihr was? Ich hab wenigstens Aussichten!\n\nIch hab ein paar Freunde, Schamanen, die haben Großes vor sich, aber die sind so festgefahren; sie vertrauen gänzlich auf Elemente und vergessen, die normalen Rohstoffe in ihrer Umgebung zu nutzen.\n\nBei den Ruinen südlich von hier habe ich gesehen, wie die Schläger des Schattenhammers Fass um Fass entflammbares Öl abtransportiert haben. Sie haben das Öl benutzt, um unsere Siedlung niederzubrennen. Ich schlage vor, wir tun es ihnen gleich.", sourceObjective = "Sammelt 10 Scheiterhaufenbrandölfässer.", progress = "Ich frage mich, was passiert, wenn man das Zeug über einen Elementar kippt. Ob ein Super-über-Leuchtfeuer-Elementar entsteht? Ich glaube fast schon. Das müssen wir ausprobieren.", completion = "Ha, genau das hab ich gemeint! Stellt Euch nur vor, was man damit alles machen kann! Mir fällt sicher nur ein Bruchteil ein. Aber die Nutzungsmöglichkeiten, die mir in den Sinn kommen, gefallen mir auf jeden Fall!", sourceObjectiveStatus = "unverified-source-field" }
quests[27303] = { id = 27303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mitleid mit den Gebundenen", description = "Natürlich hatte ich kein Bedürfnis, dort zu bleiben, aber es gab dort ein paar Materialien, die wir für das Ritual brauchen ... Ich war nicht schnell genug, alles einzusammeln, und das hat dann dazu geführt, dass sie mich geschnappt haben.\n\nIch werde zum Kreis zurückkehren, aber ich wäre Euch sehr dankbar, wenn Ihr an meiner Stelle diese Aufgabe abschließen könntet. Wir brauchen die Herzen der gebundenen Feuerelementare, die die Schattenhammerkultisten im westlichen Teil des Lagers gefangen halten.\n\nDie Elementare können nicht gerettet werden, aber durch dieses Opfer können sie Rache ausüben.\n\nTrefft mich im Lager.", sourceObjective = "Sammelt 5 Fleischbrennerherzen.", progress = "Konntet Ihr die Herzen einholen?", completion = "Ich danke Euch, {name}. Ihr seid sehr fähig. Ich bin Euch äußerst dankbar, dass Ihr Euch entschlossen habt, uns zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27304] = { id = 27304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sonne hinterher", description = "Sonnenwandler Atohmo schickt Kunde aus Orgrimmar. Er möchte Euch sprechen, wenn Ihr in der Stadt seid. Ich muss Euch wohl kaum daran erinnern, dass Atohmo ein ehrenhaftes Mitglied unseres Orden ist und seine Aufforderung nicht ignoriert werden sollte.\n\nWenn Ihr das nächste Mal in Orgrimmar seid, begebt Euch zum Tal der Weisheit und sprecht mit ihm.", sourceObjective = "Sprecht mit Sonnenwandler Atohmo im Tal der Weisheit in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[27305] = { id = 27305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Liebe und Familie", description = "In der Scharlachroten Bastion befindet sich ein Gemälde, dass für Hochlord Tirion Fordring persönlich äußerst wertvoll ist. Sucht nach einem Gemälde unseres Zwillingsmondes. Wenn Ihr die oberste Farbschicht abkratzt, werdet Ihr darunter das Meisterwerk 'Von Liebe und Familie' vorfinden.\n\nMöge das Licht Euch den Weg weisen. Oh, bitte seid äußerst vorsichtig mit dem Gemälde.", sourceObjective = "Findet 'Von Liebe und Familie'.", progress = "Das Gemälde, {name}. Habt Ihr das Gemälde?", completion = "Meister Fording wird überglücklich sein, das Gemälde zurück zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27306] = { id = 27306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit Ogron", description = "Ich kenne diesen Menschen, Paval Reethe. Lächerlich, selbst für einen seiner Art. Er ist ein Deserteur und hat seine Kameraden hintergangen. Jetzt versteckt er sich in den Wäldern.\n\nIch habe Ogron geschickt, um ihn ausfindig zu machen. Ein paar von den anderen glauben, dass er von unseren Vorräten gestohlen hat. Ich glaube, Ogron ist in Richtung Südosten unterwegs.", sourceObjective = "Findet Ogron südöstlich von Brackenwall.", completion = "Ogron? Jo, das bin ich.\n\nSchhh. Seid leise. Kroks hören Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[27310] = { id = 27310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Waffen für Grimmtotem!", description = "Nun gut, diese Feiglinge wollen kämpfen? Mal sehen, wie sie das ohne jegliche Waffen anstellen wollen.\n\nIhr habt doch sicherlich eine Fackel oder etwas in der Art.\n\nBrennt ihre Waffenregale nieder. Brennt sie alle nieder!", sourceObjective = "Brennt 8 Grimmtotemwaffenständer nieder.", completion = "Wir werden sehen, wie sie ihren Krieg jetzt führen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27311] = { id = 27311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Waffen für Grimmtotem!", description = "Die Grimmtotem wollen kämpfen? Mal sehen, wie sie das ohne ihre Waffen anstellen wollen. \n\nIhr habt doch sicherlich irgendwas, das brennt. Brennt ihre Waffenständer nieder, {class}.\n\nLasst die Natur die Arbeit verrichten.", sourceObjective = "Brennt 8 Grimmtotemwaffenständer nieder.", completion = "Mal sehen, wie gut sie ohne ihre Waffen kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27312] = { id = 27312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimmtotem in Düsterwolkengipfel", description = "Es geht nicht anders. Wenn man einen Kampf gewinnen will, muss Blut vergossen werden. Und in diesem Fall viel Blut.\n\nIhr wisst, was zu tun ist.", sourceObjective = "Tötet 20 Tauren der Grimmtotem in Düsterwolkengipfel.", completion = "Das hat ihre Zahlen verringert! Es ist ja nicht so, als hätten sie es nicht verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[27313] = { id = 27313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimmtotem in Düsterwolkengipfel", description = "Es gibt keine Alternative; wenn man einen Kampf gewinnen will, muss man das Blut des Feindes vergießen. Und in diesem Fall leider viel Blut.\n\nIhr wisst, was zu tun ist.", sourceObjective = "Tötet 20 Tauren der Grimmtotem in Düsterwolkengipfel.", completion = "Die Erdenmutter duldet Gewalt wie diese nicht, aber wir hatten keine andere Wahl. Die Grimmtotem haben ihre Lehren schon zu lange ignoriert, und ernten nun, was sie gesät haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27314] = { id = 27314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Häuptlinge der Grimmtotem: Isha Düsteraxt", description = "Grundlagen der Schildwachenausbildung: wenn der Anführer ausgelöscht ist, wird der Rest der Streitmacht bald zerfallen. Und genau das werden wir tun, {class}.\n\nIsha Düsteraxt ist von den Häuptlingen der Grimmtotem am wenigsten weit entfernt. Mal sehen, ob wir es mit ihr aufnehmen können.", sourceObjective = "Tötet Isha Düsteraxt.", completion = "Sie war ein stärkerer Gegner, als ich erwartet hatte. Wir haben gut zusammengearbeitet, aber wir müssen sicherstellen, dass wir die anderen Häuptlinge der Grimmtotem nicht unterschätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27315] = { id = 27315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Häuptlinge der Grimmtotem: Isha Düsteraxt", description = "Die Grundlagen der Kriegerheldenphilosophie legen fest, dass durch den Tod eines Anführers die restlichen Streitmächte bald den Mächten der Verwirrung zum Opfer fallen. Und genau das werden wir tun, {class}.\n\nIsha Düsteraxt ist von den Häuptlingen der Grimmtotem am wenigsten weit entfernt. Wir werden sie und ihre Axt auf die Probe stellen, und sie wird kläglich scheitern.", sourceObjective = "Tötet Isha Düsteraxt.", completion = "Sie war ein außerordentlicher Gegner, weitaus besser, als ihr Ruf vermuten lässt. Obwohl wir gut zusammengearbeitet haben, müssen wir sicherstellen, dass wir die anderen Häuptlinge der Grimmtotem nicht unterschätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27316] = { id = 27316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rassel der Knochen", description = "Eine Rassel der Tauren liegt hier und strahlt übernatürliche Macht aus. Ohne seine Hüter ist das Artefakt ungeschützt.\n\nVielleicht kann die Schildwache uns Einblicke in seine Bedeutung geben?", sourceObjective = "Gebt die Rassel der Knochen der Schildwache von Feralas in Düsterwolkengipfel in Tausend Nadeln.", progress = "Das ist die sagenhafte Rassel der Knochen, {name}!", completion = "Es ist also wahr! Aber was macht sie hier? Wenn die Rassel hier ist, bedeutet das, dass auch die Niederschrift und die Trommeln in der Nähe sein müssen!\n\nVielleicht gibt es eine Verbindung zwischen der Rassel und der Windnatter, die eben erschienen ist? Ich habe eine Ahnung, was es mit dieser Kreatur auf sich haben könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[27317] = { id = 27317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rassel der Knochen", description = "Eine Rassel der Tauren liegt hier und strahlt übernatürliche Macht aus. Ohne seine Hüter ist das Artefakt ungeschützt.\n\nVielleicht kann die Schildwache uns Einblicke in seine Bedeutung geben?", sourceObjective = "Gebt die Rassel der Knochen dem Kriegerheld des Freiwindpostens in Düsterwolkengipfel in Tausend Nadeln.", progress = "Die sagenhafte Rassel der Knochen, {name}!", completion = "Es ist also wahr! Aber was macht sie hier? Wenn die Rassel hier ist, bedeutet das, dass auch die Niederschrift und die Trommeln in der Nähe sein müssen!\n\nVielleicht gibt es eine Verbindung zwischen der Rassel und der Windnatter, die eben erschienen ist? Ich glaube, ich weiß, was es mit dieser Kreatur auf sich hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[27318] = { id = 27318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Häuptlinge der Grimmtotem: Ältester Sturmhuf", description = "Der Älteste Sturmhuf ist ein Schamane mit ernormer Macht. Anscheinend ist er die rechte Hand von Magatha Grimmtotem, der Ältestengreisin und Anführerin des Grimmtotemklans.\n\nWir wissen, dass er hier ist und damit beschäftigt ist, Geomanten auszubilden. Wir müssen ihn töten, {class}.", sourceObjective = "Tötet den Ältesten Sturmhuf.", completion = "Das wären zwei. Bleiben noch zwei.\n\nIch frage mich, was er mit \"auserwählt\" gemeint hat?", sourceObjectiveStatus = "unverified-source-field" }
quests[27319] = { id = 27319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Häuptlinge der Grimmtotem: Ältester Sturmhuf", description = "Der Älteste Sturmhuf ist ein Schamanenhäuptling mit ernormer Macht. Er wurde von Magatha Grimmtotem unterrichtet, der Ältestengreisin und Anführerin des Grimmtotemklans.\n\nWir wissen, dass er hier ist und damit beschäftigt ist, Geomanten auszubilden. Wir müssen ihn töten, {class}.", sourceObjective = "Tötet den Ältesten Sturmhuf.", completion = "Das war kein Spaß. Ich frage mich, was er damit gemeint hat, als er Euch \"auserwählt\" genannt hat?", sourceObjectiveStatus = "unverified-source-field" }
quests[27320] = { id = 27320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Niederschrift der Geschichte", description = "In der Mythologie der Shu'halo ist die Rassel der Knochen eng mit der Niederschrift der Geschichte und den Trommeln des Krieges verknüpft. Es handelt sich dabei anscheinend um wertvolle Artefakte der Tauren.\n\nWir müssen unsere Augen offen halten, wenn wir die anderen zwei Artefakte finden wollen. Wenn man den Geschichten Glauben schenken will, sieht die Niederschrift wohl aus wie eine Schriftrolle mit Piktogrammen.", sourceObjective = "Findet die Niederschrift der Geschichte.", progress = "Wir brauchen die echte Niederschrift, nicht irgendeine Schriftrolle der Tauren.", completion = "Ich bin mir relativ sicher, dass es die Niederschrift ist. Das ist sehr verwunderlich, {name}. Was haben die hier zu suchen? Werden sie als Waffen benutzt?\n\nDie Windnatter ist nordwestlich zum nächsten Felsen geflogen. Vielleicht sind die Trommeln dort?", sourceObjectiveStatus = "unverified-source-field" }
quests[27321] = { id = 27321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Niederschrift der Geschichte", description = "Die Rassel der Knochen ist Teil der uralten Mythologie der Shu'halo. Sie wurde schon immer mit der Niederschrift der Geschichte und den Trommeln des Krieges in Verbindung gebracht. Es handelt sich dabei anscheinend um wertvolle Artefakte der Tauren, Geschenke von der Erdmutter, wenn man den Geschichten Glauben schenken soll. Allerdings kann ich mir nicht vorstellen, dass die Erdmutter mit den Trommeln wirklich etwas zu tun hat.\n\nWir müssen aufmerksam sein, wenn wir die anderen zwei Artefakte finden wollen. Wenn ich mich recht erinnere, sieht die Niederschrift wohl aus wie eine Schriftrolle mit Piktogrammen.", sourceObjective = "Findet die Niederschrift der Geschichte.", progress = "Wir brauchen die echte Niederschrift, nicht irgendeine Schriftrolle.", completion = "Das ist sehr aufregend, aber auch Besorgnis erregend, {name}. Was haben die Artefakte hier zu suchen? Und werden sie von den Grimmtotem als Waffen gegen uns verwendet?\n\nDie Windnatter ist nordwestlich zum nächsten Felsen geflogen. Vielleicht sind die Trommeln dort?", sourceObjectiveStatus = "unverified-source-field" }
quests[27322] = { id = 27322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Korok der Koloss", description = "Das Monster ist gefallen und hat den Soldaten der Verlassenen an der Front so eine kurze Atempause verschafft.\n\nBringt Koroks zweiten Kopf zu Vorpostenkommandant Ansturm am Gefechtsstand der Verlassenen.", sourceObjective = "Bringt Koroks zweiten Kopf zu Vorpostenkommandant Ansturm am Gefechtsstand der Verlassenen in den Ruinen von Gilneas.", sourceObjectiveStatus = "unverified-source-field" }
quests[27323] = { id = 27323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Häuptlinge der Grimmtotem: Grundig Finsterwolke", description = "Einer der berüchtigten Anführer der Grimmtotem von Steinkrallengebirge ist zurückgekehrt.\n\nWir sollten diese Gelegenheit nutzen und sicherstellen, dass er nirgendwo anders hingeht.", sourceObjective = "Tötet Grundig Finsterwolke.", completion = "<Die Schildwache versucht, Euch einzuschätzen.>\n\nWas ist mit Euch los? Warum beunruhigt Eure Anwesenheit alle anderen?", sourceObjectiveStatus = "unverified-source-field" }
quests[27324] = { id = 27324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Häuptlinge der Grimmtotem: Grundig Finsterwolke", description = "Einer der versiertesten Anführer der Grimmtotem vom Steinkrallengebirge ist zurückgekehrt.\n\nWir müssen das Beste aus dieser Situation machen und seiner Schreckensherrschaft ein für alle Mal ein Ende setzen.", sourceObjective = "Tötet Grundig Finsterwolke.", completion = "<Der Kriegerheld versucht, Euch einzuschätzen.>\n\nIhr habt etwas Besonderes an Euch, {name}. So viel ist sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[27325] = { id = 27325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Trommeln des Krieges", description = "Was auch immer die Grimmtotem mit diesen Trommeln des Krieges machen, wir wollen nicht, dass sie noch länger in ihrem Besitz bleiben.\n\nSorgt Euch nicht, {name}, wir werden eine Lösung finden. Zuerst müssen wir aber alle Teile dieses Rätsels erlangen.", sourceObjective = "Findet die Trommeln des Krieges.", progress = "Die Tauren lieben Trommeln. Ich kann mir jedoch vorstellen, dass die Trommeln des Krieges sich von normalen Trommeln unterscheiden.", completion = "Das war sicher die Stimme der Ältestengreisin!\n\nWir müssen uns vorsehen, {name}. Vor uns liegen große Gefahren, wenn Magatha Grimmtotem Euch bemerkt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[27326] = { id = 27326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Trommeln des Krieges", description = "Was auch immer die Grimmtotem mit den Trommeln des Krieges machen, wir wollen nicht, dass sie sie behalten.\n\nSorgt Euch nicht, {name}, wir werden herausfinden, was hier vor sich geht. Zuerst müssen wir aber alle Artefaktteile finden.", sourceObjective = "Findet die Trommeln des Krieges.", progress = "Krieg ist keine Alternative für diejenigen, die sich an den Lehren der Erdmutter orientieren.", completion = "Das war sicher die Stimme der Ältestengreisin!\n\nWir müssen uns vorsehen, {name}. Vor uns liegen große Gefahren, wenn Magatha Grimmtotem Euch bemerkt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[27327] = { id = 27327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Häuptlinge der Grimmtotem: Der Häuptling aller Häuptlinge", description = "Die Zeit ist gekommen, dem Anführer aller Grimmtotem in Düsterwolkengipfel ein Ende zu bereiten: Arnak Grimmtotem.\n\nEs wird gesagt, dass er der in Ungnade gefallene Neffe von Magatha Grimmtotem ist, der Ältestengreisin und Matriarchin des Grimmtotemklans. Seine Taktlosigkeit hat wohl dazu geführt, dass sie ihm gegenüber nicht wohlgesinnt ist.\n\nAll dies ist aber jetzt nicht wichtig. Nur sein Tod ist für uns von Wichtigkeit. Sein endgültiger Tod.", sourceObjective = "Tötet Arnak Grimmtotem.", completion = "Aus irgendeinem Grund meinen alle, dass Ihr von Magatha Grimmtotem gesandt wurdet. Ich weiß, dass es etwas mit der Windnatter zu tun hat, die hier in letzter Zeit rumlungerte.\n\nIst aber auch egal. Ihr Anführer ist tot. Es ist nur eine Frage der Zeit, bis die Tauren den Freiwindposten wieder ihre Heimat nennen können.\n\nWenn ich einer von denen wäre, würde ich wohl ein bisschen Druck machen, um die Grimmtotem eine Lektion zu lehren. Aber das machen sie wahrscheinlich nicht. Sie sind immerhin Tauren.", sourceObjectiveStatus = "unverified-source-field" }
quests[27328] = { id = 27328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Häuptlinge der Grimmtotem: Der Häuptling aller Häuptlinge", description = "Die Zeit ist gekommen, um uns dem Anführer aller Grimmtotem in Düsterwolkengipfel zuzuwenden: Arnak Grimmtotem.\n\nEr ist der in Ungnade gefallene Neffe von Magatha Grimmtotem, der Ältestengreisin und Matriarchin des Grimmtotemklans. Seine Taktlosigkeit hat dazu geführt, dass sie ihm gegenüber nicht wohlgesinnt ist.\n\nAll dies ist aber jetzt nicht wichtig. Von Wichtigkeit ist nur, dass wir uns seiner annehmen. Ein für alle Mal.", sourceObjective = "Tötet Arnak Grimmtotem.", completion = "Alle haben geglaubt, dass Ihr von Magatha Grimmtotem geschickt wurdet. Man kann immerhin nicht leugnen, dass ihr Begleiter Arikara hier ist.\n\n<Der Kriegerheld blickt Euch lange an.>\n\nEs ist nicht wirklich wichtig. Arnak ist tot. Es ist nur eine Frage der Zeit, bis wir Freiwindposten zurückerobern.\n\nVielleicht wird es uns nun möglich sein, dauerhaften Frieden mit den Grimmtotem zu schließen?", sourceObjectiveStatus = "unverified-source-field" }
quests[27329] = { id = 27329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Windnatter entfernen", description = "Ich kenne diese Artefakte. Ich glaube, sie wurden von Magatha Grimmtotem persönlich hierher gebracht. Sie ist aber nicht bei den Grimmtotem in Düsterwolkengipfel. Sie ist gleich nach ihrer Ankunft wieder aufgebrochen, und niemand weiß, wo sie jetzt ist.\n\nVielleicht können wir es herausfinden.\n\nNehmt die Rassel, die Niederschrift, und die Trommeln mit zu Arikaras Steinkreis. Wenn ich richtig liege, wird die Windnatter wieder auftauchen. Ihr müsst sie besiegen, um über Magathas Versteck Hinweise zu erhalten.", sourceObjective = "Bezwingt Arikara.", completion = "Sie wurde also von den Schattenhammerkultisten gefangengenommen. Ich kann nicht sagen, dass ich großes Mitleid empfinde, aber in deren Händen könnte sie sich als noch gefährlicher herausstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27330] = { id = 27330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Windnatter entfernen", description = "Ich kenne diese Artefakte. Ich glaube, sie wurden von Magatha Grimmtotem persönlich hierher gebracht. Sie ist aber nicht bei den Grimmtotem in Düsterwolkengipfel. Sie ist gleich nach ihrer Ankunft wieder aufgebrochen, und niemand weiß, wo sie jetzt ist.\n\nVielleicht können wir es herausfinden.\n\nNehmt die Rassel, die Niederschrift, und die Trommeln mit zu Arikaras Steinkreis. Wenn ich richtig liege, wird die Windnatter wieder auftauchen. Ihr müsst sie besiegen, um über Magathas Versteck Hinweise zu erhalten.", sourceObjective = "Bezwingt Arikara.", completion = "Sie wurde also von den Schattenhammerkultisten gefangengenommen. Ich kann nicht sagen, dass ich großes Mitleid empfinde, aber in deren Händen könnte sie sich als noch gefährlicher herausstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27331] = { id = 27331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf der Seherin", description = "Soeben kam die Nachricht, dass Ihr in Orgrimmar gebraucht werdet, {name}. Seherin Liwatha bittet Euch, so schnell wie möglich in die Stadt zurückzukehren. Ihre Nachricht enthielt keine weiteren Informationen, aber es schien dringlich zu sein.\n\nSucht Seherin Liwatha im Tal der Weisheit in Orgrimmar auf.", sourceObjective = "Sprecht mit Seherin Liwatha im Tal der Weisheit in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[27332] = { id = 27332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht den Schattenläufer auf", description = "Der Schattenläufer Zuru fordert Eure sofortige Anwesenheit in Orgrimmar, {name}. Lasst ihn nicht warten, denn es klang, als sei es eine wichtige Angelegenheit.\n\nIhr werdet den Schattenläufer im Tal der Geister in Orgrimmar vorfinden.", sourceObjective = "Sprecht mit Schattenläufer Zuru im Tal der Geister in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[27333] = { id = 27333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haltlos", description = "Ich weiß nicht, wie lange wir die Stellung noch halten können, {name}. Die Worgen von Crowley und Blutfang kennen jedes noch so kleine Versteck und jeden sicheren Ort in Gilneas. In der einen Minute stehen sie vor Euch und in der nächsten Minute sind sie schon wieder weg! Wir werden diesen Krieg durch ihre Gelegenheitsangriffe verlieren, obwohl wir zahlenmäßig gesehen die Oberhand haben.\n\nMami hat aber keinen Aufgeber aus mir gemacht! Ich bin ein Verlassener bis zum bitteren Ende.\n\nBegebt Euch in die Mark und helft unseren Soldaten an vorderster Front. Tötet die angreifenden Rebellen der Worgen!", sourceObjective = "Tötet 12 Rebellen der Worgen.", completion = "Wenn ich noch Luft bekommen würde, würde ich jetzt erleichtert aufatmen.\n\nMacht es Euch nicht zu gemütlich, {name}. Eure Mission fängt hier erst an.", sourceObjectiveStatus = "unverified-source-field" }
quests[27334] = { id = 27334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Klerikerin Cecille", description = "Ich habe soeben eine Nachricht von der Dunklen Klerikerin Cecille aus Orgrimmar erhalten. Sie fordert Euch auf, sie in ihrem Audienzgemach in der Feste Grommash aufzusuchen. Sie empfängt dort eine Delegation aus Unterstadt. Die Klerikerin hat nicht gesagt, worum es bei Eurem Besuch geht, aber es ist ganz offensichtlich wichtig. Beeilt Euch, {name}.", sourceObjective = "Sprecht mit der dunklen Klerikerin Cecille in Feste Grommash im Tal der Stärke in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[27335] = { id = 27335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise nach Orgrimmar", description = "Ein Botschafter hat mich gebeten, Euch diese Einladung zu geben. Sie ist von Tyelis, einem Priesterlehrer und Abgesandten von Silbermond.\n\nEr fordert Euch auf, ihn in der Feste Grommash in Orgrimmar zu treffen. Ihr solltet sofort aufbrechen, {name}. Die Einladung klingt wichtig.", sourceObjective = "Sprecht mit Tyelis in Feste Grommash im Tal der Stärke in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[27336] = { id = 27336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Waffe der Grimmtotem", description = "Bevor ich während des letzten Angriffs der Grimmtotem verwundet wurde, konnte ich noch ein recht seltsames Totem an mich bringen, das von unseren Feinden gegen uns eingesetzt wurde.\n\nIm Kampf lässt es wohl wilde Energieblitze von sich. Leider konnte ich mit keinem meiner Experimente herausfinden, wie es funktioniert. Wenn Ihr versprecht, mir zu helfen, werde ich Euch das Totem leihen.\n\nDie Wasserflächen, die den Hof umgeben, beheimaten aggressive scheckige Staubsuhlerkrokilisken und Staubsuhlerdolchrachen. Versucht, die Krokilisken in Reichweite des Totems zu bekämpfen.", sourceObjective = "Platziert das erbeutete Totem auf dem Boden und tötet 10 scheckige Staubsuhlerkrokilisken oder Staubsuhlerdolchrachenen, um den Effekt des Totems zu testen.", progress = "Konntet Ihr das Totem erfolgreich testen?", completion = "<Der Lehrling hört Euch zu, als Ihr den Verlauf des Experiments schildert.>\n\nDunst und ein paar Blitze? Sonst nichts? Das Totem muss mehr können als nur das! Die Grimmtotem würden so etwas nicht mit aufs Schlachtfeld bringen, wenn es nicht irgendeinen wirklichen Nutzen hat!", sourceObjectiveStatus = "unverified-source-field" }
quests[27337] = { id = 27337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine passende Waffe", description = "Schon zu Beginn haben Eure Lehrer Euch für ein Naturtalent gehalten, {name}. Euer rascher Fortschritt und Eure Hingabe haben Euch zu einem wahren Vorbild gemacht.\n\nIn Anerkennung Eurer Dienste hat König Wrynn den königlichen Waffenschmied gebeten, eine besondere Waffe für Euch anzufertigen.\n\nDen Legenden zufolge ist die verfluchte Burg Schattenfang im Silberwald der Ort, an dem einige der Materialien zu finden sind, die Ihr dafür benötigt. Reist dorthin und findet das verlorene Schwert der Familie Silberlein, eine Ladung Mondstahlbarren und Sehnen der Ghule und Spuke, die die Burg heimsuchen.", sourceObjective = "Reist zu Burg Schattenfang und erhaltet das Schwert der Familie Silberlein von Baron Silberlein, 5 Kisten Mondstahlbarren und 5 ewige Sehnen.", progress = "Habt Ihr die Materialien besorgt, die ich für Eure Waffe benötige?", completion = "Ander hat gesagt, ich soll Euch erwarten. Es ist eine Ehre, für Euch eine Waffe zu schmieden, {name}. Mit diesen Materialien wird es wahrhaftig eine ausgezeichnete Klinge.", sourceObjectiveStatus = "unverified-source-field" }
quests[27338] = { id = 27338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsere Jungs an der Küste", description = "Die Lage hier in Hochland ändert sich minütlich. Unser Ziel ist es, die Bastion des Zwielichts zu stürmen, aber ich kann nicht mal eine Landezone an der Küste sichern, ohne dass die verfluchte Horde Ärger macht.\n\nIch brauche Männer, die hier am Strand die Landung sichern, während ich die Überreste der Flotte zusammensuche.\n\nMeldet Euch bei Leutnant Emry an der Küste und helft seinen Marinesoldaten, die Horde zurückzudrängen!", sourceObjective = "Meldet Euch bei Leutnant Emry in Zwielichtufer im Schattenhochland.", completion = "Zieht Euren Kopf ein, bevor er ihn verliert, {class}!\n\nDas hier ist MEIN Strand.\n\nDie Horde WILL meinen Strand.\n\nSie werden meinen Strand nicht BEKOMMEN.\n\nIst die Strandsituation damit geklärt?", sourceObjectiveStatus = "unverified-source-field" }
quests[27339] = { id = 27339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Reagenziendieb", description = "Wenn es eine Sache gibt, auf die man sich bei Lehrling Morlann verlassen kann, dann ist es sein ewiges Genörgel über fehlende Reagenzien.\n\nNormalerweise versuche ich einfach, ihn zu ignorieren, aber das funktioniert nicht. Dieses Mal werde ich etwas anderes versuchen.\n\nVielleicht lässt er mich in Ruhe, wenn ich fehlende Reagenzien ersetze, bevor ihm überhaupt auffällt, dass etwas fehlt. Das von uns am häufigsten genutzte Reagenz ist Marschengift. Ihr findet es bei Dunkelzahnkrabblern und giftigen Schreddern in den Marschen nördlich des Hofs. Wenn Ihr mir das Gift bringt, werde ich die Vorräte auffrischen, bevor Morlann merkt, dass etwas gefehlt hat.", sourceObjective = "Sammelt 6 Phiolen Marschengift von Dunkelzahnkrabblern oder giftigen Schreddern.", progress = "Habt Ihr das Gift bekommen? Morlann wird jeden Moment bemerken, dass nichts mehr da ist ...", completion = "<Lehrling Garion überprüft das Gift.>\n\nAbsolut perfekt! Der Unterschied wird ihm nie auffallen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27340] = { id = 27340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Räuber des Grollhornpostens", description = "Die Grimmtotem hoch oben in Grollhornposten werden von Tag zu Tag frecher. Nachts hört man oft, wie sie in Chören von ihren Taten im Kampf gegen die Bewohner der Gegend singen.\n\nSie sind festentschlossen, uns von Tabethas Hof zu vertreiben, obwohl schon Generationen von Lehrlingen hier ausgebildet wurden. Wir haben den Hof so gut es ging verteidigt, aber Lehrling Garion wurde beim letzten Angriff verwundet.\n\nBegebt Euch nach Grollhornposten und tötet alle Grimmtotem, die Ihr finden könnt! Diese Angriffe müssen ein Ende finden.", sourceObjective = "Tötet 12 Grimmtotem in Grollhornposten.", completion = "<Lehrling Morlann nickt.>\n\nGut. Ich werde ihre Anwesenheit nicht vermissen, wenn man es denn Anwesenheit nennen kann. Man sollte meinen, dass man wenigstens mitten im Sumpf ein wenig unter sich ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[27341] = { id = 27341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Späht den Strand aus", description = "Es ist ganz einfach, wir oder sie, {class}. Nur eine Fraktion kann diesen Strand einnehmen.\n\nNördlich von hier ist ein kleiner Hügel, von dem man die ganze Küstenlinie überblicken kann. Wer diesen Hügel einnimmt, erlangt sofort die Oberhand an der ganzen Küste.\n\nIch muss wissen, was die aktuelle Lage ist. Späht den Brückenkopfkontrollpunkt aus. Ihr erkennt ihn an den großen Flaggen. Kehrt anschließend zu mir zurück.\n\nIhr müsst nicht versuchen, ihn einzunehmen, es sei denn, Ihr dürstet nach einem Kampf ...", sourceObjective = "Späht den Brückenkopfkontrollpunkt in Zwielichtufer aus. Ihr müsst den Kontrollpunkt nicht einnehmen. Wenn Ihr ihn einnehmt, wird Eure Seite jedoch Vorteile im Kampf haben und Ihr werdet für PvP gekennzeichnet.", completion = "So ist das Land nun mal beschaffen. Wenn Ihr Schwierigkeiten mit dem Kampf an der Küste habt, könnt Ihr Euch vielleicht überlegen, hier auszuhelfen und versuchen, mit uns den Hügel einzunehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27342] = { id = 27342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zeit löst alle Rätsel", description = "Die Dunkle Fürstin hat Euch und Arthura für eine ganz besondere Aufgabe einberufen. Bevor ich Euch jedoch mehr verrate, müssen wir erst einige Vorbereitungen treffen.\n\nBegebt Euch zum Wald von Gilneas östlich von hier und sucht in der Nähe der Bäume und Steine in der Gegend nach einer besonderen Pflanze, die als Wolfsbann bekannt ist. Sammelt so viel Wolfsbann, wie Ihr tragen könnt und kehrt zu mir zurück.\n\nUnsere Aufgabe hier übersteigt die Aufgaben auf dem Schlachtfeld, {name}. Ich werde Euch zu gegebener Zeit mehr verraten.", sourceObjective = "Sammelt 6 Wolfsbann.", progress = "Konntet Ihr den Wolfsbann finden?", completion = "<Belmont nimmt Euch den Wolfsbann ab.>\n\nGut. Von jetzt an folgt den Befehlen von Vorpostenkommandant Ansturm. Versucht, Euch so gut wie möglich in die Reihen der Soldaten einzufinden. Wir wollen nicht, dass die Gilnearische Befreiungsfront auf Euch aufmerksam wird.\n\nOh, Ihr wusstet nicht, dass sie uns beobachten? In diesem Augenblick sind die Augen von fünf Spionen der Worgen direkt auf uns gerichtet. Bleibt ruhig und befolgt alle Befehle. Ich werde Euch Bescheid geben, wenn wir weitermachen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[27343] = { id = 27343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hand des Lichts", description = "Ich habe Eure Fortschritte verfolgt, {name}, und ich kann nur schließen, dass das Licht strahlend auf Euch scheint. Ihr seid wahrhaftig ein gutes Beispiel für <einen/eine:c> {class}.\n\nUm Eurer Hingabe Anerkennung zu zollen, hat König Wrynn den königlichen Waffenschmied beauftragt, eine besondere Waffe für Euch anzufertigen.\n\nDie Materialien zur Herstellung dieser Waffe sind einzigartig und können nur in der verfluchten Burg Schattenfang im Silberwald gefunden werden. Reist dorthin und findet das verlorene heilige Symbol von Kommandant Grüntal, eine Ladung Mondstahlbarren, und Sehnen der Ghule und Spuke, die die Burg heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und findet das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Kisten Mondstahlbarren und 5 ewige Sehnen.", progress = "Konntet Ihr die Materialien für Eure Waffe finden?", completion = "Lord Grayson hat mir viel von Euch und Eurer Hingabe zum Licht und der Allianz erzählt. Es wird mir eine große Ehre sein, einen Hammer für Euch anzufertigen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27344] = { id = 27344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine wohlverdiente Belohnung", description = "Nicht nur ich bin von Eurem Fortschritt beeindruckt, {name}. Wie Ihr Bogen und Begleiter meistert, und auch Eure Hingabe zur Allianz, sind König Wrynn zu Ohren gekommen.\n\nIn Anerkennung Eurer Dienste hat der König seinen königlichen Bogenmacher beauftragt, eine besondere Waffe für Euch anzufertigen.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der Ort, an dem Ihr die einzigartigen Bestandteile finden könnt, die für diese Waffe benötigt werden. Reist dorthin und findet das Zielfernrohr von Lord Godfreys Gewehr, eine Ladung mondbestrahltes Holz und Sehnen der Ghule und Spuke, die die Burg heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und erhaltet Godfreys Kristallzielfernrohr von Lord Godfrey, 5 Bündel mondbestrahltes Holz und 5 ewige Sehnen.", progress = "Habt Ihr die Materialien besorgt, die ich für Eure Waffe benötige?", completion = "Wer hätte gedacht, dass in einer verfluchten Burg so wertvolle Gegenstände zu finden sind? Ich sehe es als Ehre an, sie in eine wunderbare Waffe für Euch zu verarbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27345] = { id = 27345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das K.d.V.", description = "Die Kommunikation zu allen unseren Außenposten an der Front ist abgebrochen, {name}. Jetzt gerade habe ich nicht die leiseste Ahnung, wie es unseren Truppen in Gilneas ergeht. Wir müssen die Kommunikation wieder herstellen.\n\nBegebt Euch nach Westen in die Mark und findet unseren Außenposten an der Küste. Die Soldaten dort sind wahrscheinlich alle tot, aber ihr K.d.V. könnte noch funktionieren. Nehmt das Gerät an Euch und kehrt zu mir zurück.", sourceObjective = "Findet die Kommunikationsvorrichtung der Verlassenen.", progress = "Findet das K.d.V.", completion = "Mit diesem Gerät kann ich mich während Eurer Einsätze mit Euch in Verbindung setzen. Jetzt müssen wir uns daran machen, unsere Außenposten an der Front zu überprüfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27346] = { id = 27346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zeppelinabsturz", description = "Vor Kurzem ist östlich von hier ein Zeppelin der Goblins abgestürzt. Eine Beauftragte des Dampfdruckkartells kam hier vor ein paar Tagen vorbei.\n\nSie wollte Informationen über die Ladung des Zeppelins und den Piloten, Beezil, erhalten. Von uns hat den Absturz aber niemand wirklich gesehen. Ich bezweifle, dass sie das Zeppelinwrack alleine lichten kann, und noch viel weniger, dass sie je erfahren wird, welche Ladung an Bord war.\n\nWenn Ihr Zeit habt, könntet Ihr ihr vielleicht bei Beezils Wrack helfen. Es ist östlich von hier, in der Nähe der Berge.", sourceObjective = "Sprecht mit Moxie Stahlgrill bei Beezils Wrack.", completion = "Die Einsiedlermagier haben Euch geschickt? Wie soll ich wissen, dass ich Euch vertrauen kann?\n\nHilfe kann ich wohl gebrauchen. Hier gibt es auch nicht wirklich viel, für das sich Magier interessieren könnten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27347] = { id = 27347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Korrosionsschutz", description = "Seht Euch nur um! Alles ist voller Schlamm. Wenn wir nicht bald eine Möglichkeit finden, ihn unter Kontrolle zu bekommen, wird er das Wrack und die gesamte Zeppelinladung zersetzen und unbrauchbar machen!\n\nIch kann nicht mit leeren Händen zurückkehren, {class}! Helft mir, diese Schlamme aufzulösen, bevor sie alles zerstören!\n\nDieses Gerät feuert, sofern es aufgeladen ist, konzentrierte Energie auf einen Schlamm ab und bringt ihn so zur Explosion. Die Kraftkernfragmente des Zeppelins sollten über ausreichend Energie verfügen, um das Gerät anzutreiben. Der Kern beim Hauptwrack funktioniert einwandfrei, doch die anderen Kraftkerne laufen nur gelegentlich.", sourceObjective = "Moxie Stahlgrill möchte, dass Ihr 10 Schlamme auflöst und Euch dann bei Beezils Wrack bei ihr meldet.", progress = "Konntet Ihr gegen die Schlamme etwas ausrichten?", completion = "Naja, es sieht hier schon ein bisschen besser aus ...\n\nIch schätze, es ist an der Zeit, die Bergungsarbeiten fortzusetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27348] = { id = 27348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bergt die Fracht!", description = "Der Zeppelin hatte Vorräte für die nächsten sechs Monate für Morastwinkel geladen! Glücklicherweise konnte Morastwinkel sich bisher mit Tauschgeschäften über Wasser halten, doch das wird auf die Dauer nicht möglich sein.\n\nIch wurde hierher geschickt, um so viele Vorräte wie möglich zu bergen, doch leider sind die Wrackteile über die gesamten Marschen verteilt. Ich bin ziemlich sicher, dass nur die wenigsten Vorräte den Absturz heil überstanden haben. Würdet Ihr mir ein bisschen bei der Bergung helfen?", sourceObjective = "Moxie Stahlgrill bei Beezils Wrack möchte, dass Ihr 8 Teile der Zeppelinfracht bergt.", progress = "<Moxie sieht aus, als sei ihr vor Sorge ganz schlecht.>\n\nHaben die Vorräte den Absturz überstanden? Konntet Ihr sie finden?", completion = "Wow! Ihr habt in jedem Fall viel mehr gefunden, als ich erwartet hatte. Ich weiß nicht, welche Ausbeute Drazzit von uns erwartet, aber zunächst wird er sich damit zufrieden geben müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27349] = { id = 27349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kommunikationsabbruch: Außenposten von Schreckenswacht", description = "Ich werde Euch nicht anlügen, {name}. Was ich von Euch verlange ist mehr oder weniger Selbstmord. Die Wahrscheinlichkeit einer Niederlage beträgt 95%.\n\nAlle Kommunikation zum Außenposten der Schreckenswacht ist abgebrochen. Durch die ständigen Angriffe der Worgen haben wir keine Möglichkeit, zur Schreckenswacht aufzubrechen und nach unseren Soldaten zu schauen. Macht Euch auf den Weg in Richtung Süden zum Außenposten und seht nach unseren Soldaten. Ich werde von jetzt an mit Euch über die Kommunikationsvorrichtung der Verlassenen - dem K.d.V. - in Verbindung bleiben.\n\nHALTET EUCH VON DER HAUPTSTRASSE FERN.", sourceObjective = "Erkundet den Außenposten von Schreckenswacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[27350] = { id = 27350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kommunikationsabbruch: Rutsaks Wacht", description = "<Das K.d.V. brummt.>\n\nUnser nächster Außenposten ist Rutsaks Wacht, östlich von Schreckenswacht. Sucht Rutsak auf und seht zu, dass Ihr den Stürmern der Worgen entgeht, {name}. Diesen Monstern wollt Ihr nicht allein begegnen.\n\nWenn Ihr es in einem Stück dorthin schafft, sucht nach Hauptmann Rutsak.\n\nMacht Euch auf das Schlimmste gefasst.", sourceObjective = "Findet Hauptmann Rutsak in Rutsaks Wacht in den Ruinen von Gilneas.", completion = "Ss...na...na...nachdem wir Gilneas verloren haben, konnten wir auch den Hafen nicht h...h...halten.\n\nMM...MMM...MENSCHEN, HIER SIND MENSCHEN! Verstärkung aus Sturmwind! Sie haben meine Männer abgeschlachtet. Haben mich am Leben gelassen, um von ihrer Stärke zeugen zu können. Um meinen Befehlshabern... um zu berichten, dass die 7. Legion hier ist ...", sourceObjectiveStatus = "unverified-source-field" }
quests[27351] = { id = 27351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine königliche Belohnung", description = "Der SI:7 hat Eure Fortschritte mit Interesse beobachtet. Eure Dienste für die Allianz sind bekannt und Geschichten über Eure Taten sind dem König zu Ohren gekommen.\n\nIn Anerkennung Eurer Dienste hat König Wrynn den königlichen Waffenschmied gebeten, eine besondere Waffe für Euch anzufertigen.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der Ort, an dem Ihr die fremdartigen Bestandteile finden könnt, die für Eure Waffe benötigt werden. Reist dorthin und beschafft Euch Kommandant Grüntals Wetzstein, eine Ladung Mondstahlbarren, und Sehnen der Ghule und Spuke, die die Burg heimsuchen.", sourceObjective = "Reist zu Burg Schattenfang und erhaltet Grüntals Wetzstein von Kommandant Grüntal, 5 Kisten Mondstahlbarren und 5 ewige Sehnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27352] = { id = 27352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flüssiges Gold", description = "Nachdem die Geißel wie eine Krankheit durch Stratholme fegte, stellten die Ritter der Silbernen Hand Weihwasser her, um es gegen die Eindringlinge zu nutzen. Sie haben es in kleinen Kisten zusammen mit anderen wichtigen Vorräten gelagert und in der ganzen Stadt verteilt. Leider wurden die Einwohner der Stadt zu Geißeln, bevor die Vorräte je genutzt werden konnten!\n\nDie Vorratskisten werden sich für unsere Zwecke als äußerst nützlich erweisen. Bringt eine Phiole mit Weihwasser von Stratholme zu mir, damit ich es in größeren Mengen herstellen kann.", sourceObjective = "Findet eine Phiole mit Weihwasser von Stratholme.", progress = "Ist das eine Phiole mit Weihwasser von Stratholme?\n\nHe, ist das ganz normales Wasser? Spielt mit dem alten Steinberster keine Spielchen!", completion = "Hervorragend! Ich glaube, in größeren Mengen wird sich das Weihwasser als verheerend herausstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27353] = { id = 27353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Segen der Elemente", description = "Euer Talent hat in den Kreisen der Schamanen viel Aufsehen erregt, {name}. Geschichten von Eurer Beherrschung der Elemente und Eurer Hingabe zur Allianz können selbst im Palast vernommen werden.\n\nIn Anerkennung Eurer Dienste hat König Wrynn den königlichen Waffenschmied gebeten, eine besondere Waffe für Euch anzufertigen.\n\nDie Materialien für Eure Waffe können nur in der verfluchten Burg Schattenfang im Silberwald gefunden werden. Reist dorthin und erlangt den Talisman von Lord Walden, das Buch der verlorenen Seelen und Essenzen der Geister, die das Schloss heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und erhaltet den Waldens Talisman, das Buch der verlorenen Seelen und 5 geisterhafte Essenzen.", progress = "Habt Ihr die Materialien besorgt, die ich für Eure Waffe benötige?", completion = "Ich habe nicht oft die Möglichkeit, mit so fremdartigen Materialien zu arbeiten, aber selbst ich spüre die Macht dieser Gegenstände. Es wird mir eine Ehre sein, eine unglaubliche Waffe für Euch herzustellen, {name}. Die Weissagerin hat nicht untertrieben, als sie mir von Euren Fähigkeiten erzählte.", sourceObjectiveStatus = "unverified-source-field" }
quests[27354] = { id = 27354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschung des Arkanen", description = "Ihr habt Euch als <ausgezeichneter Student und engagierter Diener/ausgezeichnete Studentin und engagierte Dienerin> der Allianz herausgestellt. Selbst der König hat schon von Euren Leistungen gehört.\n\nIn Anerkennung Eurer Dienste hat König Wrynn den königlichen Verzauberer beauftragt, eine besondere Waffe für Euch anzufertigen.\n\nDie Materialien, die für Euren Stab benötigt werden, können nur in der verfluchten Burg Schattenfang im Silberwald gefunden werden. Reist dorthin und findet das verlorene Erbe der Familie Silberlein, etwas mondbestrahltes Holz und die Essenz der Geister, die die Burg heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und erlangt Silberleins verzauberten Kristall von Baron Silberlein, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.", progress = "Habt Ihr die Materialien besorgt, die ich für Eure Waffe benötige?", completion = "Ich habe Euch bereits erwartet, {name}. Maginor Dumas spricht in lobenden Tönen von Euch, und der Auftrag des Königs bestätigt diese Worte. Es ist mir eine Ehre, für Euch einen Stab anfertigen zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[27355] = { id = 27355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Segen für die Mächtigen", description = "Dank Eurer Taten bemerkt der König langsam unsere Macht und unseren Wert für die Allianz. Vielleicht werden die Unsrigen langsam akzeptiert.\n\nKönig Wrynn hat in Anerkennung Eurer Dienste den königlichen Verzauberer beauftragt, eine mächtige Waffe für Euch anzufertigen.\n\nDie Materialien dafür sind nur in Burg Schattenfang im Silberwald zu bekommen. Reist dorthin und erlangt die finstere Kugel von Lord Godfrey, das Buch der verlorenen Seelen, und Essenzen der Geister, die das Schloss heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und erhaltet die Finstere Kugel von Lord Godfrey, das Buch der verlorenen Seelen und 5 geisterhafte Essenzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27356] = { id = 27356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zukunft des Zirkels", description = "Der Zirkel des Cenarius ist zufrieden mit Eurem Fortschritt, {name}. Ihr seid von Wert für alle Druiden. Wir sehen in Euch und Euren Verbündeten die Zukunft unserer Bruderschaft.\n\nDer Zirkel hat entschieden, Euch mit der Herstellung eines einzigartigen Stabs zu ehren.\n\nDie seltenen und mächtigen Materialien für diesen Stab können nur in Burg Schattenfang im Silberwald gefunden werden. Reist dorthin und findet Lord Waldens Elixiersammlung, eine Ladung mondbestrahltes Holz, und Sehnen der Ghule und Geister, die die Burg heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und erhaltet Waldens Elixire von Lord Walden, 5 Bündel mondbestrahltes Holz und 5 ewige Sehnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27357] = { id = 27357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gefangene Braut", description = "Natürlich! Lakota Windweise! Warum ist mir das nicht früher eingefallen?\n\nArnak hat Lakota vor Jahren entführt und versucht, sie in eine Ehe zu zwingen. Sie konnte fliehen, aber in dem Chaos durch die Angriffe auf Freiwindposten in letzter Zeit konnte er sie wieder schnappen.\n\nSie muss hier irgendwo in der Nähe sein. Sie ist in den letzten Jahren recht mystisch geworden. Ich glaube, dass sie weiß, was man mit den Artefakten der Tauren machen kann.", sourceObjective = "Sprecht mit Lakota Windweise in Düsterwolkengipfel in Tausend Nadeln.", completion = "Es ist peinlich, schon wieder von Arnak entführt worden zu sein. Ich habe draußen Kampfgeräusche gehört. Habt Ihr ihn getötet?\n\n<Für einen winzigen Moment sieht die Schamanin traurig aus.>\n\nIch bin froh, wieder frei zu sein. Nun, wie kann ich Euch helfen, {race}?", sourceObjectiveStatus = "unverified-source-field" }
quests[27358] = { id = 27358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gefangene Braut", description = "Lakota Windweise! Warum ist mir das nicht früher eingefallen?\n\nArnak hat Lakota vor Jahren entführt und mit Gewalt versucht, sie zu seiner Braut zu machen. Sie konnte mit etwas Hilfe fliehen, aber in dem Chaos durch die Angriffe auf Freiwindposten in letzter Zeit konnte er sie wieder schnappen.\n\nSie muss in der Nähe sein. Sie hat in den letzten Jahren viel Schamanenwissen erworben. Ich bin mir sicher, dass sie uns sagen kann, inwiefern die Rassel, die Niederschrift und die Trommeln wichtig sind.", sourceObjective = "Sprecht mit Lakota Windweise in Düsterwolkengipfel in Tausend Nadeln.", completion = "Es ist peinlich, schon wieder von Arnak entführt worden zu sein. Ich habe draußen Kampfgeräusche gehört. Habt Ihr ihn getötet?\n\n<Für einen winzigen Moment sieht die Schamanin traurig aus.>\n\nIch bin froh, wieder frei zu sein. Nun, wie kann ich Euch helfen, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[27359] = { id = 27359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung der Argentumdämmerung", description = "Die Geißel haben eine Art Zauber gewirkt, der mich daran hindert, ein Portal zu öffnen. Daher kann auch unserer Verstärkung nun nicht dabei helfen, die Stadt einzunehmen! Es ist wie ein nicht enden wollender Schrei in meinem Kopf! Argh!\n\nIch versuche mein Bestes, um durch die Geräusche dieser Barriere nicht verrückt zu werden. Meine Vermutung ist, dass dieser Schutzwall von den Banshee aufrecht erhalten wird. Bringt mir ihre Essenzen - ich glaube, ich kann sie benutzen, um einen Gegenzauber zu wirken, damit die Verstärkung eintreffen kann!", sourceObjective = "Erhaltet 4 Essenzen einer Banshee.", progress = "Konntet Ihr die Essenzen erhalten? Seid vorsichtig, die Banshee sind todbringende Zauberer.", completion = "Oh... die Banshee sind in der Tat geschundene Seelen. Selbst das Halten ihrer Essenz schmerzt dem Gemüt...\n\nAber genug davon. Ich mache mich an den Gegenzauber, damit wir das Portal bald erstellen können. Stratholme wird bald Unser sein, ich weiß es einfach.", sourceObjectiveStatus = "unverified-source-field" }
quests[27360] = { id = 27360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache für unsere Soldaten", description = "Die 7. Legion… Sie haben uns mitten in der Nacht überrannt. Ihr Hauptmann hat Befehle gebrüllt, während die Besatzung des U-Boots meine Männer abgeschlachtet hat. Dann kam er zu mir, sah mir direkt in die Augen und sagte etwas, das ich nie vergessen werde:\n\n\"Ich bin Hauptfeldwebel Pietro Zaren, Offizier der 7. Legion. Wenn Ihr in Euren Alpträumen seht - wenn Ihr überhaupt noch schlafen könnt - wie Eure Soldaten massakriert werden, dann erinnert Euch an meinen Namen und zittert!\"\n\nRächt meine Soldaten! Tötet die 7. Legion, die das Kathedralenviertel von Gilneas südwestlich von hier besetzt.", sourceObjective = "Tötet 10 Unterseebootmatrosen der 7. Legion.", completion = "Obwohl wir in der Schlacht bloßgestellt wurden, konnte der Feind keinen Sieg erringen. Ich werde das niemals vergessen, {name}.\n\nWenn ich es heil in den Silberwald zurück schaffe, werde ich mich wahrscheinlich ausmustern. Der Krieg steckt mir nicht im Blut.", sourceObjectiveStatus = "unverified-source-field" }
quests[27361] = { id = 27361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vom Licht begünstigt", description = "Das Licht scheint wirklich hell auf Euch und Eure Hingabe zur Allianz, {name}. Ihr seid wahrhaftig ein gutes Beispiel für Eure Priesterkameraden und Kampfgenossen.\n\nIn Anerkennung Eurer Taten hat König Wrynn den königlichen Verzauberer beauftragt, einen besonderen Stab für Euch anzufertigen.\n\nDie Materialien für diese Waffe können nur in der verfluchten Burg Schattenfang im Silberwald gefunden werden. Reist dorthin und findet das verlorene heilige Symbol von Kommandant Grüntal, etwas mondbestrahltes Holz und die Essenz der Geister, die die Burg heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und erhaltet das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27362] = { id = 27362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elunes Liebling", description = "Ihr seid ein echter Diener Elunes, ein Beispiel für unser Volk, und ein tapferer Diener der Allianz. Der Tempel des Mondes und der Hof von Sturmwind möchten Eure Leistungen ehren.\n\nWir haben den königlichen Verzauberer beauftragt, einen Stab für Euch zu fertigen.\n\nDie Materialien für Euren Stab können nur in der verfluchten Burg Schattenfang im Silberwald gefunden werden. Reist dorthin und findet das verlorene heilige Symbol von Kommandant Grüntal, etwas mondbestrahltes Holz und die Essenz der Geister, die die Burg heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und erhaltet das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27363] = { id = 27363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vielversprechend für den Chirurgenberuf", description = "Ihr habt Euch als fähig in den Reihen der Priester und als wertvoll für die Leute von Gnomeregan erwiesen. Der Hochtüftler und der König von Sturmwind möchten Eure Arbeit für die Allianz ehren.\n\nSie haben den königlichen Verzauberer beauftragt, einen besonderen Stab anzufertigen.\n\nDie Materialien für diese Waffe können nur in der verfluchten Burg Schattenfang im Silberwald gefunden werden. Reist dorthin und findet das verlorene heilige Symbol von Kommandant Grüntal, etwas mondbestrahltes Holz und die Essenz der Geister, die die Burg heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und erhaltet das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27364] = { id = 27364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf wessen Befehl?", description = "<Das K.d.V. summt.>\n\nDie 7. Legion sind besondere Eliteeinheiten. Sie waren hinter den Kulissen für fast alle größeren Offensiven und Militäreingriffe der Allianz zuständig. Das sind schlechte Neuigkeiten. Wie sind sie nur an unseren Kriegsschiffen vorbei gekommen? Und auf wessen Befehl agieren sie?\n\nWir müssen ihre Befehle irgendwie in die Hände bekommen. Dieser Pietro hat sicherlich wichtige Informationen. Findet ihn im Kathedralenviertel von Gilneas und erledigt ihn. Durchsucht danach seinen Leichnam nach Hinweisen.", sourceObjective = "Findet die Befehle des Oberkommandos.", sourceObjectiveStatus = "unverified-source-field" }
quests[27365] = { id = 27365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine passende Waffe", description = "Schon zu Beginn haben Eure Lehrer gewusst, dass Ihr Euch bei der Horde einen Namen machen werdet. Ihr habt mutig gekämpft und Euren Feinden Grund zur Angst gegeben.\n\nAls Belohnung für Eure Hingabe hat der Kriegshäuptling bei seinem eigenen Schmied eine besondere Waffe in Auftrag gegeben.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und findet das verlorene Schwert der Familie Silberlein, eine Ladung Mondstahlbarren, und Sehnen der Ghule und Spuke, die die Burg heimsuchen.", sourceObjective = "Reist zu Burg Schattenfang und erhaltet das Schwert der Familie Silberlein vom Baron, 5 Kisten Mondstahlbarren und 5 ewige Sehnen.", progress = "Habt Ihr die Materialien besorgt, die ich für Eure Waffe benötige?", completion = "Grezz Zornfaust hat gesagt, ich soll Euch erwarten. Diese Materialien werden ein ausgezeichnetes Schwert machen. Benutzt es für den Ruhm der Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[27366] = { id = 27366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Landerschließung", description = "Die Marinesoldaten der Axtbeißer der Horde sind überall an meinem heiß geliebten Strand.\n\n<Der Leutnant deutet in Richtung Norden, entlang der Küste.>\n\nTötet sie.", sourceObjective = "Tötet 12 Marinesoldaten der Axtbeißer am Zwielichtufer im Schattenhochland.", completion = "Tot? Alle?\n\nImmerhin ein Anfang, {class}.\n\nImmerhin ein Anfang.", sourceObjectiveStatus = "unverified-source-field" }
quests[27367] = { id = 27367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gidwin Goldzopf", description = "Meine Jungs sind mir viel wert, versteht mich nicht falsch. Aber ich habe ihnen GESAGT, dass ich FÜNF MINUTEN brauche, um die Pferde zu versorgen und was machen sie? Schließen eine blöde Wette ab und weg sind sie! Ich hätte es besser wissen müssen... es ist immer das Gleiche.\n\nGidwin ist der kurz Gewachsene. Er hat sich in Richtung Norden aufgemacht, den Fluss entlang. Wenn Ihr in diese Richtung unterwegs sein solltet, könnt Ihr ihm sagen, er soll zurückkommen? Wir müssen zur Kapelle des Hoffnungsvollen Lichts und ich habe kein Problem damit, ihn zurückzulassen.", sourceObjective = "Findet Gidwin Goldzopf in den Östlichen Pestländern.", completion = "Tarenar? Bist du das?\n\nWer immer Ihr seid, würde es Euch etwas ausmachen, mir aus diesem Ding herauszuhelfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[27368] = { id = 27368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur eingehüllt", description = "Ihr hättet mich im Kampf sehen sollen! Ich hab bestimmt sechs dieser Biester getötet, als...\n\nOh, stimmt, Ihr könnt ja die Leichen sehen. Na gut. Vier der Biester habe ich getötet und dann kam das fünfte an und hat dieses Netz auf mich geschossen. Und noch viel schlimmer: Als es seinen Netzsaft abgeschossen hat, war mein Mund offen!\n\nIch kann dieses Netz nicht zerstören und Ihr werdet es wohl auch nicht können. Aber die Magensäfte von den untoten Spinnendingern könnten das Netz auflösen. Das funktioniert sicher.", sourceObjective = "Erhaltet 8 Phiolen Kryptengalle von den Nerubern im Schreckenstunnel.", progress = "Oh Mann... Fiona wird wütender sein als eine nasse Harpyie. Beeilt Euch bitte.", completion = "Ihr seid zurück?! Dem Licht sei Dank!\n\nBevor Ihr die Säure über mir ausschüttet, habe ich eine Frage: seid Ihr der Typ von vorhin, oder einer dieser achtbeinigen Feiglinge? Ich muss wissen, ob ich Euch eins überbraten sollte, sobald ich hier raus bin.", sourceObjectiveStatus = "unverified-source-field" }
quests[27369] = { id = 27369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Rad schmieren", description = "Entschuldigt mein Verhalten von eben. Ich war einfach sicher, Ihr wärt eines dieser Spinnenbiester, das sich als {race} ausgeben wollte.\n\nWie geht es Euch? Gidwin Goldzopf, zu Euren Diensten. Ich bin ein bisschen in Eile, weil ich schnell zurück zu meinem Karawanenwagen muss, aber ... könntet Ihr mir vielleicht noch einen Gefallen tun? Meine Freundin Fiona hat einen kleinen Laden und ich glaube, dass einige der Pflanzen, die hier am Flussufer wachsen, für sie von Interesse wären.\n\nIch glaube, wenn ich ihr ein paar tolle Pflanzen mitbringe, wird sie VIEL weniger sauer auf mich sein. Das ist zumindest der Plan.", sourceObjective = "Pflückt 10 Bansheeglocken vom Ufer des Thondroril.", progress = "Hat Giddy Euch mit hineingezogen?", completion = "Ich werde diesen winzigen Paladin in Stücke hauen, noch bevor er... oh, sind das etwa Bansheeglocken? Ihr habt die für mich gepflückt?\n\nOh, Gidwin hat Euch darum gebeten? Das ist wirklich süß von ihm. Na gut. Jetzt kann ich ihm fürs Erste nicht mehr böse sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[27370] = { id = 27370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tarenar Sonnenhieb", description = "Kaum hatten wir Halt gemacht, haben sie eine Wette abgeschlossen, wer die meisten Untoten in fünf Minuten töten könne.\n\nDas ist jetzt eine Stunde her und ich warte immer noch darauf, dass sie wieder herkommen.\n\nIch habe gesehen, wie Tarenar in Richtung Südosten losgelaufen ist. Aber leider kann ich den Wagen nicht unbeaufsichtigt lassen. Wenn Ihr zufällig in diese Richtung unterwegs sein solltet, könntet Ihr ihn suchen und zu mir zurückschicken?", sourceObjective = "Findet Tarenar Sonnenhieb an der Treppe des Schnitters in den Östlichen Pestländern.", completion = "Ich habe sie gefunden, {race}. Die Geißel. Wie ich mich nach diesem Tag gesehnt habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[27371] = { id = 27371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ich am besten kann", description = "Ich erinnere mich an die Zeit zurück, als ich jung war und mich oft in die Geisterlande geschlichen habe, um stundenlang Zombies zu verprügeln. Ich habe nicht einmal eine BEZAHLUNG dafür erhalten. Ich hab es einfach so gemacht.\n\nAber jetzt schaut Euch mal um. Das sind ernst zu nehmende Zombies. Ich wollte gerade damit anfangen, sie zu verprügeln, so wie früher. Wollt Ihr mir helfen?", sourceObjective = "Tötet 5 Missgeburten der Treppe des Schnitters an der Treppe des Schnitters in den Östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[27372] = { id = 27372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für Fiona", description = "Meine Reisegefährtin, Fiona, hat in ihrem Karawanenwagen einen kleinen Laden. Wir beide und unser Freund Gidwin sind auf dem Weg zur Kapelle des Hoffnungsvollen Lichts. Ihr könnt sicher mit uns reisen, wenn Ihr wollt... obwohl Fiona womöglich ein wenig sauer auf mich sein wird.\n\nFiona vergisst aber immer, dass sie sauer ist, wenn man ihr ein Geschenk macht. Tötet für mich ein paar dieser Seuchenhunde und bringt ihr Blut zu Fiona bei der Karawane unten am Fluss. Sie wird sich über alle Maßen freuen. Wir sehen uns dann dort!", sourceObjective = "Erhaltet 10 Proben des Bluts eines Seuchenhundes.", progress = "Ich hätte es wissen müssen. Tarenar hat dafür gesorgt, dass Ihr mir ein Geschenk macht? Dieser gedankenlose Idiot!\n\nÄhm... Um was für ein Geschenk handelte es sich denn?", completion = "Das ist ganz genau das, was ich gebraucht habe! Na gut, ich werde Tarenar dafür vergeben, dass er davongelaufen ist.\n\nIhr seid hier bei uns jederzeit willkommen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27373] = { id = 27373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf zur Kapelle des Hoffnungsvollen Lichts", description = "Jetzt, da die Jungs wieder hier sind, können wir endlich los. Ihr seid in Richtung Osten unterwegs?\n\nEs wäre uns eine Freude, wenn Ihr mit uns reisen würdet. Ich bestehe darauf! Erst gestern bei der Stätte der Heiler habe ich zu Tarenar gesagt: „Wir haben zwei Paladine und mich, um auf den Laden aufzupassen, aber weißt du, was wir wirklich brauchen? <Einen echten Helden/Eine echte Heldin>!“\n\nSeht mich nicht so an! Ehrlich! Kommt schon, springt auf!", sourceObjective = "Steigt auf Fionas Karawanenwagen am Thondroril in den Östlichen Pestländern.", completion = "Ich hoffe, die Fahrt war nicht zu holprig für Euch.\n\nSeht Euch einmal in der Gegend um den Turm herum um, solange sich die Pferde ausruhen. Es ist zwar nicht mit der Kapelle des Hoffnungsvollen Lichts zu vergleichen, aber ich bin mir sicher, dass Ihr Euch irgendwie beschäftigen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27374] = { id = 27374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schlund des Wahnsinns", description = "Ich kann es nicht glauben, {name}. Mein eigener Sohn - mein eigen Fleisch und Blut! Tut sich mit diesen Unholden vom Schattenhammer zusammen. Habt Ihr gesehen, was aus ihm wurde, als er versuchte, die Hochzeit zu zerstören? Oh... warum? Warum?\n\nEs ist diese Bestie, {name}. Der gigantische Schlund, der im Westen aus der Erde ragt. \"Der Schlund des Wahnsinns!\" Mein Sohn sagte, er würde mit ihm sprechen, aber ich dachte, es wären nur Alpträume.\n\nDer Irdene Ring versucht, ihn zu zerstören. Geht zu Erdenrufer Torunskar, westlich von hier, und schaut, ob Ihr helfen könnt!", sourceObjective = "Sprecht am Kreis der Elemente mit Erdenrufer Torunskar.", completion = "Willkommen, Bruder. Ihr habt eine schwere Zeit ausgesucht, um uns beizutreten, aber für uns ist das ein Glück. Wir können Eure Hilfe brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27375] = { id = 27375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schwärende Wunde", description = "Eine Bestie, {name}! Ich habe eine Bestie gesehen. Ein riesiger Schlund, ein noch größerer Hunger. Ich kann nicht glauben, dass sie wissen, was sie da losgelassen haben.\n\nEs ist hier. Sein schrecklicher formloser Körper bricht in diesem Augenblick in das Hochland herein.\n\nIch habe Euch in meiner Vision gesehen, {name}. Ihr kämpft zusammen mit dem Irdenen Ring, um das Biest zurückzudrängen. Ihr werdet der Dunkelheit gegenübertreten.\n\nGeht jetzt, bevor die Bestie an Macht gewinnt. Sprecht mit Erdenrufer Torunskar am Kreis der Elemente, nordwestlich von hier auf dem Gebirgskamm, hinter dem zerstörten Drakgorlager. Schnell!", sourceObjective = "Sprecht mit Erdenrufer Torunskar am Kreis der Elemente.", completion = "Willkommen, Bruder. Ihr habt eine schwere Zeit ausgesucht, um uns beizutreten, aber für uns ist das ein Glück. Wir können Eure Hilfe brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27376] = { id = 27376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Maul von Iso'rath", description = "Wir sind bereit, die Bestie anzugreifen. Erst müssen wir ihre Tentakel zerstören, dann wird Yevaa ein Ritual durchführen, um einen mächtigen Feuerelementar zu beschwören, den wir in den Schlund werfen werden.\n\nIch möchte, dass Ihr mit unserer ersten Gruppenattacke ausfliegt. Tut nichts, bis sich eine Gelegenheit bietet, dann tretet dem Kampf bei, indem Ihr mit den anderen Schamanen die Tentakel abschneidet.\n\nNehmt einen unserer Greifen, wenn Ihr für den Angriff bereit seid.", sourceObjective = "Steigt auf einen Greifen, um dem Angriff auf Iso'rath beizutreten.", completion = "Die Tentakel haben uns sogar von den Greifen geschlagen! Sie waren viel beweglicher, als wir angenommen hatten.\n\nEgal. Wir waren auf diese Möglichkeit vorbereitet. Ich kann den Elementar von hier aus beschwören, wenn Ihr mich beschützt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27377] = { id = 27377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlungen", description = "Wir wussten, dass das eine Möglichkeit war, aber wir hatten keine Ahnung, wie sich die Bestie verteidigen würde. Iso'raths Körper reagiert schnell auf unsere Bedrohung.\n\nIch kann die Beschwörung von hier aus beendet, aber nur, wenn Ihr Iso'raths Vereidigung zurückhalten könnt. Beschäftigt sie! Wir werden überleben!", sourceObjective = "Schützt Euch und Erdenruferin Yevaa vor Iso'raths körperlicher Verteidigung.", completion = "Ich habe Euch von der Schwelle des Todes zurückgeholt, Held!\n\nTodesschwinge ist da! Wir brauchen Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[27378] = { id = 27378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weltenbrecher", description = "Wir haben keine Zeit! Todesschwinge hat zugeschlagen, bevor wir uns gegen ihn aufstellen konnten. Wenn Ihr ihn nicht aufhaltet, endet der Irdene Ring hier und jetzt!", sourceObjective = "Bezwingt Todesschwinge, den Aspekt des Todes.", completion = "Ihr seid wach! Den Elementen sei Dank! Ich hatte fast die Hoffnung verloren.", sourceObjectiveStatus = "unverified-source-field" }
quests[27379] = { id = 27379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schrecken des Iso'rath", description = "Wir brauchen Euch! Ihr wart in einer Art Alptraum gefangen. Viele der anderen Schamanen sind das immer noch.\n\nEgal... unser Plan fällt auseinander. Einige unserer Schamanen kanalisieren schützende Auren, die die Verdauungsflüssigkeiten bekämpfen und Euch am Leben halten, aber wir müssen die anderen Schamanen vor den Tentakeln retten. Wir können Iso'rath nicht ohne sie besiegen!\n\nBleibt nicht ohne die anderen Schamanen im Magen, oder Ihr werdet bei lebendigem Leib verdaut!", sourceObjective = "Rettet Hargoth Trübflamm, Erdheiler Duarn, Sturmruferin Jalara und Sturmruferin Mylra.\n\nKehrt in den Schutz der anderen Schamanen zurück, wenn Iso'raths Verteidigung Euch zusetzt.", progress = "Die Schlacht ist noch nicht geschlagen. Die Schamanen innerhalb von Iso'rath zählen auf Euch!", completion = "Zusammen mit dem Irdenen Ring können wir Iso'raths Schrecken überleben. Jetzt ist es an der Zeit, uns zu rächen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27380] = { id = 27380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alptraum", description = "Iso'raths Hirn liegt frei! Der Schamane, den Ihr gerettet habt, sollte Euch in seiner Verteidigung einigermaßen sicher halten.\n\nGreift das Hirn an und zerstört Iso'rath!", sourceObjective = "Zerstört Iso'raths Gehirn.", completion = "Ihr habt heute viele meiner engsten Vertrauten gerettet, {name}. Ich kann mir kaum vorstellen, was für Schrecken Ihr in Iso'rath gesehen habt, aber Ihr habt den Dank des gesamten Irdenen Rings.", sourceObjectiveStatus = "unverified-source-field" }
quests[27381] = { id = 27381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reisegefährten", description = "Jetzt wo wir schon hier an diesem Turm sind, können wir auch schauen, ob außer uns noch jemand zur Kapelle des Hoffnungsvollen Lichts unterwegs ist. Je mehr, desto besser, nicht wahr?\n\nFragt doch in der Umgebung, ob uns jemand auf der Reise begleiten möchte. Ich bin sicher, dass wir jemand finden werden, der auch zur Kapelle unterwegs ist.", sourceObjective = "Findet jemanden am Turm der Kronenwache, der sich Eurer Reisegruppe anschließen möchte.", progress = "Wie sieht es aus?", completion = "Argus Leuchtfeuer ... der Alte von hoch oben im Turm? Großartig!\n\nEin Mann seines Alters gehört dem Argentumkreuzzug bestimmt schon ewig an. Vielleicht kann er bei der Kapelle ein gutes Wort für uns einlegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27382] = { id = 27382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verseuchte Straßen", description = "Der Argentumkreuzzug hat diese Türme als Lichter in der Dunkelheit der Pestländer errichtet. Ich bin auf den Pfaden zwischen den Türmen unterwegs, um sie zu schützen und instand zu halten.\n\nIn letzter Zeit wurden die Straßen aber immer gefährlicher. Verseuchte Wildtiere laufen frei herum und die Fledermäuse greifen nichtsahnende Reisende an. Es würde den nächsten Teil meiner Reise sehr erleichtern, wenn Ihr für mich die wilden Tiere aus dem Weg schaffen könntet.", sourceObjective = "Tötet 13 Seuchenfledermäuse entlang des Wegs zum Lichtschildturm.", completion = "Natürlich war es für einen jungen {race} wie Euch nicht schwierig, ein paar Wildtiere zu beseitigen. Jetzt, da die Straßen geräumt sind, wird meine Reise zum nächsten Turm viel einfacher.", sourceObjectiveStatus = "unverified-source-field" }
quests[27383] = { id = 27383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klein-Pamela", description = "Die Schlacht von Darroheim verfolgt mich immer noch, {race}. Ich wache in kaltem Schweiß auf, felsenfest davon überzeugt, dass ich noch dort bin. Diese Träume holen mich immer und immer wieder ein.\n\nMit dem Tod meiner Kameraden komme ich einigermaßen klar, aber der Tod meiner Familienmitglieder schmerzt immer noch gnadenlos. Eine meiner Verwandten, die ich bei dem Angriff verloren habe, war meine kleine Nichte Pamela.\n\nWenn Ihr mutig genug seid, Darroheim aufzusuchen, könnt Ihr nach einem Zeichen von meiner kleinen Pammy suchen? Die Ruinen von Darroheim sind südlich von hier.", sourceObjective = "Sucht in Darroheim nach Pamela Rotpfad.", completion = "Hallo. Ich bin Pamela und wie heißt Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[27384] = { id = 27384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pamelas Puppe", description = "Meine Tante Marlene hat gesagt, ich soll in unserem Haus bleiben, weil mein Vater in den Kampf ziehen muss. Mein Vater ist der mutigste Mann auf der ganzen Welt!\n\nAber ich bin schon so lange hier und er ist nicht gekommen, um mich abzuholen. Manchmal kommen böse Leute und flüstern mir etwas zu und ich will, dass mein Vater sie wegjagt, aber er ist nicht hier!\n\nUnd manchmal, wenn es dunkel wird, möchte ich mit meiner Puppe spielen, aber das kann ich nicht, weil ich sie in der Stadt gelassen habe.\n\nKönnt Ihr vielleicht meine Puppe für mich suchen?", sourceObjective = "Sucht Pamelas Puppe.", progress = "Habt Ihr meine Puppe gefunden?", completion = "Ihr habt sie gefunden! Ihr habt meine Puppe gefunden! Oh, danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[27385] = { id = 27385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onkel Carlin", description = "Ich werde mit meiner Puppe spielen, aber mit Papas Schwert will ich doch nicht spielen. Ihr könnt es haben.\n\nOder könnt Ihr es vielleicht doch lieber Onkel Carlin geben? Ich weiß nicht, wo er ist, aber manchmal höre ich ihn weinen. Es klingt, als ob er in der Nähe ist, nördlich von hier. Ich hoffe, er weint nicht wegen mir! {name}, könnt Ihr meinen Onkel suchen und ihm sagen, dass es mir gut geht? Wenn Ihr ihn findet, sagt ihm, ich warte auf ihn und ich will die Geschichte hören, die er mir immer erzählt hat ... die von den Kaninchen und der Beerenmarmelade! Die Geschichte ist so witzig!", sourceObjective = "Kehrt zu Carlin Rotpfad am Turm der Kronenwache in den Östlichen Pestländern zurück.", progress = "Gibt es Neuigkeiten von meiner Pammy?", completion = "Ihr habt Pamela gesehen? Ist sie am Leben?\n\nSie ist tot? Nein! Oh, Pamela! Warum leidet dein Geist noch immer in dieser Welt? Warum musstest du sterben, wenn ich am Leben gelassen wurde? Ohne zu zögern würde ich mit dir tauschen und tot durch Darroheim wandern, als Geist und ganz allein! Ah, diese Nachrichten können mein Schicksal nicht ändern. Ich danke Euch, {name}. Jetzt ruft meine Pflicht, die Pflicht nach Rache, lauter als je zuvor.\n\nSagt, was ist das für ein Schwert, das Ihr da habt?", sourceObjectiveStatus = "unverified-source-field" }
quests[27386] = { id = 27386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein seltsamer Historiker", description = "Dieses Schwert hat Joseph Rotpfad gehört, Pamelas Vater - aber das wisst Ihr wahrscheinlich schon. Ich wünschte, Joseph könnte wieder bei seiner Tochter sein, aber das ist unmöglich. Seine Seele wurde von der Geißel verdreht und er wurde zu einem Monster.\n\nPamelas Schicksal ist besiegelt, aber vielleicht können wir sein Schicksal ändern.\n\nEine komische Gnomin kam hier vor Kurzem am Turm an. Sie heißt Chromie. Bringt dieses Schwert zu ihr. Ich habe das Gefühl, dass sie uns helfen kann.", sourceObjective = "Bringt Josephs Jagdklinge zu Chromie.", progress = "Euer Besuch kommt gerade zur rechten Zeit. Ihr seid nicht aus der Zukunft, oder?", completion = "Was ist das? Ein Kriegsschwert? Ein Buttermesser? Ich habe keine Ahnung von Klingen. Lasst mich das genauer betrachten...\n\nAh! Dieses Schwert hat einst einem guten Mann gehört, aber in der Vergangenheit dieses Mannes ist viel Schlimmes passiert.\n\nSeid Ihr hier, um ihm zu helfen? Dafür ist es schon lange zu spät... aber vielleicht können wir ihm in der Vergangenheit helfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27387] = { id = 27387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bösewichte von Darroheim", description = "Die 'Annalen von Darroheim' berichten von den Bösewichten dieser Schlacht. Sie berichten, wie der Ghulfürst Horgus der Verheerer von Allianztruppen während der Schlacht vernichtet wurde. Er wurde im Vorgebirge nördlich von hier getötet und dort liegt sein Schädel noch heute.\n\nMarduk der Schwarze wurde nie besiegt, aber sein sagenhaftes Schwert verrostet nun herrenlos... Man kann es in der Nähe der Straße südöstlich von uns finden.\n\nStellt diese Gegenstände sicher, {name}. Ich weiß nicht, warum, aber ich bin sicher, dass ihr Schicksal in Euren Händen liegt.", sourceObjective = "Bringt den Schädel von Horgus und das zertrümmerte Schwert von Marduk zu Chromie am Turm der Kronenwache in den Östlichen Pestländern.", progress = "Habt Ihr den Schädel und das Schwert gefunden, {name}?", completion = "Ihr habt sie gefunden! Gut gemacht, {name}! Diese Relikte enthalten die Erinnerungen der Streitkräfte der Geißel, die in Darroheim gefallen sind. Diese werden wir brauchen, wenn wir Euren Joseph Rotpfad retten wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27388] = { id = 27388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helden von Darroheim", description = "Die Helden von Darroheim hatten ebenfalls Relikte und darin sind weitere wertvolle Erinnerungen gefangen. Sprecht zunächst mit Carlin und erhaltet die erweiterten Annalen von Darroheim. In diesem Folianten findet sich die Geschichte, die Eure Reise durch die Zeit führen wird.\n\nDanach müsst Ihr westlich reisen, um zu Marris' Siedlung zu gelangen. Der ehemalige Besitzer von Marris' Siedlung sammelte Relikte aus der Schlacht um Darroheim. Warum er das tat, kann ich nicht mit Sicherheit sagen. Sammelt diese Relikte und kehrt zu mir zurück.", sourceObjective = "Erhaltet die Erweiterten Annalen von Darroheim von Carlin Rotpfad sowie Davils Buchband und Rotpfads Schild in Marris' Siedlung.", progress = "Habt Ihr die Relikte, {name}?", completion = "Ihr habt die Relikte? Gut. Ich werde mich darum kümmern, etwaige zeitliche Störstellen zu korrigieren.\n\nSorgt Euch nicht... darüber müsst Ihr Euch wirklich keine Sorgen machen. Ihr seid nur für das Auffinden der Reagenzien zuständig.", sourceObjectiveStatus = "unverified-source-field" }
quests[27389] = { id = 27389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marodeure von Darroheim", description = "Ich benötige ein seltenes Reagenz für den mächtigen Zauberspruch, den zu wirken ich vorhabe: Schädel der Geißelschergen, die an der Schlacht von Darroheim teilnahmen.\n\nNehmt diesen Kristall und jagt Champions der Geißel, um an ihre Schädel zu gelangen. Der Kristall ist verzaubert: Er wird widerhallen, wenn Ihr ihn über den Schädel eines Champions haltet, der an der Schlacht teilgenommen hat. Bringt mir die Schädel der Krieger, bei denen der Kristall widerhallt.\n\nGeht, {name}. Ihr werdet die Champions der Geißel im Fungustal nördlich von hier finden. Geht.", sourceObjective = "Bringt 5 widerhallende Schädel zu Chromie am Turm der Kronenwache in den Östlichen Pestländern.", progress = "Habt Ihr die Schädel? Sie sind für den Zauber unglaublich wichtig. Mit ihrer Hilfe werden wir Darroheim retten können. Möglicherweise.", completion = "Ausgezeichnete Arbeit, {name}. Ihr habt so was wirklich noch nie gemacht?", sourceObjectiveStatus = "unverified-source-field" }
quests[27390] = { id = 27390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um Darroheim", description = "Nun, {name}, Ihr werdet an der Schlacht von Darroheim teilnehmen und Joseph Rotpfad retten.\n\nPlatziert dieses Reliktbündel auf dem Marktplatz von Darroheim und die Geister von Darroheim werden sich erheben. Nehmt an der Schlacht teil und sorgt dafür, dass die folgenden zwei Dinge eintreten: Davil muss den Tod von Horgus überleben und Rotpfad muss überleben, um erst verdorben und dann besiegt zu werden.\n\nNachdem Ihr den verderbten Rotpfad besiegt habt, wird seine Seele gerettet sein. Sprecht mit ihm und kehrt dann zu seiner Tochter Pamela zurück.", sourceObjective = "Legt das Reliktbündel auf den Marktplatz von Darroheim.\n\nVerhindert Davil Lichterscheins Tod, bis Horgus stirbt.\n\nVerhindert Hauptmann Rotpfads Tod, bis Rotpfad der Verderbte erscheint.\n\nBesiegt Rotpfad den Verderbten.\n\nSprecht mit dem Geist von Joseph Rotpfad, sobald er auf dem Marktplatz erscheint.", completion = "Der Kampf ist vorüber! Ich habe meinen Vater zu mir flüstern hören. Er hat alle Geister verjagt und sagt, dass er nach Hause kommt! Ich bin so froh!\n\nEr sagte außerdem, dass ich Euch willkommen heißen sollte, wenn Ihr zu uns nach Hause kommt, daher habe ich Euch etwas Tee zubereitet!\n\nIch hoffe, Ihr mögt ihn mit viel Zucker!", sourceObjectiveStatus = "unverified-source-field" }
quests[27391] = { id = 27391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versteckte Schätze", description = "Papa sagte, ich solle Euch diesen Schlüssel geben. Er sagte, er öffnet eine Truhe draußen hinter dem Haus.\n\nEr wollte außerdem, dass ich Euch danke. Habt Ihr ihm einen Gefallen getan? Habt Ihr ihm gesagt, dass Ihr meine Puppe gefunden habt?\n\nNun, hier ist jedenfalls der Schlüssel. Und habt Dank, {name}. Danke! Ihr seid <ein sehr netter Mann/eine sehr nette Dame>!", sourceObjective = "Bringt Josephs Schlüssel zu Josephs Truhe.", progress = "Diese Truhe ist alt und rußverschmiert.", completion = "Der Schlüssel passt in das Schloss und die Truhe öffnet sich...", sourceObjectiveStatus = "unverified-source-field" }
quests[27392] = { id = 27392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich soll Euch das eigentlich nicht verraten", description = "Mein Papa hat immer zwei Schwerter gehabt: eines für den Kampf und eines für die Jagd. Ich sollte eigentlich die Schwerter nicht anfassen, aber ich wusste, wo er sie versteckt.\n\nEines Tages hat er meiner Mama gesagt, dass er einen „einsamen Jäger“ in den Hügeln östlich von hier bekämpfen würde, aber er hat sein Schwert für die Jagd von Tieren mitgenommen! Als er zurückkam, hatte er kein Schwert bei sich.\n\nWenn Papa zurückkommt, wird er sich so freuen, wenn ich sein Jagdschwert für ihn habe! Könnt Ihr es für mich finden?", sourceObjective = "Erhaltet Josephs Jagdklinge von dem Einsamen Jäger in den Östlichen Pestländern.", progress = "Papa liebte seine Jagdklinge. Er wirkte traurig, als sie weg war.", completion = "Das ist Papas Schwert! Wie habt Ihr es gefunden? Habt Ihr den bösen Jäger gefunden?", sourceObjectiveStatus = "unverified-source-field" }
quests[27393] = { id = 27393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf der Klinge", description = "Ich spüre, wie eine starke Macht in den Ruinen nach mir ruft. Könntet Ihr noch einmal auf dem südlichen Schlachtfeld für mich nachsehen? Ich bin mir sicher, dass dort etwas sein muss.", sourceObjective = "Untersucht das Schlachtfeld am südlichen Ende der Ruinen von Vashj'ir.", completion = "Die Wellensprecherin hatte Recht. Da ist etwas.", sourceObjectiveStatus = "unverified-source-field" }
quests[27394] = { id = 27394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf der Klinge", description = "Ich spüre, wie eine starke Macht in den Ruinen nach mir ruft. Könntet Ihr noch einmal auf dem südlichen Schlachtfeld für mich nachsehen? Ich bin mir sicher, dass dort etwas sein muss.", sourceObjective = "Untersucht das Schlachtfeld am südlichen Ende der Ruinen von Vashj'ir.", completion = "Die Wellensprecherin hatte Recht. Da ist etwas.", sourceObjectiveStatus = "unverified-source-field" }
quests[27395] = { id = 27395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Waffe eines Schützen", description = "Ihr habt die Wege der Jäger schnell erlernt, {name}. Eure Fähigkeiten sind für die Horde äußerst wertvoll und Ihr seid beispielhaft für den Nachwuchs.\n\nAls Belohnung für Eure Fortschritte und Eure harte Arbeit hat der Kriegshäuptling bei seinem Bogenmacher die Herstellung einer besonderen Waffe in Auftrag gegeben.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und erlangt das Zielfernrohr von Lord Godfreys Gewehr, eine Ladung mondbestrahltes Holz und Sehnen der Ghule und Spuke, die die Burg heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und erhaltet Godfreys Kristallzielfernrohr, 5 Bündel mondbestrahltes Holz und 5 ewige Sehnen", progress = "Habt Ihr die Materialien besorgt, die ich für Eure Waffe benötige?", completion = "Ich fühle mich geehrt, dass der Kriegshäuptling mich beauftragt hat, eine Waffe für Euch herzustellen, {name}. Mit diesen fremdartigen Materialien wird es ein feiner Bogen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27396] = { id = 27396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klinge der Zerschmetterten Hand", description = "Viele Mitglieder der Zerschmetterten Hand überleben ihre Ausbildung nicht, {name}. Ihr habt nicht nur überlebt, sondern werdet bald auch eine gefürchtete Klinge für die Horde darstellen.\n\nAls Belohnung für Euren Fortschritt hat der Kriegshäuptling bei seinem eigenen Schmied eine Waffe in Auftrag gegeben.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und beschafft Euch Kommandant Grüntals Wetzstein, eine Ladung Mondstahlbarren, und Sehnen der Ghule und Spuke, die die Burg heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und erhaltet Grüntals Wetzstein von Kommandant Grüntal, 5 Kisten Mondstahlbarren und 5 ewige Sehnen.", progress = "Habt Ihr die Materialien besorgt, die ich für Eure Waffe benötige?", completion = "Gordul hat mir schon gesagt, dass Ihr eine Vielzahl ungewöhnlicher Materialien bringen würdet, aber mit so etwas habe ich nun wirklich nicht gerechnet. Mondstahl soll äußerst selten sein und es gibt nur einen Ort von dem ich weiß, an dem man es bekommen kann. Ihr habt für diese Waffe ein großes Risiko auf Euch genommen, {name}, und ich werde dafür sorgen, dass Ihr eine passende Belohnung bekommen werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[27397] = { id = 27397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Aufgabe eines Traumsuchers", description = "Die Elemente und Geister sprechen in klaren Stimmen zu Euch, {name}. Ihr seid ein mächtiges Mitglied in den Rängen der Schamanen und ein Beispiel für alle, die der Horde dienen möchten.\n\nSelbst der Kriegshäuptling hat von Euch erfahren, und er hat bei seinem Schmied die Herstellung einer besonderen Waffe für Euch in Auftrag gegeben.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und erlangt Lord Waldens Talisman, das Buch der verlorenen Seelen und Essenzen der Geister, die das Schloss heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und erhaltet den Talisman des Wolfmeisters von Wolfmeister Nandos, das Buch der verlorenen Seelen und 5 geisterhafte Essenzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27398] = { id = 27398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht ist gewonnen, der Krieg geht weiter", description = "Wir haben die Truppen des Feindes hier besiegt, {name}. Aber der Hyjal ist nicht der einzige Ort, an dem unsere Feinde gegen uns vorrücken.\n\nMan hat mir berichtet, dass unsere Verbündeten des Irdenen Rings in einer Angelegenheit um Hilfe gebeten haben, die keinen Aufschub duldet.\n\nErdsprecher Naraat am Östlichen Erdschrein in Sturmwind wird Euch weitere Anweisungen erteilen.", sourceObjective = "Sprecht mit Erdsprecher Naraat am Östlichen Erdschrein in Sturmwind.", completion = "Eure Hilfe kommt genau zur rechten Zeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27399] = { id = 27399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht ist gewonnen, der Krieg geht weiter", description = "Wir haben die Truppen des Feindes hier besiegt, {name}. Aber der Hyjal ist nicht der einzige Ort, an dem unsere Feinde gegen uns vorrücken.\n\nMan hat mir berichtet, dass unsere Verbündeten des Irdenen Rings in einer Angelegenheit um Hilfe gebeten haben, die keinen Aufschub duldet.\n\nScharfseher Krogar am Westlichen Erdschrein in Orgrimmar wird Euch weitere Anweisungen erteilen.", sourceObjective = "Sprecht mit Scharfseher Krogar am Westlichen Erdschrein in Orgrimmar.", completion = "Eure Hilfe kommt genau zur rechten Zeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27400] = { id = 27400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschung des Arkanen", description = "Alle Eure Lehrer sind sich einig, {name}, dass Ihr für einen Gesellen unglaubliches Talent zeigt. Selbst der Kriegshäuptling hat von Eurem schnellen Fortschritt gehört.\n\nAls Belohnung für Eurer Verständnis für das Erlernte hat der Kriegshäuptling bei seinem Verzauberkunstmeister die Herstellung eines besonderen Stabs in Auftrag gegeben.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und findet das magische Erbe der Familie Silberlein, etwas mondbestrahltes Holz und die Essenz der Geister, die die Burg heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und erlangt Silberleins verzauberten Kristall von Baron Silberlein, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27401] = { id = 27401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was uns morgen erwartet", description = "<Das K.d.V. summt.>\n\nSeht Euch im Kathedralenviertel um. Dort sollte irgendwo ein Teleskop sein, das die 7. Legion zur Beobachtung benutzt. Findet es und benutzt es, um den Hafen auszuspähen. Wir müssen herausfinden, wie die 7. Legion an unserer Flotte vorbeigekommen ist.\n\nBeeilt Euch, {name}. Wir können diese Bestien nicht sehr viel länger zurückhalten.\n\nWas uns morgen wohl erwartet?", sourceObjective = "Benutzt das Teleskop der 7. Legion, um den Hafen auszuspähen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27402] = { id = 27402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeichen der Macht", description = "Ihr erlernt unsere Wege in einem atemraubenden Tempo, {name}, und ich bin bei Weitem nicht der Einzige, der von Eurem Fortschritt beeindruckt ist. Der Kriegshäuptling selbst hat Eure Taten schon zur Kenntnis genommen.\n\nAls Belohnung für Eure Hingabe hat der Kriegshäuptling bei seinem eigenen Verzauberer die Herstellung eines Stabes in Auftrag gegeben.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und erlangt die finstere Kugel von Lord Godfrey, das Buch der verlorenen Seelen und Essenzen der Geister, die die Burg heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und erhaltet die Finstere Kugel von Lord Godfrey, das Buch der verlorenen Seelen und 5 geisterhafte Essenzen.", progress = "Habt Ihr die Materialien besorgt, die ich für Eure Waffe benötige?", completion = "Ihr seid also der Hexenmeister, für den dieser Stab ist. Es wird eine passende Belohnung für jemanden, der mit solcher Hingabe für den Machterlang und die Vorherrschaft der Horde kämpft.", sourceObjectiveStatus = "unverified-source-field" }
quests[27403] = { id = 27403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein echter Sonnenwandler", description = "Ich habe Eure Ausbildung beobachtet, {name}. Ihr habt den Weg eines beispielhaften Sonnenwandlers eingeschlagen und seid ein mutiger Verteidiger der Horde und ein Anhänger unserer Wege.\n\nAls Belohnung für Eure Hingabe hat der Kriegshäuptling bei seinem eigenen Schmied eine besondere Waffe in Auftrag gegeben.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und findet das heilige Symbol von Kommandant Grüntal, eine Ladung Mondstahlbarren und Sehnen der Ghule und Spuke, die die Burg heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und findet das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Kisten Mondstahlbarren, und 5 ewige Sehnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27404] = { id = 27404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zukunft des Zirkels", description = "Der Zirkel des Cenarius ist zufrieden mit Eurem Fortschritt, {name}. Ihr seid von Wert für alle Druiden. Wir sehen in Euch und Euren Verbündeten die Zukunft unserer Bruderschaft.\n\nDer Zirkel hat entschieden, Euch mit der Herstellung eines einzigartigen Stabs zu ehren.\n\nDie seltenen und mächtigen Materialien für diesen Stab können nur in Burg Schattenfang im Silberwald gefunden werden. Reist dorthin und findet Lord Waldens Elixiersammlung, eine Ladung mondbestrahltes Holz und Sehnen der Ghule und Spuke, die die Burg heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und erhaltet Waldens Elixiere von Lord Walden, 5 Bündel mondbestrahltes Holz und 5 ewige Sehnen.", progress = "Habt Ihr die Materialien besorgt, die ich für Euren Stab benötige?", completion = "Ah, Ihr müsst der {class} sein, von dem Loganaar erzählt hat. Ich freue mich, Euch endlich zu treffen, {name}. Ich habe schon oft gehört, wie Mitglieder des Zirkels Euch als talentiert und vielversprechend für die Reihen der Druiden halten, und ich freue mich, dass ihre Einschätzungen auch der Wahrheit entsprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27405] = { id = 27405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückzug!", description = "<Das K.d.V. summt.>\n\n<Im Hintergrund ist Worgengeheul zu vernehmen.>\n\n{name}, hört Ihr mich? Kommen, {name}. Das ist wahrscheinlich meine letzte Übertragung. Die Worgen haben den Gefechtsstand der Verlassenen überrannt. Es ist nur eine Frage der Zeit, bis wir den Stützpunkt verlieren. Belmont und die Val'kyr Arthura sind weg. Belmont meinte, er wird Euch in Glutstein treffen, nordöstlich von hier. Findet Belmont, {name}. Unsere Mission - unsere Existenz - hängt davon ab.\n\nIhr seid unsere letzte Hoffnung.", sourceObjective = "Findet Todespirscherkommandant Belmont in Glutstein in den Ruinen von Gilneas.", completion = "Vorpostenkommandant Ansturm hat bis zum bitteren Ende gekämpft, {name}. Erst eine Meute blutdurstiger Worgen konnte ihn niederringen. Sein Tod und der Tod all unserer Soldaten in Gilneas darf nicht umsonst gewesen sein. Unsere Mission MUSS gelingen.\n\nJetzt werde ich Euch enthüllen, warum wir hier sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[27406] = { id = 27406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Mann namens Godfrey", description = "Lord Vincent Godfrey hat sein Leben mit der Verteidigung des Königreich Gilneas verbracht. Als der Fluch der Worgen sein Land verheerte, war Godfrey der Erste in Gilneas, der die Waffen gegen die Bestien erhob. Es wird gesagt, dass Godfrey sein Leben nahm, als er herausfand, dass sein König dem Fluch zum Opfer gefallen war. Lieber sei er tot, als dass er den Kreaturen diene, gegen die er sein Land verteidigt hatte.\n\nWir werden ihm eine zweite Chance geben, {name}. Zusammen werden wir die Schlacht nach Südosten vorantreiben, nach Witterfront, und dort seinen Leichnam einholen.", sourceObjective = "Findet die Leiche von Lord Vincent Godfrey.", completion = "Hier, {name}. Er ist ein wenig verfault, aber es könnte schlimmer sein. Wir müssen uns beeilen, bevor die Allianz uns findet!", sourceObjectiveStatus = "unverified-source-field" }
quests[27407] = { id = 27407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutsumpffedern", description = "Hat Euch Broggs Anwesenheit erschreckt, {race}? Sorgt Euch nicht. Die Goblins von Morastwinkel sind Broggs Freunde und Ihr könnt es auch werden.\n\nBrogg hat Brackenwall verlassen, nachdem der neue Oberanführer nicht Rache an den Drachkin geübt hatte, die für Zerstörung unserer alten Heimat und Tod vieler alter Freunde von Brogg verantwortlich sind. Brogg ist hierhergekommen, um Geister seiner Freunde zur letzten Ruhe zu betten und für sie Rache zu üben, doch Brogg braucht Hilfe bei Vorbereitungen. Für Ritual braucht Brogg Federn mit mächtiger Magie, Federn wie die der Raptoren aus Blutsumpfbau.", sourceObjective = "Sammelt 5 Blutsumpffedern von Blutsumpfraptoren.", progress = "<Brogg blickt Euch voller Hoffnung an.>\n\nIhr bringt Brogg Federn?", completion = "<Brogg nimmt die Federn an sich.>\n\nBrogg froh über die Federn. Sehr mächtige Magie. Brogg weiß nicht, wie Raptoren Federn Macht geben, aber Raptorenfedern immer am besten für Ritual.", sourceObjectiveStatus = "unverified-source-field" }
quests[27408] = { id = 27408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Banner der Steinbrecher", description = "Als die Drachen über Broggs alte Heimat herfielen, flohen die Steinbrecheroger und ließen alles zurück, sogar das Klanbanner.\n\nBrogg weiß, dass das Banner tief im Ogerhort aufbewahrt wurde. Jetzt heißt der Ort Flammenbau.\n\nBrogg braucht Klanbanner für seine Rache an den Drachen, die seine Freunde auf dem Gewissen haben. Der alte Hort von Broggs Klan, der Flammenbau, befindet sich nordwestlich von Morastwinkel und überall treiben sich Drachkin herum. Banner ist tief in der Höhle. Seid vorsichtig, {name}.", sourceObjective = "Beschafft das Banner der Steinbrecher aus Flammenbau.", progress = "Ihr bringt Banner der Steinbrecher?", completion = "Brogg dankt Euch, {name}. Brogg hat große Pläne für Klanbanner.", sourceObjectiveStatus = "unverified-source-field" }
quests[27409] = { id = 27409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Essenz der Feindschaft", description = "Damit Brogg das Totem für sein Ritual herstellen kann, benötigt er die Essenzen der Kreaturen, die seine Freunde getötet haben. Der Hass und die Wut von Broggs Feinden wird die Magie seiner Rache verstärken.\n\nTötet Aschenschweife, Späher oder Bannschuppen der Feuermähnen und wendet Broggs Totem auf ihren Leichen an. Nur tote Drachkin geben ihre Essenzen frei.\n\nDie Kreaturen, die Ihr sucht, befinden sich im Flammenbau im Nordwesten und in den Ruinen der Steinbrecher im Norden.", sourceObjective = "Bringt 10 Essenzen eines schwarzen Drachkin zu Brogg in Morastwinkel.", progress = "Habt Ihr die Essenzen? Brogg braucht sie, um seine Freunde zu rächen!", completion = "Brogg dankt Euch, {name}. Sobald Brogg die Magie der Essenzen zu dem Totem hinzufügt, kann das Totem die Geister von Broggs gefallenen Freunden befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[27410] = { id = 27410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geister der Festung der Steinbrecher", description = "Brogg hat das Totem fertig gestellt, mit dem den Geistern seiner Freunde Frieden gegeben werden kann. Als die Drachkin einfielen, töteten sie alle Steinbrecher, die nicht rechtzeitig fliehen konnten. Brogg entkam zusammen mit Oberanführer Mok'Morokk, in der Hoffnung auf einen gemeinsamen Gegenangriff mit den anderen überlebenden Steinbrechern.\n\nDoch der Gegenangriff fand nie statt und die Geister der Gefallenen verfolgen Brogg und die anderen noch immer. Nehmt das Totem und begebt Euch zu den Ruinen der Steinbrecher nördlich von hier; verwendet das Totem in der Nähe von Ogerskeletten, um die Geister anzulocken. Besiegt die Geister und ermöglicht ihnen und ihren Knochen die letzte Ruhe.", sourceObjective = "Gebt 10 Geistern der Steinbrecher bei den Ruinen der Steinbrecher ihre letzte Ruhe.", progress = "Brogg muss wissen, habt Ihr den brutalen Geistern der Steinbrecher Frieden geben können?", completion = "Brogg dankt Euch für Eure Hilfe, obwohl er weiß, dass Oberanführer Mok'Morokk nicht dankbar sein wird. Jetzt können Überlebende der Steinbrecher endlich Probleme der Lebenden lösen und die Toten hinter sich lassen. Brogg muss nur noch eine Sache machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27411] = { id = 27411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderung für den schwarzen Drachenschwarm", description = "Brogg kann es kaum erwarten, endlich Rache an dem schwarzen Drachenschwarm der Marschen zu üben. {name}, Ihr habt bei den Vorbereitungen für diesen Augenblick sehr geholfen. Werdet Ihr mir auch weiterhin zur Seite stehen?\n\nNehmt Broggs Klanbanner und reist in Richtung Osten, bis Ihr eine Höhle seht, die wie das Maul eines Drachen aussieht. Stellt das Banner der Steinbrecher direkt vor dem Höhleneingang auf und überbringt Onyxia Broggs Herausforderung.\n\nBrogg und die Steinbrecher werden ihr Land zurückerlangen!", sourceObjective = "Platziert das Banner der Steinbrecher am Eingang zu Onyxias Hort und besiegt alle, die reagieren.", progress = "Brogg wird seine Rache üben können!", completion = "<Brogg hört Euch zu, als Ihr von den Erlebnissen am Eingang zu Onyxias Hort berichtet.>\n\nBrogg weiß Onyxia tot. Brogg weiß Onyxias Brut noch da. Brogg lässt sie Steinbrecher niemals vergessen.\n\nBrogg ist dankbar für Eure Hilfe, {name}, und wird nie vergessen, was Ihr für ihn getan habt. Brogg wird nicht ruhen, bis er die Steinbrecher wieder in ihre Heimat gebracht hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[27412] = { id = 27412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Schlächterklaue der Gefräßige", description = "Reisende und Mitarbeiter des Dampfdruckkartells werden aufgefordert, Blutsumpfbau westlich der Siedlung weiträumig zu umgehen.\n\nDas gesamte Areal wird von äußerst gefährlichen Raptoren bewohnt. Das Leittier, Schlächterklaue der Gefräßige, ist für den Tod von mindestens zwei Ingenieuren des Dampfdruckkartells verantwortlich.\n\nDrazzit Tropfhahn hat eine großzügige Belohnung ausgeschrieben, die ausgezahlt wird, wenn der Bedrohung durch Schlächterklaue in Morastwinkel ein Ende gesetzt wird.", sourceObjective = "Tötet Schlächterklaue den Gefräßigen und meldet Euch bei Drazzit Tropfhahn in Morastwinkel.", completion = "Zum Glück ist endlich jemand meiner Aufforderung nachgekommen. Ich dachte schon, dass ich die Belohnung verdreifachen müsste, bevor jemand diesen verdammten Raptor zur Strecke bringt, und das ließ unser Budget einfach nicht zu!", sourceObjectiveStatus = "unverified-source-field" }
quests[27413] = { id = 27413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entwindet den Drachen", description = "Durch den Absturz des Zeppelins mitsamt unseren Vorräten gehen uns langsam die Medikamente und Verbände aus.\n\nWir tun was wir können, aber inmitten all dieser Insekten, umgeben von Feinden bleiben Verletzungen nicht aus, und ich komme meiner Arbeit kaum nach! Ich habe kürzlich eine Pflanze entdeckt, welche die Wundheilung unterstützt und Schmerzen lindern kann, doch auch dieser Vorrat geht zur Neige.\n\nDie Pflanze heißt Drachenwinde und sie wächst in Drachendüster und in Drachensumpf östlich von unserer Siedlung. Die Pflanze besteht aus gewundenen Stängeln und wenn man sie ansieht, scheint sie zu pulsieren.", sourceObjective = "Sammelt 8 Stängel der Drachenwinde in Drachendüster oder in Drachensumpf.", progress = "Konntet Ihr die Drachenwinde finden?", completion = "Vielen Dank! Damit kann ich unsere Jungs versorgen, bis Moxie mit den Vorräten von der Zeppelinabsturzstelle zurückkommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27414] = { id = 27414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brut identifizieren", description = "Während der törichte Narr Mok'Morokk seine Macht genießt und Tharg mit den Dämonen des Kummers und der Rache ringt und um die Führerschaft des Klans buhlt, scheine ich der Einzige zu sein, der die Ursache der Aggression in unserer alten Heimat herausfinden möchte.\n\nWarum der verwirrte Blick, {name}? Habt Ihr erwartet, dass ich wie ein tumber Grobian spreche, nur weil ich ein Oger bin?\n\nWidmen wir uns wieder dem wichtigeren Thema: Bringt mir die Herzen und Zungen der Welpen und Jungtiere. Ich werde herausfinden, was es mit diesem Übel auf sich hat ...", sourceObjective = "Draz'Zilb in Brackenwall möchte, dass Ihr ihm 7 sengende Zungen und 7 sengende Herzen bringt.", progress = "An den Herzen und der Zungen der versengten Nachkommen der Armee der schwarzen Großdrachen kann ich erkennen, von welcher Bestie sie abstammen. Wenn wir mehr über unsere Angreifer wissen, können wir sie vielleicht besser bekämpfen und sie ein für alle Mal zerstören, und die Siedlung der Steinbrecher aus den Ruinen retten.\n\nAllerdings wird es schon eine wahrhaft epische Aufgabe, Mok'Morokk davon zu überzeugen, seinen lethargischen Hintern aus dem Schlammloch zu bewegen ...", completion = "Zweifellos war es eine gefährliche Sache, diese Herzen und Zungen zu sammeln. Ich werde nun in die Tiefen des Arkanen vorstoßen, um den Ursprung der schwarzen Bedrohung zu finden, die über unsere einstige Heimat kam.", sourceObjectiveStatus = "unverified-source-field" }
quests[27415] = { id = 27415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brut von Onyxia", description = "Onyxias Brut wurde über ganz Drachendüster verstreut. Es dürfen auf keinen Fall weitere Welpen schlüpfen.\n\nEilt nach Drachensumpf im Süden von Düstermarschen. Gewiss hat sie dort ihren Hort angelegt. Sucht die Eier der bösen Großdrachen und vernichtet sie.\n\nWir werden das Dorf der Steinbrecher nie zurückerobern können, wenn das Umland eine Brutstätte bleibt.\n\nWas Mok'Morokk angeht ... für den Jammerlappen habe ich andere Pläne.", sourceObjective = "Zerstört 5 Eier von Onyxia.", completion = "Großartig! Es wird einige Zeit dauern, bis Onyxia wieder Eier legen kann.\n\nIm Namen meines Volkes danke ich Euch, {name}.\n\nIch habe bislang viel von Euch verlangt. Vielleicht könnt Ihr jedoch dem Steinbrecherklan einen letzten Dienst erweisen.\n\nMok'Morokk ist nicht in der Lage, uns anzuführen. Tharg wäre ein ausgezeichneter Anführer, sieht sich aber durch seine Verletzungen und sein Alter daran gehindert. Vertreibt Mok'Morokk mit Gewalt von hier. Erst dann können wir einen neuen Anführer bestimmen und in unsere angestammte Heimat im Süden zurückkehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[27416] = { id = 27416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brut von Onyxia", description = "Das Dorf der Steinbrecher wurde von Onyxias Brut überfallen. Aber warum sollte die Tochter des schwarzen Drachenlords Todesschwinge über unser Land herfallen?\n\nEs ist äußerst beunruhigend. Sicherlich wurde Onyxia aus einem anderen Grund hergeschickt, als nur eine kleine Schar von Ogern zu belagern.\n\nVerständigt Mok'Morokk auf der Stelle! Es muss etwas getan werden.", sourceObjective = "Sprecht mit Oberanführer Mok'Morokk in Brackenwall.", completion = "Warum erzählt Ihr mir von Drachen? Ich mag Drachen nicht. Ich mag es hier. Hier keine Drachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27417] = { id = 27417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brut von Onyxia", description = "Lasst mich jetzt allein. Sagt Draz'Zilb, dass ich hier bleibe. Hier keine schwarzen Großdrachen.", sourceObjective = "Sprecht mit Draz'Zilb in Brackenwall.", completion = "Dieser träge Feigling!\n\nMok'Morokk hat Stärke gezeigt, als Rexxar noch unser Anführer war. Doch kurz nach Rexxars Abschied erlag Mok'Morokk den Verlockungen der Macht. Er führte nicht, sondern forderte. Er dient seinem Volk nicht, sondern erwartet, dass wir ihm dienen.\n\nEs muss etwas geschehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27418] = { id = 27418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fordert Oberanführer Mok'Morokk heraus", description = "Ihr wagt es, Oberanführer Mok'Morokk herauszufordern?\n\nHa!\n\nIch zerschmettern Winzling von {race}!\n\nIhr sagt mir, wenn bereit für ordentliche Tracht Prügel.", sourceObjective = "Besiegt Mok'Morokk und erstattet Draz'Zilb in Brackenwall Bericht.", completion = "Dieser feige Fettwanst Mok'Morokk ist geflohen wie ein ängstliches Kind. Ihr habt uns einen großen Dienst erwiesen, {name}.\n\nJetzt kann mein Volk einen neuen Anführer bestimmen, mit dem wir unsere angestammte Heimat ein für alle Mal zurückerobern werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27419] = { id = 27419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armee des schwarzen Großdrachen", description = "Mok'Morokk wurde von Rexxar zum Oberanführer gemacht. Ihm liegt mehr an Macht als an den Ogern.\n\nSchwarze Großdrachen töten viele Oger. Töten Thargs Frau. Mok'Morokk sagt uns, wir müssen fliehen. Lässt uns hierher kommen.\n\nOger sollten kämpfen. Oger nicht gut im Weglaufen. Mok'Morokk schert sich nur um Mok'Morokk.\n\nFür mich die Ruinen der Steinbrecher Heimat. Mir gefallen im Süden. Dieser Ort nicht Heimat.\n\nHelft Ogern, Armee der schwarzen Großdrachen zu bekämpfen. Ich wollen Rache. Ich wollen nach Hause.", sourceObjective = "Tharg in Brackenwall möchte, dass Ihr 10 Späher der Feuermähnen, 10 Aschenschweife der Feuermähnen und 5 Bannschuppen der Feuermähnen tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[27420] = { id = 27420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Unvermeidliche hinauszögern", description = "Ihr habt ein gutes Auge, wenn Ihr mich hier in meinem Versteck im Gras sehen konntet.\n\nDas Fungustal liegt vor uns, eine Gegend, an die sich die Geißel noch immer klammert. Sie benutzen schwebende Konstrukte, um das Land ständig neu zu verseuchen, damit es so abstoßend bleibt, wie es jetzt ist.\n\nDie Konstrukte werden von Runen der dunklen Adepten und der Schattenmagier gesteuert. Nehmt die Kontrollrunen der Kultisten an Euch, zielt damit auf die Seuchenverbreiter und erzeugt mit diesem Partikel eine Überlast. Das Ergebnis sollte recht amüsant sein.", sourceObjective = "Erhaltet Kontrollrunen von den dunklen Kultisten und Schattenmagiern und benutzt das überladene Partikel, um 3 Seuchenverbeiter zu zerstören.", completion = "Je eher die Geißel aus dem Fungustal vertrieben ist, desto eher können wir es heilen.\n\nVielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27421] = { id = 27421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mitten im Tod ist Leben", description = "Die Streitmächte der Geißel haben es geschafft, jeglichem Leben im Fungustal ein Ende zu bereiten. Das Einzige, was noch zu finden ist, sind die Überreste verfaulter Pilze und versengte Gräser. In den drei Ecken des Tals sind drei große Ziggurats zu finden, in denen die Geißel ihre Toten reanimiert und neue Soldaten für das Schlachtfeld einberuft.\n\nDoch selbst an diesem bösen, leblosen Ort kann Leben gedeihen. Nehmt diese Samen und planzt sie in die Zentren der Ziggurats. Beweist ihnen, dass sich das Leben durchsetzen wird.", sourceObjective = "Pflanzt Raynes Samenkörner in den Zentren der drei Ziggurats im Fungustal.", completion = "Selbst wenn die Blumen verwelkt sind, kurz nachdem sie geblüht haben, wird das der Geißel eines klarmachen: sie verlieren und wir gewinnen.\n\nVielen Dank für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[27422] = { id = 27422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Stadt unter Belagerung", description = "Wir werden die Östlichen Pestländer nie unter Kontrolle bekommen, wenn wir Stratholme nicht im Besitz haben. Stratholme ist nicht nur ein strategisch unglaublich wichtiger Ort, sondern auch die Heimat der Anführer unserer Feinde - Balnazzar und Baron Aurius Totenschwur. Ihre Armeen der Auferstandenen und der Geißel drohen jedoch, alle unsere Fortschritte nichtig zu machen.\n\nDer Argentumkreuzzug ist wie geschaffen, sich dieser Aufgabe anzunehmen. Reist nach Westen, betretet Stratholme durch das Haupttor, und sprecht mit Rottenkommandant Steinberster. Er wird Euch weitere Anweisungen geben.", sourceObjective = "Sprecht mit Rottenkommandant Steinberster.", completion = "Welch eine Erleichterung einen tauglichen Soldaten an unserer Seite zu haben. Hier gibt es genug für Euch zu tun, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27423] = { id = 27423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Widerstand ist zwecklos", description = "<Das K.d.V. summt.>\n\nHier spricht Kommandantin Lorna Crowley von der Gilnearischen Befreiungsfront. Wenn Ihr diese Nachricht hört, bedeutet das, dass die Allianz Gilneas wieder eingenommen hat. Legt Eure Waffen nieder und kapituliert. Wenn Ihr dieser Aufforderung nicht nachkommt, steht Euch der sichere Tod bevor.\n\nUnsere Streitmächte sind über Euren Standort informiert und werden in Kürze eintreffen. Widerstand ist zwecklos.", sourceObjective = "Tötet 20 Kämpfer der Worgen.", completion = "Wir haben keine Zeit, um uns am Ruhm der Schlacht zu laben, {name}. Es gibt Arbeit. Ich bin mir sicher, dass noch mehr von diesen Biestern unterwegs sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[27424] = { id = 27424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oberanführer Mok'Morokks Sorgen", description = "Verbeugen Euch vor Oberanführer Mok'Morokk!\n\nRexxar mich machen zu mächtigem Anführer von Steinbrecherklan!\n\nIch guter Anführer. Ich auf Klan aufpasse.\n\nGroße Drachen machen Feuer in alte Heimat. Ich schlauer Oger. Finden neue Heimat für Klan hier.\n\nAber alte Heimat so schnell verlassen, ich Sachen vergessen. Winzig {race}, gehen mein Sachen holen. Gehen nach Süden und suchen mein lecker Grog, Schnupftabak und Geldkassette. Ich Euch dann mögen. Ihr in Flammenbau und Ruinen der Steinbrecher schauen ... alles dort sein, ich sicher!", sourceObjective = "Holt Oberanführer Mok'Morokks Grog, Mok'Morokks Schnupftabak und Mok'Morokks Geldkassette aus Düstermarschen.", progress = "Ich Durst auf Grog. Und Lust auf Schnupftabak. Wo ist Geldkassette? Ihr geht holen für Oberanführer Mok'Morokk.\n\nGeht holen in Süden in alter Heimat. Ich mit Anführen von Ogern beschäftigt.", completion = "Gut, {race}. Ich haben Sachen arg vermisst. Ich Euch jetzt mag.", sourceObjectiveStatus = "unverified-source-field" }
quests[27425] = { id = 27425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der entscheidende Grimmweis", description = "Ich habe mich mit Inspektor Tarem über die Beweise, die Ihr bei den Ruinen des Gasthauses \"Zur Süßen Ruh\" gefunden habt, unterhalten. Er ist sich sicher, dass die Hufabdrücke und der Schild auf den Taurenklan der Grimmtotem hindeuten.\n\nBedenkt man die jüngsten Berichte über die zunehmenden Aktivitäten der Grimmtotem in den Marschen, so handelt es sich sicherlich nicht um einen bloßen Zufall. Ich bitte Euch, mit Hauptmann Darill zu sprechen. Er ist so eine Art Experte in Sachen Grimmtotem. Folgt der Straße aus dem Dorf in Richtung Norden nach Nordwacht. Es ist der zweite Außenposten entlang der Straße.", sourceObjective = "Berichtet Hauptmann Darill in Nordwacht.", completion = "Hauptmann Mumm meint, die Grimmtotem stecken hinter dem Angriff auf das Gasthaus \"Zur Süßen Ruh\"? Auf meiner Verdächtigenliste wären sie jetzt nicht weit oben, aber wenn Hauptmann Mumm Euch schickt, um einem Hinweis zu folgen, hat er sicherlich gute Gründe. Davon aber abgesehen, die Grimmtotem sind uns schon seit einiger Zeit ein Dorn im Auge und wir sind immer über zusätzliche Hilfe dankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[27426] = { id = 27426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bestätigung des Verdachts", description = "Die Grimmtotem mögen der kriegerischste Klan der Tauren sein, aber sie sind keineswegs unorganisiert. Wenn sie das Gasthaus \"Zur Süßen Ruh\" wirklich in Brand gesteckt haben, dann nur auf Befehl von einem der Klanältesten.\n\nNordwestlich von hier liegt eine große Siedlung der Grimmtotem, das Dorf der Schwarzhufe. Sie haben das Dorf als Ausgangsbasis für ihre Angriffe auf den Turm genutzt, aber ich bin mir ganz sicher, dass Ihr dort auch die Befehle finden könnt. Sucht bei den Ältesten im Dorf nach den Befehlen, die Ihr für Eure Ermittlungen benötigt.", sourceObjective = "Erlangt 4 Notizen der Grimmtotem von den Ältesten der Grimmtotem. Setzt die Teile zusammen, um die Schlachtpläne der Grimmtotem zu sehen.", progress = "Konntet Ihr die Befehle ausfindig machen?", completion = "<Hauptmann Darill überfliegt die Schlachtpläne.>\n\nIch glaube, deutlicher kann es kaum werden. Sie haben es sich zur Aufgabe gemacht, die Menschen aus den Siedlungen in der Gegend zu vertreiben. Ich bezweifle nicht, dass Theramore ihr nächstes Ziel sein wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[27427] = { id = 27427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen der Grimmtotem", description = "Wenn die Ausrüstung, die Ihr bei den Ruinen des Gasthauses gefunden habt, zu einem Angriffstrupp der Grimmtotem gehörte, dann gibt es vermutlich noch mehr davon in ihrem Lager nordwestlich von hier.\n\nBis jetzt konnten wir noch nicht viel über das Dorf der Schwarzhufe in Erfahrung bringen, aber ausgehend von der Größe ihrer Angriffstrupps schätzen wir, dass sich dort eine größere Streitmacht aufhält.\n\nTut, was auch immer Ihr tun müsst, um einige ihrer Ausrüstungsgegenstände zu erbeuten, damit wir sie mit Eurem Fund beim Gasthaus vergleichen können.", sourceObjective = "Hauptmann Darill in Nordwacht möchte, dass Ihr ihm 7 Waffen der Schwarzhufe bringt.", progress = "Habt Ihr diese Waffen aus dem Dorf der Schwarzhufe?", completion = "<Hauptmann Darill betrachtet die Waffen, die Ihr aus dem Dorf der Schwarzhufe mitgebracht habt.>\n\nEs gibt keine Zweifel mehr. Diese Waffen stimmen genau mit der Beschreibung überein. Es gibt nur ein Problem - mit diesen Waffen wurde noch nie gekämpft. Das Dorf der Schwarzhufe ist wohl nicht der einzige Posten der Grimmtotem in den Marschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27428] = { id = 27428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tabethas Unterstützung", description = "Ich kann keine Männer mehr entbehren, um Euch bei der Suche nach einem zweiten Außenposten der Grimmtotem zu helfen. Ich kenne aber jemanden, der Euch behilflich sein könnte.\n\nTief im Morast, südlich von hier, liegt ein kleiner Hof, der Tabetha gehört. Sie mag zwar wie eine alte Einsiedlerin erscheinen, aber in Wirklichkeit ist sie eine Magierin und recht angesehene Wahrsagerin. Folgt der Straße in Richtung Süden bis zu ihrem Hof und bittet sie um Hilfe bei der Suche nach den Übeltätern, die für das Massaker beim Gasthaus \"Zur Süßen Ruh\" verantwortlich sind.", sourceObjective = "Sprecht mit Tabetha auf ihrem Hof.", completion = "Ihr möchtet also, dass ich die Grimmtotem durch meine Weissagungen ausfindig mache, ja? Was würdet Ihr sagen, wenn ich Euch verrate, dass es keinerlei Weissagung dafür bedarf?", sourceObjectiveStatus = "unverified-source-field" }
quests[27429] = { id = 27429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennt den Grollhornposten nieder!", description = "Man muss nicht Hellsehen können, um zu wissen, welche Schwierigkeiten meine neuen \"Nachbarn\" hier heraufbeschwören. Falls es sich bei ihnen wirklich um diejenigen handelt, die das Gasthaus \"Zur Süßen Ruh\" niedergebrannt haben, dann gibt es keinen Grund mehr, sie hier noch länger zu dulden.\n\nNehmt diese Fackel und brennt ihr Lager nieder! Der Grollhornposten liegt nördlich von meinem Hof, in der Nähe der Straße. Ihr könnt ihn nicht verfehlen, wirklich. Die Grimmtotem haben ganze Arbeit geleistet und ihre Anwesenheit durch das Aufstellen ihrer Totem förmlich angekündigt.", sourceObjective = "Benutzt Tabethas Fackel, um das nördliche Zelt, das östliche Zelt und das nordöstliche Zelt am Grollhornposten in Flammen zu setzen.", progress = "Hat die Fackel ihren Zweck erfüllt?", completion = "Ich hoffe, die Grimmtotem haben unsere Nachricht verstanden. Jeder Rückkehrversuch wird mit schlimmeren Mitteln als einer Fackel beantwortet werden. Meine Lehrlinge und ich werden uns der Sache annehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27430] = { id = 27430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerechtigkeit im Namen der Familie Hyal", description = "Für mich waren die Grimmtotem zwar lediglich eine Belästigung, aber dennoch sollte Hauptmann Mumm von Euren Taten erfahren. Berichtet ihm, dass Ihr diejenigen, die für den Anschlag auf das Gasthaus \"Zur Süßen Ruh\" verantwortlich sind, gefunden und bestraft habt.\n\nEs ist zwar zu spät, um die Familie von Jim Hyal zu retten, aber vielleicht denken die Grimmtotem das nächste Mal zweimal nach, bevor sie jemanden aus Theramore angreifen.", sourceObjective = "Sprecht mit Hauptmann Garran Mumm bei der Wehrzitadelle in Theramore.", completion = "<Der Hauptmann hört sich Euren Bericht sorgfältig an.>\n\nWir haben James und seine Familie zwar gerächt, aber nicht einmal das kann wieder gut machen, was zerstört wurde.", sourceObjectiveStatus = "unverified-source-field" }
quests[27431] = { id = 27431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus dem Gleichgewicht gebracht", description = "<Harrison grinst.>\n\nDas ist es, {name}. Die Teile, die wir brauchen, sind in diesen Statuen versteckt!\n\nSie sehen aus, als wären sie sowieso ein wenig aus dem Gleichgewicht... Ein kleiner Stupser vielleicht...\n\nEure Untersuchungen schreiten ordentlich voran, muss ich sagen. Wenn Ihr Euch bewerben würdet, könnte aus Euch eines Tages <ein feiner Archäologe/eine feine Archäologin> werden.", sourceObjective = "Sprecht mit Harrison Jones in der Kammer der Sterne.", progress = "Was habt Ihr gefunden, {name}?", completion = "Wo wir gerade bei \"Häuser einreißen\" sind...", sourceObjectiveStatus = "unverified-source-field" }
quests[27432] = { id = 27432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zaeldarr der Ausgestoßene", description = "Könnt Ihr Euch vorstellen, dass wir uns nach dem ganzen Ärger in den Pestländern... jetzt auch noch um Diebe sorgen müssen? Nicht einfach gewöhnliche Diebe, Trolldiebe.\n\nUnd nicht einfach gewöhnliche Trolldiebe. Tote Trolldiebe!\n\nSie werden von diesem großen toten Troll namens Zaeldarr dem Ausgestoßenen angeführt, kommen nachts hierher und stehlen Leichen von unseren Friedhöfen. Dann schaffen sie sie zu ihrem üblen Versteck für tote Trolle - dem Tiefgewölbe im Südwesten.\n\nGeht dorthin und schaltet Zaeldarr aus, {name}. Ich habe seine Schandtaten satt!", sourceObjective = "Besorgt Zaeldarrs Kopf von Zaeldarr dem Ausgestoßenen.", progress = "Habt Ihr das Versteck gefunden, {name}? Habt Ihr Zaeldarr ausgeschaltet?", completion = "Sehr schön, Ihr habt ihn! Und ich hoffe, Ihr habt auch seiner Bande eine Lektion erteilt!", sourceObjectiveStatus = "unverified-source-field" }
quests[27433] = { id = 27433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schredderektomie", description = "Unsere Panzer müssen zurückgezogen werden, und das bedeutet, dass wir Arbeiten auf dem Schlachtfeld verrichten müssen.\n\nZerstört ein paar von den Diamantklingenschreddern, die diese kleinen Monster benutzen, um die Bäume an der Küste zu fällen, und bringt mir einen Haufen der Schredderteile, die noch verwendbar sind. Wir basteln damit etwas, um die Panzer wieder einsatzbereit zu machen.", sourceObjective = "Zerstört Diamantenklingenschredder, um 5 misshandelte Schredderteile zu erlangen.", progress = "Was habt Ihr für mich, {name}?", completion = "Oha, das ist gutes Zeug! Ein guter Ingenieur kann alles machen, wenn er nur ein paar gute Sachen hat.\n\nDieses Dingens hier könnte an eine kaputte Zylinderhülse gekoppelt werden ... Oh! Und wer freut sich nicht über ein solches Dingsbums? ... Und aus diesem Gedöhns hier kann man auf jeden Fall ein ... Ding machen!\n\n<Flintlocke steckt eines der schmierigen Maschinenteile in den Mund.>\n\nJupp, perfekt!", sourceObjectiveStatus = "unverified-source-field" }
quests[27434] = { id = 27434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad der Adepten", description = "Eure Lehrlingszeit neigt sich dem Ende zu, {name}. Ihr seid bereit, den Rang Adept innezuhalten und ein richtiger Blutritter im Dienste Silbermonds zu werden.\n\nUm Eure Leistungen zu ehren, hat der Kriegshäuptling bei seinem Schmied die Herstellung einer Waffe für Euch in Auftrag gegeben.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und findet das verlorene heilige Symbol von Kommandant Grüntal, eine Ladung Mondstahlbarren und Sehnen der Ghule und Spuke dort.", sourceObjective = "Reist nach Burg Schattenfang und findet das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Kisten Mondstahlbarren, und 5 ewige Sehnen.", progress = "Habt Ihr die Materialien besorgt, die ich für Eure Waffe benötige?", completion = "Ich weiß nicht, wie Ihr solche Mengen Mondstahl auftreiben konntet, {name}. Ich habe schon seit Jahren nicht mehr damit gearbeitet. Es wird sowohl eine Herausforderung als auch eine Freude sein, diese Waffe für Euch zu schmieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27435] = { id = 27435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stab eines Sehers", description = "In den Augen der Erdmutter seid Ihr bereit, den Rang des Sehers zu erlangen. Ihr habt Eure Grundausbildung mit Können und Hingabe absolviert.\n\nZu diesem Anlass hat der Kriegshäuptling bei seinem Verzauberkunstmeister die Herstellung eines Stabs für Euch in Auftrag gegeben.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und findet das verlorene heilige Symbol von Kommandant Grüntal, etwas mondbestrahltes Holz und die Essenz der Geister, die die Burg heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und erhaltet das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27436] = { id = 27436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Aufgabe des Schattenläufers", description = "Dies ist ein besonderer Anlass, {name}. Ihr habt viel gelernt und seid an der Macht gewachsen. Im Stamm der Dunkelspeere und in der Horde steht Euch eine großartige Zukunft bevor.\n\nIch habe den Verzauberkunstmeister des Kriegshäuptlings gebeten, einen Stab zu erstellen, um Eure Leistungen anzuerkennen.\n\nUm die dafür benötigten Materialien zu erlangen, müsst Ihr zur verfluchten Burg Schattenfang im Silberwald reisen. Findet das heilige Symbol von Kommandant Grüntal, etwas mondbestrahltes Holz, und die Essenzen der Geister, die die Burg heimsuchen, und bringt alles zu Godan.", sourceObjective = "Reist nach Burg Schattenfang und erhaltet das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27437] = { id = 27437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Aufforderung des dunklen Klerikers", description = "Ihr habt gewissenhaft gelernt und uns gedient. Wenn Ihr Eure Talente übereinstimmend mit den Wünschen von Fürstin Sylvanas benutzt, wird Euch der Schatten segnen.\n\nUnsere Königin hat beim Verzauberkunstmeister von Orgrimmar die Herstellung eines mächtigen Stabes zur Anerkennung Eurer Dienste in Auftrag gegeben.\n\nDie Materialien, die dafür benötigt werden, sind nur in Burg Schattenfang inmitten von Silberwald zu bekommen. Findet das verlorene heilige Symbol von Kommandant Grüntal, etwas mondbestrahltes Holz und die Essenz der Geister, die die Burg heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und erhaltet das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27438] = { id = 27438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die große Flucht", description = "Das Ziel unserer Mission ist erfüllt. Nun können wir unsere Flucht planen. Obwohl wir Gilneas verloren haben, werden wir es mit der Hilfe von Godfrey und seinen Leutnants schnell wieder zurückerobern können.\n\nGeht nun, {name}. Fliegt mit Arthura zurück zur Frontlinie der Verlassenen im Süden von Silberwald. Die Bansheekönigin erwartet Eure Ankunft.", sourceObjective = "Flieht aus den Ruinen von Gilneas mit Arthura und der Leiche von Lord Godfrey.", completion = "Ich hatte keinerlei Zweifel, dass es Euch gelingen würde, {name}. Ich hoffe Ihr könnt verstehen, warum ich den eigentlichen Grund Eurer Mission geheim gehalten habe. Falls Crowley und Blutfang von unserem Plan Wind bekommen hätten, hätten sie Godfrey sicher vor uns ausfindig gemacht und seine Leiche verschwinden lassen. Bleibt weiterhin verfügbar, {name}.\n\nDie Zeit der Wiedergeburt unseres Landes ist gekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27439] = { id = 27439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stab des Lichts", description = "Ihr seid durch Euer Talent schnell zu einem guten Diener des Lichts und Silbermonds geworden, {name}. Eure Loyalität gegenüber unserem Volk und der Horde sind beispielhaft.\n\nIn Anerkennung Eurer Hingabe hat der Kriegshäuptling bei seinem Verzauberkunstmeister die Herstellung eines Stabs für Euch in Auftrag gegeben.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und findet das verlorene heilige Symbol von Kommandant Grüntal, etwas mondbestrahltes Holz und die Essenz der Geister, die die Burg heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und erhaltet das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27440] = { id = 27440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trolls, Oger und Orcs, oh weh!", description = "Dem großen Schwarzdrachen Oberanführer Wyrmthalak unterstehen die Streitmächte der unteren Schwarzfelsspitze, die schon bald bereit für ihren Angriff auf die Dunkeleisenzwerge sein werden. Wir können nicht zulassen, dass die schwarzen Großdrachen die Kontrolle über den Berg erlangen!\n\nIhr müsst Kriegsmeister Voone, Hochlord Omokk und Oberanführer Wyrmthalak töten. Ihre Tode werden den Kampfgeist der Armee beeinträchtigen und uns so wertvolle Zeit verschaffen.", sourceObjective = "Tötet Kriegsmeister Voone, Hochlord Omokk und Oberanführer Wyrmthalak.", completion = "Es tut mir leid, wenn ich das so sage, aber ich bin erstaunt, dass Ihr diese Aufgabe lebendig abschließen konntet. Diese Monster waren für die Tode Tausender verantwortlich, darunter viele Helden, von denen bis zum heutigen Tag noch gut gesprochen wird.\n\nIhr habt Euch meinen Respekt verdient und sollt eine Belohnung für Euren Mut erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27441] = { id = 27441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stab eines Sehers", description = "Man sagt, dass sogar der Kriegshäuptling von Euren Taten für die Horde erfahren hat. Bestimmt wird er jetzt erkennen, dass er uns falsch eingeschätzt hat.\n\nEr hat sich bereiterklärt, dem Verzauberkunstmeister von Orgrimmar zu gestatten, einen Stab für Euch zu fertigen.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und findet das verlorene heilige Symbol von Kommandant Grüntal, etwas mondbestrahltes Holz und die Essenz der Geister, die die Burg heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und besorgt Euch das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27442] = { id = 27442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Krieg hat viele Fronten", description = "Jetzt sieht unsere Lage dem Feind in Vashj'ir gegenüber viel besser aus als vor Eurer Ankunft. Versteht mich nicht falsch, wir brauchen immer noch Eure Hilfe, aber vielleicht sind unsere anderen Fronten in noch größerer Bedrängnis.\n\nMan hat mir berichtet, dass unsere Verbündeten des Irdenen Rings in einer Angelegenheit um Hilfe gebeten haben, die keinen Aufschub duldet.\n\nScharfseher Krogar am Westlichen Erdschrein in Orgrimmar wird Euch weitere Anweisungen erteilen.", sourceObjective = "Sprecht mit Scharfseher Krogar am Westlichen Erdschrein in Orgrimmar.", completion = "Eure Hilfe kommt genau zur rechten Zeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27443] = { id = 27443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Krieg hat viele Fronten", description = "Jetzt sieht unsere Lage dem Feind in Vashj'ir gegenüber viel besser aus als vor Eurer Ankunft. Versteht mich nicht falsch, wir brauchen immer noch Eure Hilfe, aber vielleicht sind unsere anderen Fronten in noch größerer Bedrängnis.\n\nMan hat mir berichtet, dass unsere Verbündeten des Irdenen Rings in einer Angelegenheit um Hilfe gebeten haben, die keinen Aufschub duldet.\n\nErdsprecher Naraat am Östlichen Erdschrein in Sturmwind wird Euch weitere Anweisungen erteilen.", sourceObjective = "Sprecht mit Erdsprecher Naraat am Östlichen Erdschrein in Sturmwind.", completion = "Eure Hilfe kommt genau zur rechten Zeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27444] = { id = 27444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der falsche Kriegshäuptling", description = "Rend Schwarzfaust war der Sohn eines Kriegshäuptlings der Orcs. Sein Vater wurde von Orgrim Schicksalshammer umgebracht, der daraufhin zum neuen Kriegshäuptling anstelle des jungen Rends wurde. Rend hat sich nun zum Anführer der Schwarzfelsorcs emporgeschwungen, einer Möchtegern\"horde\", und wird dabei von Nefarian und seiner Drachenarmee unterstützt.\n\nRend, der Narr, behauptet auch, dass er das Geburtsrecht auf die Horde innehält, und droht, dieses Recht mit Gewalt geltend zu machen. Wir können nicht zulassen, dass dies unter dem Einfluss seines Meisters geschieht. Findet ihn in der oberen Schwarzfelsspitze und bringt diesen falschen Kriegshäuptling zu Fall, {race}.", sourceObjective = "Tötet Kriegshäuptling Rend Schwarzfaust.", progress = "Rend wird nicht ohne Kampf gestürzt werden können.", completion = "Habt Ihr Nefarian gesehen, als Ihr mit Rend gekämpft habt?\n\n<Acride seufzt.>\n\nIch wünschte, ich hätte Euch begleitet. Ich hätte ihm gegenübertreten können, als er nicht damit gerechnet hat, außerhalb seines Horts. Nun, das ist egal. Nefarian wird unter meiner Klaue sterben.\n\nIhr habt gute Arbeit geleistet.", sourceObjectiveStatus = "unverified-source-field" }
quests[27445] = { id = 27445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "General Drakkisath, Nefarians rechte Hand", description = "Nefarian weitet seinen Herrschaftsbereich weiter oben im Pechschwingenhort aus. Obwohl man dort von der oberen Schwarzfelsspitze aus hinkommt, könnten wir dort mit weitaus mehr Streitmächten einfallen, wenn wir die Kugel der Teleportation in der Nähe benutzen. Wir können uns erst teleportieren, wenn wir durch eine andere Kugel gekennzeichnet sind.\n\nDie zweite Kugel wird von Drakkisath, dem General von Nefarians Armee, persönlich bewacht. Schaltet ihn aus und sichert die zweite Kugel, damit wir sie nutzen können. Ihr werdet ihn im Spitzenthron in der oberen Schwarzfelsspitze finden.", sourceObjective = "Tötet General Drakkisath.", completion = "Hervorragend! Es ist nur eine Frage der Zeit, bevor der Sohn von Todesschwinge meine Klauen zu spüren bekommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27446] = { id = 27446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanaris ruft", description = "Hey, {name}! Kelsey Stahlfunken aus Tanaris hat eine Nachricht für Euch gebracht. Sie meint, die Gnome dort in Gadgetzan hätten von Euren Leistungen gehört.\n\nDer Kataklysmus hat sie auch dort unten nicht verschont. Uns hat er zwar härter getroffen, aber sicherlich können sie Eure Hilfe gebrauchen.", sourceObjective = "Sprecht mit Kelsey Stahlfunken in Gadgetzan in Tanaris.", completion = "Seid gegrüßt, mein Freund. Willkommen in Tanaris!", sourceObjectiveStatus = "unverified-source-field" }
quests[27447] = { id = 27447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanaris ruft", description = "Hey, {name}! Megs Schredderschreck aus Tanaris hat eine Nachricht für Euch hinterlassen. Sie sagt, die Goblins dort in Gadgetzan haben von Euren Leistungen gehört.\n\nDer Kataklysmus hat sie auch dort unten nicht verschont. Uns hat er zwar härter getroffen, aber sicherlich können sie Eure Hilfe gebrauchen.\n\nAußerdem sieht diese Megs verdammt gut aus!", sourceObjective = "Sprecht mit Megs Schredderschreck in Gadgetzan in Tanaris.", completion = "Aber hallo, {class}. Willkommen in Tanaris!", sourceObjectiveStatus = "unverified-source-field" }
quests[27448] = { id = 27448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reise geht weiter", description = "Ich glaube, die Pferde sind startklar. Argus Leuchtfeuer, der Herr, der mit dem Argentumkreuzzug zusammenarbeitet, hat sich vorhin mit mir unterhalten. Wie ich höre, wird er uns wohl begleiten - großartig! Ich werde Platz für ihn machen.\n\nIch weiß, dass Ihr beschäftigt seid, also nur keine Hektik. Sobald Ihr soweit seid, springt einfach auf den Karawanenwagen auf und wir machen uns auf den Weg zum nächsten Turm.", sourceObjective = "Steigt auf Fionas Karawanenwagen, wenn Ihr bereit seid, um zum nächsten Turm aufzubrechen.", progress = "Sobald wir am Lichtschildturm eintreffen, können sich die Jungs auf den Weg zur Kapelle des Hoffnungsvollen Lichts machen. Diese kurze Strecke können sie laufen.", completion = "Es war sehr angenehm, mit Euch zu reisen, {name}. Hoffentlich können wir unsere Reise gemeinsam fortsetzen, sobald Gidwin und Tarenar dem Argentumkreuzzug beigetreten sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[27449] = { id = 27449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehre und Stärke", description = "Mein Name lautet Vex'tul und ich habe Euch im Kampf beobachtet, {race}. Ihr seid stark.\n\nIhr habt meinen Meister Zaeldarr getötet, aber das stört mich nicht. Stärke ist mir wichtiger als die Loyalität, die ich ihm gegenüber empfand. Stärke ist mir wichtiger als alles andere.\n\nBeweist mir Eure Stärke ein letztes Mal, {race}. Wenn Ihr sie beweisen könnt, werde ich Euch MEINE Stärke leihen und Ihr werdet sie für all die Zwecke einsetzen können, die Euch vorschweben.", sourceObjective = "Besteht Vex'tuls Stärketest.", completion = "Ja, Ihr seid in der Tat stark ... ich unterwerfe mich Euch.\n\nIch werde Euch und Eure Freundin, den Worgen, begleiten. Meine Stärke ist Eure.", sourceObjectiveStatus = "unverified-source-field" }
quests[27450] = { id = 27450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fredericks Vorliebe für Fisch", description = "Ich liebe das Meer. Ich, Frederick Calston, war es, der die Meeresbewohner in den See im Südwesten gebracht hat. Ich hatte gehofft, den Kreuzzug so mit frischer Nahrung direkt aus den Pestländern versorgen zu können.\n\nAllerdings haben sich einige als Raubfische herausgestellt und jetzt versetzen sie alle anderen Tiere in Angst und Schrecken. Wenn wir nicht aufpassen, werden sie alle töten!\n\nSchwimmt zum Boden des Sees und rettet ein paar der Schnecken, Krabben und Kugelfische, bevor es zu spät ist.", sourceObjective = "Erhaltet 8 Pestkugelfische, 8 Infektkriecher und 8 Infektkrabbler aus der Infektnarbe.", progress = "Habt... habt Ihr die Fische besorgt?", completion = "Hmm ... sie haben den Ausflug an Land nicht so gut überstanden, wie ich gehofft hatte.\n\nNun gut. Dann gibt es für Frederick heute Abend Meeresfrüchtesalat!", sourceObjectiveStatus = "unverified-source-field" }
quests[27451] = { id = 27451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Töten zu einem bestimmten Zweck", description = "Seid gegrüßt, Fremdling! Ihr seid im Herzen der Pestländer angelangt. Ich hoffe, Ihr habt Eure Untote-Töten-Ausrüstung dabei.\n\nDieser Tage verbreitet sich die Seuche immer langsamer und daher hat der Kult der Verdammten die Herstellung hochgeschraubt, damit das Land braun und tot bleibt, so, wie es ihnen am liebsten ist. Ich habe einen Plan, sie aufzuhalten. Nehmt meinen Mörser und den Stößel; zerstoßt damit die lebendige Fäulnis der untoten Kreaturen in Corins Kreuzung südöstlich von hier. Wir werden für diese Kultisten ein kleines Geschenk vorbereiten.", sourceObjective = "Reist zu Corins Kreuzung im Süden und tötet die Geißelsoldaten, die dort hausen. Sammelt 7 Stück lebendige Fäulnis. Zerstoßt die lebendige Fäulnis mit Mörser und Stößel zu geronnener Fäulnis.", sourceObjectiveStatus = "unverified-source-field" }
quests[27452] = { id = 27452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Gewänder", description = "Einige meiner Mitstreiter haben berichtet, dass das Land heilen möchte. Allerdings lassen das viele hochrangige Untote - und auch der Kult der Verdammten - nicht zu. Das bedeutet, dass wir sie aufhalten müssen! Ich habe einen Plan, aber zuerst brauche ich eine Kultistenverkleidung.\n\nBegebt Euch nach Südosten, zu Corins Kreuzung und nehmt einem der menschlichen Kultisten die Gewänder ab. Ihr werdet sie durch den Ort streifen sehen. Ich werde mich mit Euch in Verbindung setzen, wenn Ihr das Gewand erhalten habt.", sourceObjective = "Erhaltet die Kopfbedeckung eines Todeskultisten und die Roben eines Todeskultisten von Kultisten in Corins Kreuzung.", sourceObjectiveStatus = "unverified-source-field" }
quests[27453] = { id = 27453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Katalysmus", description = "Geronnene Fäulnis ist allein schon sehr wirksam, aber wir brauchen etwas, um die versteckten Kräfte hervorzurufen ... einen Katalysator. Ein guter Katalysator findet sich südlich von hier, im Mereldarsee.\n\nWenn Ihr in Eure Taschen seht, werdet Ihr bemerken, dass ich ein paar Fläschchen hineingeschmuggelt habe, als Ihr nicht aufgepasst habt. Benutzt diese Fläschchen bei den Wasserelementaren im See. Das lebende, verderbte Wasser, aus dem ihre Körper bestehen, wird einen perfekten Katalysator abgeben!", sourceObjective = "Verwendet Betinas Fläschchen gegen lebende Elementare im Mereldarsee, um 8 flüssige Seuchenwirkstoffe zu erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27454] = { id = 27454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur ein Tropfen im Eimer", description = "Gebt nun eine kleine Menge Fäulnis zum Wasser und gut verrühren. So, das war es schon. Diese Lösung wird sehr aggressiv sein und wir brauchen nur ganz wenig davon.\n\nAm südöstlichen Ufer des Sees befindet sich ein Seuchenkessel, in dessen Nähe sich mehrere Kultisten aufhalten. Tragt die Kultistenverkleidung, geht zum Kessel und fügt nur EINEN TROPFEN dieser Lösung hinzu. Wenn Ihr mehr in den Kessel schüttet, ist Euer Leben in großer Gefahr!", sourceObjective = "Benutzt Eure Todeskultistenverkleidung, um das Basislager der Todeskultisten zu betreten und fügt Betinas Mischung dem Mereldar Seuchenkessel zu.", completion = "Es sollte Wochen dauern, bis sie ihr Vorhaben wieder in die Tat umsetzen können. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27455] = { id = 27455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jungs bleiben Jungs", description = "Direkt nach unserer Ankunft hier am Lichtschildturm sind die beiden Paladinschwachköpfe zur Kapelle des Hoffnungsvollen Lichts davongerannt. Sie ist noch recht weit entfernt, aber wenn wir Argus auf seiner Turmrundreise folgen wollen, dann ist das hier wohl noch am nächsten.\n\nSchaut einmal nach ihnen und stellt sicher, dass es ihnen gut geht. Ich weiß, dass sie auf sich selbst aufpassen können, aber dennoch... Mir wäre wohler, wenn ich wüsste, dass Ihr über sie wacht, während ich hier mit dem Wagen festsitze.", sourceObjective = "Findet Gidwin Goldzopf vor der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", completion = "Ich kann es kaum glauben. Wir stehen SO kurz davor, ordentliche Mitglieder des Argentumkreuzzugs zu werden.\n\nWir wären bereits aufgenommen, wenn Tarenar nicht so herumtrödeln würde. Wenn er nicht bald aufhört, mit den Einwohnern zu schwatzen, werde ich alleine dort hineingehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27456] = { id = 27456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht auf leeren Maden", description = "Wir haben Schwierigkeiten, unsere Nahrungsvorräte hier im tiefen Osten aufrecht zu erhalten.\n\nIn dieser Gegend gibt es nur eine Tierart, die nicht von der Seuche beeinträchtigt wird und das sind Aaswürmer. Sie schmecken zwar nach nichts, aber das Fleisch dieser Würmer kann über Monate hinweg aufbewahrt werden. Wir benötigen einige hundert Pfund, damit wir wieder ausreichend versorgt sind.\n\nMan findet Aaswürmer überall in den Pestländern, aber besonders häufig kommen sie südlich der Kapelle vor. Und denkt daran: Große Würmer liefern mehr Fleisch.", sourceObjective = "Sucht in der Umgebung nach Aaslarven und Aasverschlingern. Tötet sie und bringt 15 Scheiben Aaswurmfleisch an Euch.", progress = "Ihr werdet Euch an den Geschmack gewöhnen, {race}. Ging mir auch so.", completion = "Möge die Erdenmutter über Euch wachen. Seid gesegnet, Jüngling.", sourceObjectiveStatus = "unverified-source-field" }
quests[27457] = { id = 27457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Gelegenheitsallianz", description = "Durch Euren Beitrag zu den Nahrungslagern ist meine Aufgabe erledigt.\n\nIch werde mich als nächstes nach Norden in den Pestwald begeben. Wie ich höre, geht Ihr in die gleiche Richtung?\n\nWürde es Euch etwas ausmachen, wenn ich mich Euch anschließe? \n\nIch bin unterwegs nach Nordwesten zum Ostwallturm. Wenn Ihr Interesse an einem Zusammenschluss habt, könnt Ihr mich dort treffen.", sourceObjective = "Meldet Euch bei Fiona am Ostwallturm in den Östlichen Pestländern.", completion = "Ihr habt einen Schamanen mitgebracht! Und dann auch noch vom Irdenen Ring!\n\nIch habe keine Ahnung, wie er in dem Wagen Platz finden soll, aber uns wird etwas einfallen. Willkommen an Bord, Rimblat Erdspalter!", sourceObjectiveStatus = "unverified-source-field" }
quests[27458] = { id = 27458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smokey und der Verband", description = "He, Ihr da! Interesse, leichtes Geld zu verdienen?\n\nIch muss an eine Bandage kommen. Also, um ehrlich zu sein, hab ich einen Freund, der an eine Bandage kommen muss. Also, um ehrlich zu sein... sagen wir einfach, es ist zu kompliziert, aber wenn Ihr diese Bandage holt, bekommt Ihr Geld. Genau wie ich. Und mein Freund. Möglicherweise auch andere Leute.\n\nDie Mühle im Norden gehörte früher einmal Stephan Braumann, aber jetzt ist er tot. Ein Zombie. Der Kerl ganz oben möchte die Wickel von Braumanns Körper.\n\nWas ist los - mögt Ihr kein Geld?", sourceObjective = "Besorgt Braumanns Wickel von Stephan Braumann in Braumanns Mühle.", progress = "Ihr habt gegen Untote gekämpft. Habt Ihr Braumann gefunden?", completion = "Kaum zu glauben! Jemand, der losgeht und Dinge tatsächlich erledigt! Hier ist Euer Anteil, Chef. Wir seh'n uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[27459] = { id = 27459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bruderschaft des Lichts", description = "Die Bruderschaft des Lichts ist für ihre unbesonnenen und gedankenlosen Entscheidungen bekannt. Sie haben eine Brücke zwischen dem Scharlachroten Kreuzzug und der Argentumdämmerung geschlagen. Sie waren unter den ersten, die sich in Nordend in den Kampf warfen, während wir anderen noch zögerten.\n\nDeshalb sind sie auch für ihre Ergebnisse bekannt und das respektiere ich. Jetzt kämpfen sie an zwei Fronten: Eine Schlacht in Stratholme und die andere - viel drängendere - Schlacht im Süden bei Tyrs Hand.\n\nIch schlage vor, Ihr sprecht mit Angela Dosantos in Tyrs Hand. Vielleicht hat sie Verwendung für Euch.", sourceObjective = "Meldet Euch bei Erzmagierin Angela Dosantos in Tyrs Hand in den Östlichen Pestländern.", completion = "Ein {class}! Genau das, was wir brauchen. Eure Ankunft hätte nicht zu einem besseren Zeitpunkt erfolgen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[27460] = { id = 27460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sanfte Landung", description = "Man hat uns nur einhundert Männer überlassen, um diese Mission zu erfüllen und einer fehlt uns bereits. Unser Späher wurde in die Feste des Feindes entsandt, um einige Wachen auszuschalten, die in der Gegend patrouillieren. Außerdem sollte er ein Leuchtfeuer entfachen, damit wir einen koordinierten Angriff durchführen können. Unsere neunundneunzig verbliebenen Männer sind bereit und warten auf das Leuchtfeuer. Ich brauche <einen talentierten/eine talentierte:c> {class} wie Euch, <der/die:c> sich nach Tyrs Hand schleicht, so viele Wachen wie möglich ausschaltet und das Leuchtfeuer entfacht.\n\nFühlt Ihr Euch dem gewachsen?", sourceObjective = "Tötet 10 beliebige Anhänger des Scharlachroten Kreuzzugs in Tyrs Hand.", completion = "Das Leuchtfeuer ist aufgetürmt und die Streichhölzer liegen unbenutzt neben der Zündschnur.\n\nDer gefallene Argentumzenturio war näher dran, das Leuchtfeuer zu entzünden, als Ihr vermutet hattet.", sourceObjectiveStatus = "unverified-source-field" }
quests[27461] = { id = 27461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Abtei einnehmen", description = "Der Scharlachrote Kreuzzug unterhält eine gut befestigte Abtei im unteren westlichen Teil von Tyrs Hand. Zunächst muss die Abtei gesichert werden, bevor man sich weiter in die Festung vorwagen kann.", sourceObjective = "Meldet Euch bei Kommandant Eligor Morgenbringer außerhalb der Abtei in Tyrs Hand in den Östlichen Pestländern.", completion = "Seid gegrüßt, {name}. Kann ich darauf vertrauen, dass Ihr mir helfen werdet, die Abtei diesen Monstrositäten zu entreißen?", sourceObjectiveStatus = "unverified-source-field" }
quests[27462] = { id = 27462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kaserne einnehmen", description = "Eines der Schlüsselgebäude in Tyrs Hand ist die Kaserne, die sich ganz in der Nähe dieses Leuchtfeuers befindet. Die Bruderschaft des Lichts und ihre Zenturionen werden alle verfügbare Hilfe benötigen, um sie zu erobern.", sourceObjective = "Meldet Euch bei Kreuzzugskommandant Korfax vor der Kaserne in Tyrs Hand in den Östlichen Pestländern.", completion = "Ich werde ab jetzt die Leitung hier übernehmen, {class}.\n\nAlso gut, Ihr wollt eine Aufgabe? Ich denke, ich kann es mir leisten, Euch auf die ein oder andere Mission zu schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[27463] = { id = 27463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Kindheitstraum", description = "Ich wollte mich schon immer dem Kreuzzug anschließen. Deshalb bin ich Paladin geworden. Jahrelange Übung und Verbesserung meiner Fertigkeiten. Endlich bin ich bereit.\n\nTarenar glaubt ebenfalls, dass er bereit ist, aber da bin ich mir nicht so sicher. Er ist ein Angeber und hat seine Lektionen nie ernstgenommen. Dennoch - wir haben versprochen, dass wir das hier zusammen machen und hier stehen wir nun.\n\nSollen wir uns in die Kapelle begeben?", sourceObjective = "Sprecht mit Lord Maxwell Tyrosus in der Kapelle des Hoffnungsvollen Lichts.", completion = "Willkommen in der Kapelle des Hoffnungsvollen Lichts.\n\nIhr wünscht, Euch dem Kreuzzug anzuschließen? Na schön. Wir haben ausreichend Aufgaben für neue Rekruten.\n\nAber zunächst ein Test...", sourceObjectiveStatus = "unverified-source-field" }
quests[27464] = { id = 27464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argentumruf: Die Prüfung der Gruft", description = "Hinter unserer Kapelle findet Ihr eine kleine Gruft. Darin sind die Leichen unserer gefallenen Helden bestattet, die ihr Leben im Krieg gegen die Geißel verloren haben.\n\nIhre Seelen ruhen friedlich. Dennoch kehren sie hin und wieder zurück, um neue Mitglieder des Ordens zu prüfen.\n\nIhr drei dürft die Prüfung zusammen absolvieren. Betretet die Gruft und lest dann diese Schriftrolle. Lord Raymond George - mein Vorgänger - wird den Vorsitz bei Eurer Prüfung übernehmen.", sourceObjective = "Betretet die Gruft hinter der Kapelle des Hoffnungsvollen Lichts, lest aus der Argentumschriftrolle und schließt die Prüfung ab.", progress = "Eure Prüfung ist noch nicht abgeschlossen.", completion = "Denkt daran, dass Eure Vorfahren stets über Euch wachen. Als Bruder des Argentumkreuzzugs werdet Ihr Teil einer Familie, die auf eine lange Reihe solcher Vorfahren zurückblickt. Ihre Wachsamkeit und Ihr Schutz werden Eure Stärke sein, wenn Ihr Euch gegen die Geißel stemmt.\n\nMeine Glückwünsche, Tarenar, Gidwin und {name}. Willkommen beim Argentumkreuzzug.", sourceObjectiveStatus = "unverified-source-field" }
quests[27465] = { id = 27465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argentumruf: Das Giftige Tal", description = "Braumanns Mühle im Norden wimmelt nur so von Untoten. Das Giftige Tal, noch weiter nördlich, ist noch schlimmer befallen. Trotz der Nähe zu unserer Kapelle sind wir nicht in der Lage gewesen, sie zu entfernen.\n\nWachsamkeit ist der Schlüssel. Reist in das Giftige Tal und tötet so viele Untote, wie Ihr finden könnt, sowie die Kultisten, die sich darunter befinden.\n\nWährend Ihr dort seid, weicht Garginox dem Fleischriesen aus, der durch das Tal wandelt. Ich vermute, dass Ihr nicht stark genug seid, um ihn zu besiegen.", sourceObjective = "Tötet 16 Angehörige der Geißel und 8 Kultisten in Braumanns Mühle und dem Giftigen Tal. Kehrt zur Kapelle des Hoffnungsvollen Lichts zurück, wenn Tarenar oder Gidwin getötet werden.", completion = "Ihr seid früher als erwartet zurückgekehrt. Ausgezeichnet.\n\nWir werden unseren Weg in den Norden fortsetzen. Als nächstes werdet Ihr eine ähnliche Aufgabe erfüllen, diesmal in Nordtal.", sourceObjectiveStatus = "unverified-source-field" }
quests[27466] = { id = 27466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argentumruf: Nordtal", description = "Tyrosus hat uns unsere nächste Aufgabe gestellt: weitere Untote in Nordtal vernichten. Gidwin freut sich darauf, weiterzuziehen, aber ich glaube, wir sollten etwas vorsichtiger sein.\n\nLasst uns Fiona aufsuchen. Sie sollte jetzt den nächsten Turm erreicht haben... Ich glaube, er heißt Ostwallturm. Er ist in der Nähe, nordwestlich der Kapelle. Dort können wir uns ausruhen und unseren Angriff auf Nordtal planen.", sourceObjective = "Sprecht mit Fiona am Ostwallturm in den Östlichen Pestländern.", completion = "Hallo, {name}! Es freut mich, dass Ihr Euch uns wieder angeschlossen habt.\n\nTarenar und Gidwin sind bereits vor Euch eingetroffen. Tarenar ist gleich hier und Gidwin... nun... er ist gerade schlecht gelaunt. Ich glaube, er ist im Turm.", sourceObjectiveStatus = "unverified-source-field" }
quests[27467] = { id = 27467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergrabene Klingen", description = "Das Giftige Tal ist ein Morast, im wörtlichen und übertragenen Sinne. Es gibt dort oben genug Angehörige der Geißel, um uns beiden bis an unser Lebensende Schwierigkeiten zu bereiten.\n\nSie können die schwächeren wieder auferstehen lassen, wenn sie sterben, {name}. Sie werden nie aufhören, nachzurücken, wenn wir nicht etwas unternehmen.\n\nNehmt diese Klingen und durchstoßt damit die Leichen aller Reitersoldaten der Geißel, derer Ihr habhaft werden könnt. Die Klinge ist einfach, aber ihre Verzauberung wird verhindern, dass die toten Knochen wiederbelebt werden können. Für immer.", sourceObjective = "Stoßt die lichtberührten Klingen in die Leichen von 10 getöteten Reitersoldaten der Geißel.", completion = "Unsere Pflicht für heute ist getan.\n\nEs ist nur eine Frage der Zeit, bis wir die Geißel vernichtend schlagen. Heute haben wir Fortschritte gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[27468] = { id = 27468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettung des Belagerungspanzers", description = "Wir müssen unsere Belagerungspanzer einen nach dem anderen aus dem Schlamm ziehen. Nehmt die Ersatzteile, die Ihr gesammelt habt und gebt sie einem der Belagerungspanzerkommandanten, die auf den kaputten Fahrzeugen stehen.\n\nUnd dann verteidigt den Panzer, während die Ingenieure versuchen, ihn unzukaputten.\n\nGeht un' macht mich stolz, {class}!", sourceObjective = "Sprecht mit einem Belagerungspanzerkommandanten auf einem kaputten Belagerungspanzer von Hochstade. Verteidigt den Panzer, während die Ingenieure Reparaturen vornehmen.", progress = "Steine un' Stümpfe un' Berge un' Matsch ... Bäh.\n\nIch hasse die Natur.", completion = "Jupp, noch ein weiterer Panzer, der zur Reparatur kann.\n\nDurch all diese Bäume un' Baumstümpfe un' Matsch un' Steine könnte man nicht mal einen Golfball abschlagen und erst recht keinen Panzer fahren.\n\nWir müssen unsere Vorgehensweise ändern.", sourceObjectiveStatus = "unverified-source-field" }
quests[27469] = { id = 27469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freunde auf der anderen Seite", description = "Ich bringe Neuigkeiten von der Schwarzfelsspitze. Wir haben einen neuen Besucher. Sein Name ist Acride.\n\nEr sucht Leute, die stark, intelligent und geschickt sind. Ihr solltet zur Schwarzfelsspitze gehen und mit ihm sprechen.", sourceObjective = "Findet Acride.", completion = "Hallo, was führt Euch hierher?\n\nEntschuldigung, wer hat Euch geschickt? Ich fürchte, von einem {race} dieses Namens habe ich noch nie gehört.", sourceObjectiveStatus = "unverified-source-field" }
quests[27470] = { id = 27470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein möglicher Verbündeter", description = "Es ist kein Geheimnis, dass wir die Orcs im Schwarzfels nicht mögen. Wir beobachten sie daher ganz genau. Hier in den Bergen passiert nichts, von dem ich nichts weiß, {class}.\n\nVor Kurzem kam ein ganz andersartiger Orc nach Schwarzfels. Er hat sich in der Schwarzfelsspitze niedergelassen, und ich weiß, dass er irgendwie vorhat, Nefarian und seine ganze Orcarmee zu stürzen. Normalerweise würde ich keinem dieser Orcs trauen, aber zur Zeit verfolgen wir ein gemeinsames Ziel. Findet ihn. Er heißt Acride.", sourceObjective = "Findet Acride.", completion = "Hallo, was führt Euch hierher?\n\nAlso Aufseher Schlickfaust hat Euch geschickt? Hört gut zu, wir haben viel zu besprechen und nur wenig Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[27471] = { id = 27471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzfelsanomalie", description = "In der Schwarzfelsspitze gibt es einen Orc, der ganz anders ist als alle anderen Orcs. Seine Sprache zeugt von Intelligenz und Wissen, die seinem Aussehen Hohn spricht. Im Gegensatz zu den anderen Orcs bekämpft er auch unsere Soldaten nicht.\n\nIhr müsst zur Schwarzfelsspitze reisen, nordwestlich von hier, und diesen Orc finden, der uns nur als Acride bekannt ist. Vielleicht ist er der Schlüssel, um die Armee der Orcs aufzuhalten. Vielleicht können wir Nefarian aufhalten, bevor es zu spät ist ...", sourceObjective = "Findet Acride.", completion = "Hallo, was führt Euch hierher?\n\nAlso Ihr seid auf Bitten von Fräulein Wolkenglanz hier? Das ist ja höchst interessant.", sourceObjectiveStatus = "unverified-source-field" }
quests[27472] = { id = 27472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erwacht, Godfrey", description = "Eure Loyalität den Verlassenen gegenüber ist standhaft, {name}. Was Ihr bisher für uns getan habt - Eure Dienste für die Horde - werden nicht unbemerkt bleiben. Nun, da Lord Godfrey und seine Männer sich bald wieder erholt haben werden, werden wir einen großen Vorteil gegenüber der Gilnearischen Befreiungsfront und dem Rest der Hunde der Allianz haben.\n\nIch möchte Euch zum Anlass von Lord Godfreys Wiedergeburt als Einem von uns an meiner Seite haben. Wir werden ihn und seine Männer gemeinsam in unseren Kreis aufnehmen.", sourceObjective = "Bleibt bei Fürstin Sylvanas Windläufer, während sie Lord Godfrey und seine Männer aufnimmt.", completion = "Der heutige Tag stellt den Beginn einer neuen Ära für die Verlassenen und das Ende der Allianz in Lordaeron dar!", sourceObjectiveStatus = "unverified-source-field" }
quests[27474] = { id = 27474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Barriere durchbrechen", description = "Während Godfrey und ich unseren Angriff auf Gilneas vorbereiten, möchte ich, dass Ihr den Angriff auf Mühlenbern, direkt östlich von hier, leitet.\n\nDie früheren Magier von Dalaran in Mühlenbern haben eine magische Barriere errichtet, die sie unsichtbar macht. Sie befinden sich in einer Art Dimensionstasche und erwarten Befehle der Allianz, um ihren Angriff zu beginnen. Wir müssen diesen Angriff durch einen Präventivschlag verhindern. Begebt Euch nach Mühlenbern und sucht nach Informationen, die uns Zugang zu diesen Magiern verschaffen.", sourceObjective = "Findet den Kodex von Mühlenbern.", progress = "Habt Ihr schon etwas gefunden?", completion = "Die Magier sind schlau. Der Kodex ist mit einem magischen Schutzzauber versiegelt.\n\nSchade nur, dass sie nicht schlau genug waren, zu erkennen, dass die früheren Erzmagier von Dalaran jetzt Verlassene sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[27475] = { id = 27475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unnachgiebige Diener", description = "Die Magier von Mühlenbern haben abscheuliche Magie benutzt, um uns fernzuhalten. Elementardiener, deren Immunitäten wir nicht überwinden können, beschützen ihr Territorium.\n\nGeht nach Osten nach Mühlenbern und tötet die unerschütterlichen Elementardiener, die die Stadt bewachen. Dann bergt ihre Kerne. Bringt die Kerne hierher zu mir, damit ich einen Weg finden kann, wie wir sie alle zerstören können.", sourceObjective = "Bergt 6 Dienerkerne.", progress = "Habt Ihr die Dienerkerne gefunden?", completion = "Gut gemacht, {name}. Das Lob, das die Bansheekönigin Euch zuteilwerden lässt, ist anscheinend nicht unbegründet.", sourceObjectiveStatus = "unverified-source-field" }
quests[27476] = { id = 27476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dalar Morgenweber", description = "Nehmt den Kodex und reist nach Norden zum Grabmal. Wenn Ihr dort eintrefft, sucht nach Dalar Morgenweber. Dalar ist ein früherer Erzmagier der Kirin Tor. Er wird sicherlich in der Lage sein, die Schutzzauber, die diesen Kodex umgeben, zu entfernen und ihm seine Geheimnisse zu entlocken.\n\nBeeilt Euch, {name}.", sourceObjective = "Liefert den Kodex von Mühlenbern bei Dalar Morgenweber am Grabmal im Silberwald ab.", progress = "Ja? Was wollt Ihr?", completion = "Die Dunkle Fürstin benötigt meine Expertenmeinung? Aber selbstverständlich! Gebt schon her mein Junge.", sourceObjectiveStatus = "unverified-source-field" }
quests[27477] = { id = 27477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Korpulente", description = "Nördlich von hier und westlich von Nordtal findet Ihr das fettleibige Madenungeheuer Blutschlinger.\n\nIch habe ganze Regimenter gegen dieses Monster eingebüßt. Seine Ausmaße sind gewaltig! Je mehr er frisst, desto größer wird sein Umfang...\n\nEs würde mir keine schlaflosen Nächte bereiten, sollte die Bestie Euch verschlingen, dennoch sähe ich es lieber, wenn Ihr als Sieger hervorgeht. Man weiß, dass Blutschlinger schon andere verschlungen hat, die versucht haben, ihn zu jagen.", sourceObjective = "Findet Blutschlinger im nördlichen Ödland der Östlichen Pestländer und vernichtet ihn.", completion = "Macht weiter so und es könnte passieren, dass ich Euch hier in Ostwall bei mir behalte, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27478] = { id = 27478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relios, Bewahrer der Relikte", description = "Die Dunkle Fürstin hat Recht, dass ich in der Lage bin, den Kodex zu entschlüsseln. Leider benötige ich dafür einen Siegelring von einem Erzmagier aus Dalaran. Mein eigener Ring wurde mir weggenommen, als ich vor vielen Jahren starb, aber es gibt vielleicht eine Möglichkeit.\n\nObwohl Dalaran fortgeschwebt ist, sind doch die Außenbezirke der Stadt erhalten geblieben. Weit im Osten liegen die Ruinen von Dalaran. Dort werdet Ihr einen Erzmagier mit Namen Relios finden. Nehmt seinen Siegelring an Euch und bringt ihn zu mir zurück.\n\nIhr dürft das Portal hinter mir benutzen, um zu dem Krater zu gelangen.", sourceObjective = "Findet einen Siegelring eines Erzmagiers aus Dalaran.", progress = "Habt Ihr einen Siegelring eines Erzmagiers aus Dalaran gefunden?", completion = "Perfekt. Ich hoffe, es war nicht zu schwierig, an ihn heranzukommen, {name}. Relios war einer meiner Schüler, als ich noch ein Sterblicher war. Deshalb dürfte er ein fähiger und ernstzunehmender Gegner sein. Ich hätte Euch wohl schon vorher warnen sollen.\n\nNun, lasst uns den Ring anschauen.\n\n\n\nNa also...", sourceObjectiveStatus = "unverified-source-field" }
quests[27479] = { id = 27479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rechtschaffene Empörung", description = "Die Moosschinder von Zul'Mashar spucken dem Licht ins Gesicht! Ihr Kannibalismus, ihr Atheismus, ihr Atavismus stellen die Mächte des Bösen über die des Guten. Ich verschreibe, Ihr rückt ihnen zu Leibe, damit ihr Getreibe ein Ende finde und jeder noch so Blinde empfinde, welche Strafe auf Torheit stünde!\n\nIhr werdet nach Norden reisen und mit all Eurer rechtschaffenen Empörung über sie kommen, {name}. Der Zorn, den sie im Angesicht des Lichts entflammt haben, wird Euch zueigen werden.", sourceObjective = "Erbeutet 30 Moosschinderaugen von Moosschindertrollen in Zul'Mashar.", progress = "<Diakon Andaal ist ins Gebet vertieft.>", completion = "Oh, Hallelujah, gelobt sei das Licht, Bruder!", sourceObjectiveStatus = "unverified-source-field" }
quests[27480] = { id = 27480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ley-Energien", description = "Das arkane Überbleibsel pulsiert mit seltsamer Energie. Vielleicht solltet Ihr nach weiteren Überbleibseln suchen. Dalar wäre an solchen Funden sicherlich interessiert.", sourceObjective = "Findet 8 arkane Überbleibsel.", sourceObjectiveStatus = "unverified-source-field" }
quests[27481] = { id = 27481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus dem Ziggurat", description = "Die Zeit ist gekommen, Euch um einen Gefallen zu bitten, {name}.\n\nWeit nördlich des Ostwallturms, verborgen in den Hügeln, liegt die Moosschinderhauptstadt Zul'Mashar. Hier wurde ich geboren und hier bin ich gestorben.\n\nDer Verräter Thresh'jin sitzt auf Zul'Mashars Ziggurat. Eigentlich hätte mir der Sitz zugestanden, aber er erschlich ihn sich von mir durch Verrat und Lügen. Er ist nicht stark. Er ist schwach.\n\nIch werde in Zul'Mashar zu Euch stoßen. Dann werden wir ihn töten. Eure Stärke und die meine. Vereint.", sourceObjective = "Erbeutet den Leichnam von Kriegsherr Thresh'jin.", sourceObjectiveStatus = "unverified-source-field" }
quests[27482] = { id = 27482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinein in die Flammen", description = "Dies ist unsere letzte Begegnung, {name}. Ich verlasse die Karawane.\n\nBehaltet Thresh'jins Leiche, wenn Ihr weiter an meiner Seite kämpfen wollt. Ich kann noch ein wenig länger ausharren. Werft den Körper in das Feuer oben auf Zul'Mashars Ziggurat, wenn Ihr bereit zum Abschied seid.\n\nIch danke Euch für Eure Freundschaft, {name}. Ihr wart stark.", sourceObjective = "Werft den Leichnam des Kriegsherrn Thresh'jin in das Feuer oben auf Zul'Mashars Ziggurat, wenn Ihr bereit seid, Euch von Vex'tul zu trennen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27483] = { id = 27483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Praktische Rache", description = "Eigentlich bin ich kein rachsüchtiger Mann. Um genau zu sein bin ich eher Pragmatiker. Wisst Ihr, Sachlichkeit ist im Grunde das Gegenteil zu Rache. Die meisten Rachepläne sind höchst unpraktisch.\n\nABER... in diesem Fall... Da Ihr Euch ohnehin schon zu den Ruinen von Dalaran begebt, könnt Ihr auch jeden Menschen, der mit Dalaran in Verbindung gebracht werden kann, töten. Die Gründe dafür, dass ich sie tot sehen will, reichen von Hass über Zorn bis zu Verrat, aber ich versichere Euch, der Groll ist durchweg berechtigt. Erledigt das für mich und ich werde Euch reich belohnen.", sourceObjective = "Tötet 12 beliebige Menschen aus Dalaran.", completion = "Ich hatte mit Sicherheit angenommen, dass der Tod eines Dutzends meiner meist gehassten Feinde mir eine große Last von den Schultern nimmt. Leider spüre ich gar nichts. Vielleicht bin ich ein Psychopath.", sourceObjectiveStatus = "unverified-source-field" }
quests[27484] = { id = 27484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es darf nur einer eintreten", description = "<Dalar blättert durch den Kodex.>\n\nHAHAH!\n\nOh... Das ist schlimm.\n\n<Dalar klappt den Kodex zu und schaut zu Euch hoch.>\n\nNur EINER darf mit Hilfe dieses Rings die Dimensionstasche in Mühlenbern betreten. Diese Person muss sich dann einen Weg durch eine Armee von Magiern freikämpfen und den Erzmagier töten, der die Verschiebung von der anderen Seite her erschafft. Erst dann wird die Dimension in sich zusammenbrechen und alle Magier auswerfen.\n\nDas Portal, durch das man hineingelangen kann, liegt versteckt hinten in einer Höhle in Berens List.\n\nMehr weiß ich nicht. Bringt den Ring zu Sylvanas zurück.", sourceObjective = "Bringt den Siegelring eines Erzmagiers aus Dalaran zu Fürstin Sylvanas Windläufer an der Frontlinie der Verlassenen im Silberwald zurück.", progress = "Was habt Ihr erfahren?", completion = "Nur einer darf eintreten? Ich kenne genau die richtige Person für diese Aufgabe.\n\n<Sylvanas nickt Euch zu.>\n\nIch werde unsere Streitkräfte vorbereiten und bereithalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27485] = { id = 27485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein herzliches Willkommen", description = "Ich bin froh, dass Ihr zurück seid! Um die Welt zu retten oder dergleichen, da bin ich sicher.\n\nIch wurde ausgeschickt, um Beziehungen mit den roten Drachen in der Gegend aufzubauen, aber ich finde sie weniger zugänglich als diejenigen in Wyrmruh. Allerdings sagte man mir, dass Ihr jemand seid, der Probleme löst.\n\nEin Problemlöser sozusagen.\n\nHättet Ihr vielleicht Lust, ein wenig Vertrauen mit Lirastrasza im Zinnoberrefugium im Norden aufzubauen? Alles, das sie mir gegenüber ein wenig milder stimmt wäre wunderbar.", sourceObjective = "Trefft Euch mit Lirastrasza im Zinnoberrefugium.", completion = "Ich bin froh, dass Lira Euch nicht verschreckt hat. Ich will damit nicht sagen, dass ihre Bedenken nicht gerechtfertigt sind, aber wir haben einen gemeinsamen Feind. Vielleicht ist sie etwas übervorsichtig.", sourceObjectiveStatus = "unverified-source-field" }
quests[27486] = { id = 27486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein herzliches Willkommen", description = "Gut. Ihr seid zurück. Rettet wohl wieder die Welt, was?\n\nIch wurde ausgeschickt, um Beziehungen zu den roten Drachen in der Gegend aufzunehmen, aber die hiesige Variante ist bei Weitem nicht so entgegenkommend, wie die Drachen im Wyrmruhtempel. Mir ist allerdings zu Ohren gekommen, dass Ihr jemand seid, der Probleme löst.\n\nEin Problemlöser sozusagen.\n\nIhr müsst das Vertrauen von Lirastrasza im Zinnoberrefugium südwestlich von hier gewinnen. Unsere Zusammenarbeit mit dem Drachenmalklan hat die Angelegenheit zugespitzt, aber ich bin zuversichtlich, dass Ihr die Wogen glätten könnt.", sourceObjective = "Trefft Euch mit Lirastrasza im Zinnoberrefugium.", completion = "Ich bin froh, dass Lira Euch nicht verschreckt hat. Ich will damit nicht sagen, dass ihre Bedenken nicht gerechtfertigt sind, aber wir haben einen gemeinsamen Feind. Vielleicht ist sie etwas übervorsichtig.", sourceObjectiveStatus = "unverified-source-field" }
quests[27487] = { id = 27487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ix'lar der Unterfürst", description = "Ich weiß, dass wir eigentlich nach Nordtal aufbrechen sollten, aber das hat doch noch Zeit, oder? Dieser niedliche kleine Goblin hat mir übrigens erzählt, dass die Geißel in der Nähe weilt.\n\nAnscheinend gibt es einen nerubischen Unterfürsten namens Ix'lar, der seit der Vernichtung des Lichkönigs versucht, sich einen Namen zu machen. Er und seine Untoten haben nördlich von uns ein Lager errichtet.\n\nNatürlich will Tyrosus, dass wir Banshees in Nordtal töten. Das werden wir auch. Aber lasst uns zuerst diesen Neruber töten, solange wir in der Nähe sind!", sourceObjective = "Tötet Ix'lar den Unterfürsten und 10 seiner Diener.", completion = "Ich konnte ihn nicht aufhalten. Während Ihr und Tarenar unterwegs wart, ist Giddy ganz allein nach Norden gelaufen!\n\nTarenar, Ihr hättet es besser wissen sollen! Gidwin wird manchmal so ungeduldig und Ihr stachelt ihn noch an. Wenn Giddy in Schwierigkeiten gerät, gebe ich Euch die Schuld daran.", sourceObjectiveStatus = "unverified-source-field" }
quests[27488] = { id = 27488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungeduld", description = "Dieser verdammte Zwerg. Immer kriege ich wegen ihm Ärger mit Fiona. Seht sie Euch doch an! Sie REDET nicht einmal mehr mit mir!\n\nIch werde hier bleiben und versuchen, meine Freundschaft mit unserer Worgenfreundin zu kitten. Würde es Euch etwas ausmachen, allein nach Gidwin zu suchen? Es geht ihm bestimmt gut. Er kann auf sich allein aufpassen. Er war auf dem Weg nach Norden. Weit kann er nicht gekommen sein.", sourceObjective = "Sucht nach Gidwin Goldzopf in Nordtal.", progress = "In Nordtal gibt es einige Geister und Banshees. Der alte Giddy kommt mit denen schon klar.", completion = "Ihr seid ihm nicht begegnet? Wo ist er denn nur?\n\nSein... sein Gebetsbuch? Warum hat er das zurückgelassen?\n\nOh...\n\nBeim Licht, was habe ich getan?", sourceObjectiveStatus = "unverified-source-field" }
quests[27489] = { id = 27489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich allein bin schuld", description = "Das ist meine Schuld. Ich... Ich habe seine Warnungen und Beschwerden ignoriert. Ich konnte nicht anders - Ich sah die Geißel so nahe hinter dem Turm, da... Ich MUSSTE sie töten.\n\nArgus sagt, Gidwin sei nach Nordwesten gebracht worden. Das ist unsere einzige Spur, also werden wir in diese Richtung aufbrechen.\n\nIch pfeife auf Nordtal und den Argentumkreuzzug! Wir werden Gidwin von diesen Geißelmistkerlen zurückholen.", sourceObjective = "Steigt in Fionas Karawanenwagen und fahrt zum Nordpassturm.", completion = "Die Zeit rennt uns davon, {name}. Mit jeder Minute, die wir verschwenden, steigt die Wahrscheinlichkeit, dass die Geißel Gidwin umbringt. Wenn er nicht schon tot ist.\n\nDoch das glaube ich nicht. Giddy ist zwar nicht der Hellste, aber wenn es sein muss, schwingt er das Licht wie ein Champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[27490] = { id = 27490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den SI:7 absetzen", description = "Mathias Shaw und der SI:7 sind hier, um uns bei unserer Mission oben in der Schattenzitadelle zu unterstützen. Ihr müsst sie für mich dorthin geleiten.\n\nDie Wildhämmer sind so freundlich, uns dorthin zu fliegen. Die Agenten müssen jedoch zuerst etwas unten bei den Toren erledigen.\n\nSprecht mit Angus Stillberg und schnappt Euch eine Truppe, um sie sicher abzusetzen. Ihr werdet sie hereinfliegen. Die Stelle ist mit einem großen blauen X markiert.", sourceObjective = "Holt bei Angus Stillberg eine Truppe der Wildhammervandalen ab und begleitet sie zum Landepunkt am Schattentor.", completion = "Das muss schlimm gewesen sein.\n\nAuch wenn ich mit ihren Methoden nicht einverstanden bin, kann niemand die Effizienz von Mathias Shaw und seinem SI:7 anzweifeln. Und schließlich seid Ihr auch noch hier. Unser Sieg ist schon in trockenen Tüchern.", sourceObjectiveStatus = "unverified-source-field" }
quests[27491] = { id = 27491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kor'kron absetzen", description = "Garona und ein Kommando der Kor'kron sind hier, um uns bei unserer Mission oben in der Schattenzitadelle zu unterstützen. Ihr müsst sie für mich dorthin geleiten.\n\nDer ansässige Trollstamm ist so freundlich, uns auf ihren Windreiten dorthin zu fliegen. Die Assassinen müssen jedoch zuerst etwas unten bei den Toren erledigen.\n\nSprecht mit dem Anführer der Trolle, Jon-Jon Glibberhals, und schnappt Euch ein Kommando der Kor'kron, um sie sicher abzusetzen. Ihr werdet sie hereinfliegen. Die Stelle ist mit einem großen roten X markiert.", sourceObjective = "Holt bei Jon-Jon Glibberhals eine Truppe der Schmetterschlagwindreiter ab und begleitet sie zum Landepunkt am Schattentor.", completion = "Das muss spannend gewesen sein.\n\nTrotz der Verluste, die die Kor'kron vielleicht unterwegs erlitten haben, wird niemand es wagen, Zweifel an ihrer Effizienz noch an der Garonas zu äußern. Und da Ihr auch mit von der Partie seid, ist es nur eine Frage der Zeit, bis der Sieg unser ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[27492] = { id = 27492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oger und Ettins", description = "Wie bei jeder Offensive müsst Ihr erst ihre Reihen schwächen. Wir haben uns ganz schön angestrengt, um dort hinein zu gelangen. Aber jemand wie Ihr… Nun, sagen wir einfach, dass ich keinen Zweifel habe, dass Ihr die Tore der Zitadelle im Südwesten durchbrechen und den Ogern und Ettins des Blutaugenklans ein oder zwei Lektionen erteilen könnt.", sourceObjective = "Tötet 10 Oger oder Ettins am Schattentor.", completion = "Genau das will ich sehen, Kumpel! Heute scheint ein guter Tag zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27493] = { id = 27493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oger und Ettins", description = "Ich möchte, dass Ihr Euch hinter diese Felsen schwingt und jeden Oger oder Ettin des Blutaugenklans tötet, der Euch über den Weg läuft. Könnt Ihr das für mich tun, {name}?", sourceObjective = "Tötet 10 Oger oder Ettins des Blutaugenklans am Schattentor.", completion = "Und ich dachte, es könnte heute nicht mehr besser kommen.\n\nNun, ich irre mich gerne, zumindest manchmal.", sourceObjectiveStatus = "unverified-source-field" }
quests[27494] = { id = 27494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berge versetzen", description = "Wenn die Tore fallen sollen, müssen wir Schädelberster den Berg dort weglocken!\n\nBevor sie gegangen sind, habe ich dafür gesorgt, dass Eure Agenten des SI:7 ein paar Sprengsätze mitnahmen, die in einer Kiste des Schattenhammers versteckt waren. Sie sollten sie bereits auf den Stufen zum oberen Bereich der Zitadelle platziert haben.\n\nIch möchte, dass Ihr die Sprengsätze zündet und uns dann Bescheid gebt, wenn das Monster aus dem Weg geräumt ist.\n\nDann werden wir angreifen und den Ogern den Rest geben!", sourceObjective = "Zündet die versteckten Sprengsätze, um Schädelberster den Berg vom Schattentor wegzulocken.", sourceObjectiveStatus = "unverified-source-field" }
quests[27495] = { id = 27495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berge versetzen", description = "Wenn die Tore fallen sollen, müssen wir Schädelberster den Berg dort weglocken!\n\nBevor sie gegangen sind, habe ich dafür gesorgt, dass Eure Assassinen der Kor'kron ein paar Sprengsätze mitnahmen, die in einer Kiste des Schattenhammers versteckt waren. Sie sollten sie bereits auf den Stufen zum oberen Bereich der Zitadelle platziert haben.\n\nIch möchte, dass Ihr die Sprengsätze zündet und uns dann Bescheid gebt, wenn das Monster aus dem Weg geräumt ist.\n\nDann werden wir angreifen und den Ogern den Rest geben!", sourceObjective = "Zündet die versteckten Sprengsätze, um Schädelberster den Berg vom Schattentor wegzulocken.", sourceObjectiveStatus = "unverified-source-field" }
quests[27496] = { id = 27496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holt die Artillerie!", description = "Ich bevorzuge einen ehrenhaften Kampf Mann gegen Mann. Diese Monster verdienen es, durch die Waffen in unseren Händen den Tod zu finden. In diesem speziellen Fall müssen wir jedoch auf mächtigere Methoden zurückgreifen.\n\nNehmt diese Leuchtpistole und markiert die vier Gebäude innerhalb des Schattentors im Südwesten. Unsere Kanonen werden den Rest erledigen.", sourceObjective = "Benutzt die Artillerieleuchtpistole, um das nördliche, das nordöstliche, das südwestliche und das südliche Gebäude am Schattentor als Ziel zu markieren.", completion = "Dank Euch können unsere Kanoniere ihr Ziel nicht mehr verfehlen. Und nun berichtet mir von der Lage am Schattentor.", sourceObjectiveStatus = "unverified-source-field" }
quests[27497] = { id = 27497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holt die Artillerie!", description = "Wie schade, dass wir unsere Feinde nicht mehr mit der Seuche strafen dürfen. Gerade in dieser Lage wäre das sehr effektiv. Nun ja, zumindest haben wir Kriegsmaschinen, um ihre ach so geliebten Tore einzureißen.\n\nNehmt diese Leuchtpistole und markiert die vier Gebäude innerhalb des Schattentors im Nordwesten. Unsere Kanonen werden den Rest erledigen.", sourceObjective = "Benutzt die Artillerieleuchtpistole, um das nördliche, das nordöstliche, das südwestliche und das südliche Gebäude beim Schattentor als Ziel zu markieren.", completion = "Ich muss sagen, der Anblick der einschlagenden Bomben in ihre Gebäude hat mich gut unterhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27498] = { id = 27498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehlt den Angriff", description = "Jetzt, da Ihr Schädelbrecher den Berg vom Schattentor weggelockt habt, müsst Ihr den Truppen am Gipfel des Siegers signalisieren, dass sie angreifen können!", sourceObjective = "Benutzt das Angriffssignal auf einem der Türme beim Schattentor.", sourceObjectiveStatus = "unverified-source-field" }
quests[27499] = { id = 27499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehlt den Angriff", description = "Jetzt, da Ihr Schädelbrecher den Berg vom Schattentor weggelockt habt, müsst Ihr den Truppen am Schmetterschlagposten signalisieren, dass sie angreifen können!", sourceObjective = "Benutzt das Angriffssignal auf einem der Türme beim Schattentor.", sourceObjectiveStatus = "unverified-source-field" }
quests[27500] = { id = 27500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vier Köpfe sind besser als keiner", description = "Während der Angriff auf die Tore der Zitadelle in vollem Gange ist, gibt es noch eine Sache, um die Ihr Euch kümmern müsst: Za'brox und Beeble'phod, die Jünger Cho'galls.\n\nLaut den Geheiminformationen halten sie sich im Schlupfwinkel der Jünger auf, einer kleinen Ogerhöhle am südwestlichen Ende des Schattentors.\n\nIhr seid Euch ziemlich sicher, dass Cassius und Kurdran einen Beweis für ihren Tod sehen wollen.", sourceObjective = "Sammelt die vier Köpfe von Za'brox und Beeble'phod.", progress = "Tropft da etwa Blut aus Eurer Tasche?", completion = "<Der Paladin verzieht das Gesicht.>\n\nDa habt Ihr aber eine grausame Trophäensammlung. Ich hätte Euch auch geglaubt, wenn Ihr mir einfach gesagt hättet, dass sie tot sind. Dennoch danke, dass Ihr so vorausschauend wart, sie zu töten.\n\nDas Schattentor ist bald in unserer Hand. Es wird Zeit, uns der Schattenzitadelle selbst zuzuwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27501] = { id = 27501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vier Köpfe sind besser als keiner", description = "Während der Angriff auf die Tore der Zitadelle in vollem Gange ist, gibt es noch eine Sache, um die Ihr Euch kümmern müsst: Za'brox und Beeble'phod, die Jünger Cho'galls.\n\nLaut den Geheiminformationen halten sie sich im Schlupfwinkel der Jünger auf, einer kleinen Ogerhöhle am südwestlichen Ende des Schattentors.\n\nIhr seid Euch ziemlich sicher, dass Lady Cozwyn und Zaela einen Beweis für ihren Tod sehen wollen.", sourceObjective = "Sammelt die vier Köpfe von Za'brox und Beeble'phod.", progress = "Tropft da etwa Blut aus Eurer Tasche? Ich hoffe, es ist nicht Euer eigenes.", completion = "<Die hohe Dame grinst boshaft.>\n\nDa habt Ihr aber eine grausame Trophäensammlung. Ich hätte Euch auch geglaubt, wenn Ihr mir einfach gesagt hättet, dass sie tot sind. Aber ich weiß Eure zusätzliche Mühe durchaus zu schätzen. Dennoch danke, dass Ihr so vorausschauend wart, sie zu töten.\n\nDas Schattentor ist bald in unserer Hand. Es wird Zeit, uns der Schattenzitadelle selbst zuzuwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27502] = { id = 27502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinauf zur Zitadelle", description = "Jetzt, da der Angriff eingeleitet wurde, ist es Zeit, uns um die Schattenzitadelle zu kümmern. Wenn Ihr nichts dagegen habt, möchte ich Euch bitten, die Truppen des SI:7 zu Meister Mathias Shaw zu führen.\n\nEr hält sich irgendwo auf dem Gipfel versteckt. Der Truppenkommandant des SI:7 kann Euch den genauen Ort nennen.\n\nVielen Dank, {name}. Wir freuen uns schon darauf, Euch beim Angriff auf die Zitadelle zur Seite zu stehen!", sourceObjective = "Sprecht mit dem Truppenkommandanten des SI:7 und begleitet dann die Truppe des SI:7.", sourceObjectiveStatus = "unverified-source-field" }
quests[27503] = { id = 27503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinauf zur Zitadelle", description = "Jetzt, da der Angriff eingeleitet wurde, ist es Zeit, uns um die Schattenzitadelle zu kümmern. Wenn Ihr nichts dagegen habt, möchte ich Euch bitten, die Truppen der Kor'kron zu Garona zu führen.\n\nSie hält sich irgendwo auf dem Gipfel versteckt. Der Truppenkommandant der Kor'kron kann Euch den genauen Ort nennen.\n\nVielen Dank, {name}. Wir freuen uns schon darauf, Euch beim Angriff auf die Zitadelle zur Seite zu stehen!", sourceObjective = "Sprecht mit dem Truppenkommandanten der Kor'kron und begleitet dann die Truppe der Kor'kron.", sourceObjectiveStatus = "unverified-source-field" }
quests[27504] = { id = 27504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sogar Drachen bluten", description = "Ich werde nicht so unhöflich sein, Eure Hilfe abzulehnen, wenn Ihr sie mir schon anbietet.\n\nWir befinden uns im stetigen Kampf mit den Zwielichtdrachen im Süden. Zwar sind unsere Angriffe nicht ganz fruchtlos, aber die Drachen, die aus Grim Batol hinausströmen, haben eine Art Verderbnis auf uns herab beschworen, die es nun zu läutern gilt.\n\nVelastrasza und Unheilsflamme kümmern sich um unsere verletzten Brüder. Geht und schaut, ob Ihr ihnen helfen könnt.", sourceObjective = "Sprecht mit Velastrasza im Zinnoberrefugium.", completion = "Calen ist sehr vertrauensselig in letzter Zeit. Nicht viele Fremde dürfen das Refugium betreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27505] = { id = 27505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilung auf Drachenart", description = "Wenn unsere Drachen aus der Schlacht zurückkehren, sind sie ganz in vom Zwielicht verderbte Flammen gehüllt und werden von den Zwielichtdrachen verfolgt.\n\nMeine Heiler können sich zwar um die Wunden unserer Drachen kümmern, aber sie müssen dabei geschützt werden. Haltet die Drachen von meinen Heilern fern. Wenn Ihr könnt, helft auch Ihr unseren Drachen mit Eurer Heilkraft.\n\nVielen Dank für Eure Unterstützung in dieser Angelegenheit. Unsere Schlachten um Grim Batol nehmen kein Ende. Wir müssen unsere mächtigsten Drachen so schnell wie möglich wieder in den Kampf schicken.", sourceObjective = "Beschützt 5 zinnoberrote Heiler, während sie verwundete Drachen heilen.", progress = "Schützt die Heiler, während sie unsere verwundeten Drachen heilen!", completion = "Wir werden Grim Batol vom Schattenhammer und seinen Verbündeten zurückerobern. Es wird vielleicht ein wenig dauern, aber bei dieser Aufgabe dürfen wir nicht scheitern.", sourceObjectiveStatus = "unverified-source-field" }
quests[27506] = { id = 27506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leben aus dem Tod", description = "{race}, ich habe eine Aufgabe für Euch.\n\nNehmt diese Rubinsamen und pflanzt sie in die Leichname der Drachkin, denen Ihr begegnet. Zwielicht oder Zinnober, Welpling oder Drache, es ist ganz egal. Wir müssen dafür sorgen, dass ihre Körper wieder der Erde zurückgegeben werden, damit das Leben erneut erblühen kann.\n\nIm Tod sollte es immer neues Leben geben. Lasst Euch das einen Trost in Zeiten des Krieges und des Leids sein.", sourceObjective = "Pflanzt Rubinsamen in die Leichname von 6 Drachkin im Zinnoberrefugium.", completion = "Durch diese Tat verweigern wir Todesschwinge die Zerstörung, die er so leidenschaftlich anrichten möchte. Durch diese Tat geht das Leben weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[27507] = { id = 27507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ausbreitung des Zwielichts", description = "Im Refugium wimmelt es von Zwielichteindringlingen. Sie strömen von einem unbekannten Ort im Westen auf die Lichtung.\n\nAn diesem heiligen Ort kann es für sie kein Mitleid geben. Welchen Funken der Gewalt Ihr auch in Eurem rechtschaffenen Herzen finden mögt, lasst sie darin in Flammen aufgehen.", sourceObjective = "Tötet 12 Zwielichteindringlinge im Zinnoberrefugium.", completion = "Ihr habt ein Händchen fürs Töten, wie ich sehe. In Zeiten wie diesen hat auch dies eine Berechtigung.", sourceObjectiveStatus = "unverified-source-field" }
quests[27508] = { id = 27508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weit weg vom Nest", description = "Schaut… Ich weiß, dass Ihr keinen Grund habt, mich zu mögen, genauso wie auch ich Euch nicht besonders mag, aber ich brauche jede Hilfe, die ich bekommen kann.\n\nDiese Zwielichteindringlinge stehlen unsere Eier. Ohne Zweifel haben sie vor, sie zurück nach Grim Batol zu bringen, um damit zu experimentieren und sie zu pervertieren. Das werde ich einfach nicht zulassen.\n\nWenn Ihr uns wirklich helfen wollt, dann haltet sie auf! Holt die Eier zurück und bringt sie mir.", sourceObjective = "Holt 6 Zinnobereier zurück.", progress = "Die Zwielichtdrachen entstehen aus ihren abscheulichen Experimenten. Der Schattenhammer ist zu weit gegangen. Todesschwinge ist zu weit gegangen.", completion = "Ich weiß nicht, ob Ihr das für mich oder die Jungen im Inneren getan habt, aber das spielt auch keine Rolle. Es zeigt deutlich, dass Ihr ein Freund unseres Schwarms sein wollt. Ich weiß das zu schätzen.\n\nIch kann Euren Verbündeten die Angriffe auf meine Brut nicht verzeihen, aber bis jetzt scheint es zumindest so, als hättet Ihr Euch für die richtige Seite entschieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27509] = { id = 27509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigungslücke", description = "Jeder Millimeter der Luft um das Refugium herum wird permanent von Liras Drachen bewacht. Sie müssen sich von unten einen Weg in den Schrein gebahnt haben.\n\nNehmt diese Blitzwuchspartikel. Sie sollten sich gut dafür eignen, sämtliche Löcher, Tunnel oder Portale zu schließen, über die sie unsere Verteidigung durchbrochen haben könnten.\n\nFindet die Lücke in unserer Verteidigung, Schließt sie.", sourceObjective = "Findet die Quelle des Schattenhammers im Zinnoberrefugium und vernichtet sie.", completion = "Gut gemacht. Vielen Dank, {race}.\n\nIch werde dafür sorgen, dass wir so einen dummen Fehler nicht mehr begehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27510] = { id = 27510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Wolf im Bärenpelz", description = "Diese Worgen verkaufen uns für dumm! Man sollte meinen, dass nur ein Schwachkopf einen ihrer Druiden in Bärengestalt für einen echten Bären halten würde. Leider gibt es hier an der Frontlinie der Verlassenen viele Schwachköpfe. Wir haben bereits mehrere Bataillone bei organisierten Bärenangriffen der Worgen verloren. Ja, es ist in der Tat noch schwachsinniger, als es klingt.\n\nDirekt östlich von hier Richtung Hügelland findet Ihr Druiden der Worgen in den Wäldern. Sie sind als Bären getarnt. Tötet sie und sichert unsere südliche Versorgungslinie.", sourceObjective = "Tötet 10 unauffällige Bären.", completion = "Ich hoffe nur, dass wir demnächst nicht auch noch von unverdächtigen Vögeln, Katzen und Bäumen dezimiert werden… oder Seelöwen! Könnt Ihr Euch das vorstellen?", sourceObjectiveStatus = "unverified-source-field" }
quests[27511] = { id = 27511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spannende Entdeckungen", description = "Welch ein Fund! Und irgendwie ist alles von Plünderern verschont geblieben...\n\nHört zu, {name}. Ich muss diesen Ort aufzeichnen, bevor wir etwas verändern. Warum seht Ihr Euch nicht ein wenig um, während ich das mache - Ihr wisst schon, ein wenig auf Entdeckungsreise gehen. Ihr habt es Euch verdient.\n\nHaltet Eure Augen offen und achtet auf Ungewöhnliches.\n\nOh! Und bitte... macht nichts kaputt, ja?", sourceObjective = "Erforscht die Kammer der Sterne.", completion = "Eure Erforschung der Kammer der Sterne hat mehr Fragen aufgeworfen als Antworten gebracht...", sourceObjectiveStatus = "unverified-source-field" }
quests[27512] = { id = 27512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dimensionsübergreifender Krieg: Kapitel I", description = "<Sylvanas gibt Euch den Siegelring.>\n\nNehmt den Ring und macht Euch auf nach Berens List im Südosten von hier in einer Höhle in den Hügeln. Sobald Ihr dort seid, durchsucht die Höhle nach dem Portal zu der Dimensionstasche, die die Magier von Mühlenbern verbirgt.\n\nIch werde mit Euch über Eure Gedanken kommunizieren, {name}. Wenn Ihr das Portal erreicht habt, werde ich Euch Eure Befehle geben.", sourceObjective = "Findet das Dimensionsportal von Mühlenbern.", progress = "<Das Portal summt.>", completion = "<Die Stimme der Bansheekönigin erfüllt Eure Gedanken.>\n\nJa, das ist es. Jetzt streicht mit dem Ring über die Runen auf dem Portal und Ihr solltet für die dimensionsübergreifende Reise vorbereitet sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[27513] = { id = 27513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dimensionsübergreifender Krieg: Kapitel II", description = "<Die Worte der Bansheekönigin ertönen im Inneren Eures Kopfes.>\n\nIhr seid jetzt bereit, das Portal zu benutzen. Seid gewarnt, {name}, sobald Ihr das Portal durchschreitet, erscheint Ihr in einer anderen Dimension von Mühlenbern. Dort werden Hunderte oder sogar Tausende Magier darauf warten, Euch zu töten.\n\nIhr müsst durchhalten und alle töten, die sich Euch in den Weg stellen.", sourceObjective = "Tötet 20 Magier von Mühlenbern.", sourceObjectiveStatus = "unverified-source-field" }
quests[27514] = { id = 27514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vogel am Boden! Vogel am Boden!", description = "Während Ihr an der Küste gekämpft habt, habe ich gesehen, wie fast genau westlich von hier ein Greif aus den Wolken gestürzt ist.\n\nEs war keiner von unseren.\n\nWahrscheinlich gehörte er zu einem der Wildhämmer. Ich weiß, dass Kuran als eine der obersten Prioritäten nach der Einnahme des Strandes Kontakt zu den verschollenen Wildhammerklans aufnehmen wollte.\n\nIch kann keinen meiner Männer entbehren, um dort nachzusehen, aber Euch schon. Findet den abgestürzten Wildhammer!", sourceObjective = "Findet den abgestürzten Greifenreiter der Wildhämmer Thordun Hammerschlag am Zwielichtufer im Schattenhochland.", completion = "Ach, so ein Mist. Ihr seid nur ein {class} der Allianz. Ich hatte auf Rettung gehofft.", sourceObjectiveStatus = "unverified-source-field" }
quests[27515] = { id = 27515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wurzel alles Guten", description = "Schaut doch, Kumpel. Sie liegt in den letzten Zügen! Wenn mein Vogel stirbt, bin ich so gut wie wertlos.\n\nAlso macht Euch nützlich. Hier auf der Halbinsel wächst dorniger Stinkwurz im Boden. Der Geruch zieht Euch die Socken aus, aber in Wasser eingeweicht wird daraus ein echtes Allheilmittel.\n\nSammelt ein paar Wurzeln, während ich meinen Vogel verteidige. Und beeilt Euch! Ihr Flachzangen von der Allianz habt ja nicht gerade den Ruf, rechtzeitig einzuschreiten, oder?", sourceObjective = "Sammelt 8 Stück dorniger Stinkwurz am Zwielichtufer.", progress = "Habt Ihr meine Wurzeln, {class}? Na?", completion = "Oh, gutes Zeug! Ich hoffe, Ihr habt nichts davon gegessen. Es verursacht schlimme Krämpfe, aber bei Vögeln wirkt es Wunder!", sourceObjectiveStatus = "unverified-source-field" }
quests[27516] = { id = 27516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Schwingen nach Hochstade", description = "He, schaut nur! Sie ist schon viel munterer.\n\nGut, <Herr/Fräulein> Etepetete von der Allianz. Ist das Euer Lager da an der Küste? \"Hochstade\" sagt Ihr? Meint Ihr, mein Vogel und ich könnten dort eine Weile Unterschlupf finden, bis es ihr besser geht?\n\nSpringt auf! Wir fliegen gemeinsam nach Hochstade!", sourceObjective = "Sprecht mit Thordun Hammerschlag und fliegt gemeinsam nach Hochstade!", completion = "Gut gemacht, {name}! Durch Eure Rettung des abgestürzten Greifenreiters konnten wir einen ersten Kontakt mit den alten Wildhammerklans herstellen. Wir werden herausfinden, wer noch übrig ist und wie viele es sind.\n\nWir bekommen Auftrieb!", sourceObjectiveStatus = "unverified-source-field" }
quests[27517] = { id = 27517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seid vorbereitet", description = "Jeder Abenteurer, der etwas auf sich hält, weiß, dass man niemals einen Fuß in eine Höhle, ein Verlies, eine Krypta oder eine Grabstätte setzt ohne ausreichend Seil dabeizuhaben... nicht wahr?\n\nDavon kann man nie genug haben!\n\nMan geht sogar so weit, jedes Stück, das man finden kann, von den Skeletten hier aufzusammeln.", sourceObjective = "Sammelt 6 Stücke Seil.", progress = "Was habt Ihr gefunden, {name}??", completion = "Ahh, Seil! Danke, mein Junge!\n\nIrgendwie habe ich das Gefühl, ich werde es brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27518] = { id = 27518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dimensionsübergreifender Krieg: Kapitel III", description = "<Sylvanas spricht direkt durch Euch.>\n\nIhr müsst das Wesen, das diese Dimensionstasche aufrechterhält, finden. Wahrscheinlich ist es dieser Narr, Ataeric... Sucht das Gelände nach ihm ab. Solltet Ihr ihn finden, müsst Ihr alles Notwendige tun, um ihn davon abzuhalten, seine Magie zu kanalisieren. Er wird zweifellos durch einen mächtigen, arkanen Schild geschützt und wird Handlanger aus arkaner Energie auf Euch loslassen. Besiegt die Handlanger in seiner Nähe, um ihre Energien freizusetzen. Kein Magier kann mit so viel Kraft umgehen!", sourceObjective = "Überladet Erzmagier Ataeric mit arkaner Macht, um den transdimensionalen Schild auszuschalten.", completion = "Hätte ich nicht mit eigenen Augen Eure Taten gesehen, ich hätte es nicht geglaubt, {name}. Jetzt, da die Magier von Mühlenbern sich auf unserer Seite befinden, gibt es nur noch eins für uns zu tun, bevor wir Gilneas zurückerobern und diese Hunde der Allianz nach Sturmwind zurückrennen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27519] = { id = 27519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter dem erstickenden Sand", description = "Nein... Das kann nicht sein.\n\nOrsis ist fast vollkommen unter dem Wüstensand begraben.\n\nDer Feind wird dafür bezahlen.\n\nDoch zunächst müssen wir meinem Volk helfen. Schnell, {name}. Wir haben nicht viel Zeit, bevor auch der letzte meiner Brüder lebendig begraben wird!", sourceObjective = "Rettet 8 Überlebende von Orsis.", completion = "Ich danke Euch, {name}. Orsis wurde dafür bestraft, sich nicht den Truppen von Todesschwinge angeschlossen zu haben.\n\nPrinz Nadun hat meinem Volk Zuflucht in seiner Stadt angeboten. Ich muss dort hingehen und mich um die Überlebenden kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[27520] = { id = 27520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Al'Akirs Diener", description = "Al'Akir hat seine Diener ausgesandt, um Todesschwinges Befehle zu befolgen.\n\nDie Botschaft ist deutlich. Wir schließen uns ihnen an oder sie vernichten uns.\n\nIch weiß nicht viel über Euch, {race}. Aber eins weiß ich. Wenn Ihr Euch als Feind Al'Akirs erweist, wird Eure Hilfe nicht unbemerkt bleiben.\n\nWas sagt Ihr dazu, {class}?", sourceObjective = "Tötet 6 Abkömmlinge von Al'Akir.", completion = "Ihr erweist Euch weiterhin als wertvoller Verbündeter, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27521] = { id = 27521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elender Hort des Abschaums und der Boshaftigkeit", description = "{race}... bitte, ich brauche Eure Hilfe.\n\nEtwas ist mit meinen Leuten geschehen. Unser Kommandant, Waldläuferlord Falkenspeer, hat einen Gegenstand aus magischer Energie gefunden. Meine Freunde, meine Familie... sie alle sind seiner verführerischen Macht erlegen. \n\nSie sind verdorben, {race}. Sie alle.\n\nMeine Ellaria würde so nicht leben wollen, auch meine Brüder nicht. Bitte erlöst sie von ihrem Leid. Die Jagdhütte von Quel'Lithien ist nicht weit weg. Nur den Hügel hinauf im Nordwesten.", sourceObjective = "Tötet 9 Getriebene nahe der Jagdhütte von Quel'Lithien in den Östlichen Pestländern.", completion = "Bemitleidet mich nicht. Es waren zwar meine Freunde, die Ihr an der Jagdhütte von Quel'Lithien gesehen habt, aber sie waren schon so gut wie tot.", sourceObjectiveStatus = "unverified-source-field" }
quests[27522] = { id = 27522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prügelstrafe", description = "Uns Paladinen bringt man bei, unseren Feinden gerecht und ruhig entgegenzutreten, aber dies ist ein Notfall. Außerdem habe ich noch nie auf meine Lehrer gehört.\n\nIch werde versuchen, im Pestwald mehr über Giddy herauszufinden. Kümmert Ihr Euch um die Geißel nordöstlich von hier, auf der anderen Seite dieses Turms. Die Untoten fürchten den Tod nicht, aber schlagt sie lang genug, dann verplappern sie sich vielleicht und geben uns Hinweise auf Gidwins Aufenthaltsort.", sourceObjective = "Schlagt mindestens 6 Belagerungsingenieure der Geißel nieder, um an Informationen über Gidwins Verbleib und seinen Entführer zu gelangen.", completion = "Hört sich so an, als hättet Ihr Erfolg gehabt. Hoffentlich reichen diese Informationen, um Gidwin zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27523] = { id = 27523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämmerschwinge, oh, wie ich Euch hasse...", description = "Ich habe zu meiner Zeit viel gesehen, {race}. Die Gipfel des Hyjal... die Seltsamkeiten der Scherbenwelt... einen Wall aus Geißelsoldaten auf dem Weg in die Schlacht. Aber noch nie zuvor habe ich eine so große und schockierend weiße Fledermaus wie Dämmerschwinge gesehen.\n\nWie er mich aus seinem Nest verspottet!\n\nDiese dämonische Albinofledermaus kreist südwestlich von hier, nördlich vom Faulholzsee. Findet und vernichtet ihn. Sollte er zu hoch fliegen, könnt Ihr ihn mit meinem Leuchtfeuer anlocken.", sourceObjective = "Beschafft einen Fellflicken von Dämmerschwinge.", progress = "Ich hoffe, Ihr habt diese Kreatur beseitigt.", completion = "Hervorragende Arbeit. Nun kann ich meine Arbeit fortsetzen, ohne von dieser großen, weißen Bestie abgelenkt zu werden.\n\nIch werde dieses Fell zu etwas verarbeiten, dass Ihr nutzen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27524] = { id = 27524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blinde Wut", description = "Tarenar hat nicht gescherzt, als er sagte, Vernunft und Vorsicht interessieren ihn nicht. Er hätte diesem Hochelfen beinahe den Kopf abgeschlagen, als er auf der Suche nach Gidwin in den Pestwald lief. Ihr solltet ihm folgen.\n\nDer Pestwald ist ziemlich groß, {name}. Viel Glück. Ich hoffe, ihr <Jungs/Drei> kommt heil aus dem Wald heraus.", sourceObjective = "Findet Tarenar Sonnenhieb im Pestwald in den Östlichen Pestländern.", completion = "Ich habe nichts außer hirnlosen Untoten gefunden, aber davon jede Menge. Ich wollte mich gerade nach Stratholme durchtöten, als Ihr kamt. Hattet Ihr mehr Erfolg?", sourceObjectiveStatus = "unverified-source-field" }
quests[27525] = { id = 27525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wächter von Stratholme", description = "Baroness Anastari hält ihn gefangen? Hier im Pestwald?\n\nDer Pestwald ist groß... aber wir werden ihn finden. Wir WERDEN Gidwin finden.\n\nUnmittelbar in unserem Osten und Westen befinden sich zwei Nekropolen neben dem Weg nach Stratholme. Im Inneren werdet Ihr zwei Todesrittern begegnen - Totenschwurs Leutnants. Ich bezweifle, dass einer von ihnen Verwendung für eine Paladingeisel hätte, aber vielleicht wissen sie ja, wo Gidwin ist.", sourceObjective = "Tötet Omasum Pesthuf und Karthis Dunkelrune.", completion = "Wir müssen weiter! Wir sind schon ganz nahe!", sourceObjectiveStatus = "unverified-source-field" }
quests[27526] = { id = 27526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gidwins Schicksal enthüllt", description = "Rasch - findet einen Eingang zum Schlachthaus südlich von uns. Ich treffe Euch im Inneren.\n\nBereitet Euch auf einen Kampf vor!", sourceObjective = "Sucht nach Gidwin Goldzopf im Schlachthaus im Zentrum des Pestwalds.", completion = "Ihr glaubt ja nicht, wie froh ich bin, Euch beide zu sehen! Mir steigen gleich die Tränen in die Augen... Augen, die zu lange durch eine Banshee blicken mussten.\n\nTut mir leid, dass ich Euch so viel Ärger bereitet habe. Bringt Ihr mich zurück zur Karawane?", sourceObjectiveStatus = "unverified-source-field" }
quests[27527] = { id = 27527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ende der Reise", description = "Ich halte die Luft an diesem Ort nicht mehr aus. Der Gestank der Untoten ist schon schlimm genug, aber wenn man dem noch Pilze hinzufügt? Ich hasse Pilze!!\n\nIch werde zur Kapelle des Hoffnungsvollen Lichts zurückkehren, {name}... und ich nehme Tarenar und Fiona mit. Wir alle haben eine Pause verdient. \n\nHier, nehmt das. Das ist mein Ruhestein - mit ihm könnt Ihr Euch zur Kapelle versetzen lassen. Ich brauche ihn nicht - ich reise auf dem Wagen.\n\nUnd zwar auf dem VORDERSITZ.", sourceObjective = "Sprecht mit Fiona an der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.\n\nBereitgestellter Gegenstand:", completion = "Ihr habt mit Eurer Hilfe alle Erwartungen übertroffen, {name}. Die Türen meines Wagens stehen Euch stets offen.\n\nDie Jungs und ich haben sogar etwas Besonderes für Euch vorbereitet. Hier, trefft Eure Wahl!", sourceObjectiveStatus = "unverified-source-field" }
quests[27528] = { id = 27528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geißelmasse", description = "Man kann die Geißel nicht einfach töten. Sie kommt zurück. Man muss die verdorbene Masse zerstören, aus denen sie besteht... und selbst dann kehren diese Unholde manchmal als Schreckgespenster zurück.\n\nNur wenige Untote bringen so viel Masse mit wie die schwerfälligen Monstrositäten. Tötet sie und verbrennt ihre Leichen. Ihr findet sie überall im Pestwald.\n\nLasst Euren Zorn nicht erkalten, {race}. Vergesst nicht, dass diese Monstrositäten aus den Körpern guter Leute zusammengenäht wurden. Ihre Existenz ist ein Verbrechen.", sourceObjective = "Tötet 8 überladene Golems und steckt ihre Kadaver mit der Fackel des Kreuzfahrers in Brand.", completion = "Ein gesegnetes Feuer reinigt sogar das verdorbenste Fleisch.\n\nIm Angesicht des Lichts hatten sie keine Chance.", sourceObjectiveStatus = "unverified-source-field" }
quests[27529] = { id = 27529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidiger von Darroheim", description = "Die Schlacht von Darroheim war eine der großen Tragödien, die wir Menschen durch die Geißel erleiden mussten. Bis heute hallt sie nach.\n\nViele der mutigen Verteidiger der Stadt ziehen nun als schreckliche Diener der Geißel umher. Wir werden ihr Leid beenden.\n\nJagt Menschenfresserghule hier im Pestwald. Viele dieser Abscheulichkeiten waren einst rechtschaffene Menschen in Darroheim. Die Zerstörung ihrer Körper wird ihre Seele befreien.", sourceObjective = "Befreit 8 Darroheimgeister aus den Körpern der Menschenfresserghule und sprecht mit ihnen.", completion = "Es ist gut zu hören, dass Ihr die gequälten Seelen meiner Brüder gefunden und befreit habt. Meine Kraft ist erneuert, nun da ich weiß, dass zumindest einige der Verteidiger von Darroheim nicht mehr länger in der widerlichen Dienerschaft der Geißel gefangen sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[27530] = { id = 27530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kadaverbestien", description = "Feige Kultisten widmen sich im Süden einer düsteren Aufgabe: Sie reanimieren gewaltige Fleischberge, um aus ihnen Riesen zu erschaffen, die Kadaverbestien genannt werden. Zum Glück für uns sind diese Riesen noch leblos und schwach.\n\nNehmt dieses Amulett - benutzt es, um einen Brunnen heiliger Energie zu erschaffen. Versucht, drei dieser Quellen in der Nähe einer der Kadaverbestien zu platzieren, die von den Kultisten reanimiert werden. Die heilige Energie sollte ausreichen, um sie zu überladen und ihren Körper für immer zu zerstören.", sourceObjective = "Zerstört die Hüllen dreier Kadaverbestien, indem Ihr drei oder mehr Argentumlichtbrunnen neben ihnen platziert. Ihr könnt die Argentumlichtbrunnen nicht im Kampf platzieren und nicht weniger als zehn Meter voneinander entfernt.", completion = "Ihr seid ein wahrer Champion des Lichts, {name}. Ich wünsche Euch Glück für all Eure zukünftigen Unterfangen, wo auch immer sie Euch hinführen mögen.\n\nSolltet Ihr in Zukunft etwas benötigen, werdet Ihr mich hier finden - bis zu den Knien in den Leichen der Getöteten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27531] = { id = 27531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seuchenabwehrforschung", description = "Einst habe ich als Apotheker für die sogenannte \"Bansheekönigin\" Sylvanas gearbeitet. Ich habe sie einmal bewundert, aber etwas in ihr hat sich verändert. Sie ist nicht mehr sie selbst.\n\nIch habe den Schwur, der mich an die Verlassenen band, gebrochen und trat dem Kreuzzug bei. Nun benutze ich meine Kenntnisse der Alchemie, um nach einem Wirkstoff gegen die Seuche zu suchen. Der Pestwald ist der geeignete Ort dafür.\n\nIch brauche Nachschub für einige Reagenzien, die man im Pestwald findet. Ich werde Euch für jeden Gegenstand, den Ihr findet, bezahlen.", sourceObjective = "Beschafft 20 Faulbeeren, 5 abgetrennte Arme und 1 Stapel Fußabschabung eines Fleischgiganten.", progress = "Habt Ihr alles?", completion = "Ich liebe den Geruch von frischer Fußhornhaut, Ihr nicht auch?\n\nWenn wir ein Heilmittel für die Seuche finden wollen, müssen wir kreativ bei unseren Zutaten sein. Entschuldigt mich bitte, ich muss wieder an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[27532] = { id = 27532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pestwaldturm", description = "Nach den ungünstigen Entwicklungen im Fall Gidwin denke ich, ein Mann meines Alters sollte die gefährliche Reise durch den Pestwald nicht antreten. Das ist nicht schlimm - ich werde den Pestwaldturm bei meiner nächsten Rundreise besuchen.\n\nAllerdings habe ich eine Lieferung für Judkins. Ihr seid jünger als ich und kampferprobt. Würdet Ihr ihm diese Lieferung bringen?", sourceObjective = "Bringt Leuchtfeuers Paket zu Erzapotheker Judkins beim Pestwaldturm in den Östlichen Pestländern.", progress = "Leuchtfeuers Paket... geht es Argus gut? Ist etwas passiert?", completion = "Puh. Jedes Mal, wenn ich Argus durch den Pestwald trotten sehe, befürchte ich, es wird das letzte Mal sein. Gut, dass er weise genug ist, ein Jungblut wie Euch zu schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[27533] = { id = 27533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schicksal schlimmer als der Schlachter", description = "Die Bewohner des Schreckenstals wurden zuerst krank, dann böse. Das sind wirklich keine guten Zeiten.\n\nUnd die Schweine... sie wurden ebenfalls krank! Womit haben Schweine eine solche Krankheit verdient? Hah hah hah! Nichts!\n\nDie Leute interessieren mich nicht, aber die bösen Schweine machen mich immer noch traurig. Solltet Ihr sie jedoch töten... Wäre ich vielleicht glücklich.", sourceObjective = "Tötet 9 verseuchte Schweine.", completion = "Ich sehe sie! Ihr auch? Die kleinen Schweinegeister auf dem Weg zum großen Stall im Himmel...", sourceObjectiveStatus = "unverified-source-field" }
quests[27534] = { id = 27534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augustus' Quittungsbuch", description = "Ich bin jetzt bereit fürs Geschäftliche! Was wollt Ihr?\n\nOh, Moment mal... ohne mein Quittungsbuch kann ich kein Geschäft eröffnen. Wie soll ich ohne mein Quittungsbuch den Überblick behalten?\n\nIch muss es irgendwo in der Stadt gelassen haben. Ich hatte ein Zimmer im Gasthaus... dort muss das Buch sein.\n\nBringt mir mein Buch. Bitte, bringt es mir! Bringt mir mein Buch und Ihr werdet sehen! Ich eröffne mein Geschäft und Ihr werdet sehen, dass meine Preise der WAHNSINN sind!", sourceObjective = "Beschafft Euch Augustus' Quittungsbuch aus dem Gasthaus im Schreckenstal.", progress = "Habt Ihr mein Quittungsbuch? Ich will endlich wieder an die Arbeit gehen!", completion = "Da ist es! Oh meine Güte! Ich hatte vergessen, wie voll es war!\n\nDies ist ein glorreicher Tag, {name}! Toll! Wahnsinnig gut, sage ich Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[27535] = { id = 27535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein bisschen meschugge", description = "Ich sehe gelegentlich nach Augustus im Schreckenstal, nur um sicherzustellen, dass es ihm gut geht. Manche von uns Untoten kommen wohl mit der Seuche besser klar als andere.\n\nDas Schreckenstal liegt westlich von hier. Würdet Ihr für mich nach ihm sehen?", sourceObjective = "Sprecht mit Augustus dem Meschuggenen im Schreckenstal.", completion = "Ihr seid am richtigen Ort, mein Herr! Jawoll, es gibt keinen besseren Ort als das Schreckenstal! Das Juwel von Lordaeron!", sourceObjectiveStatus = "unverified-source-field" }
quests[27536] = { id = 27536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Größtenteils harmlos", description = "Hier ist noch ein Gefallen, den Ihr mir tun könnt, <alter Freund/alte Freundin>.\n\nKürzlich ist eine ganze Ladung Landminen aus Beutebucht angekommen. Aber jemand hat sie alle über Nacht gestohlen!\n\nWer immer es war, er war nicht besonders sorgfältig, denn er hat sie überall im Sumpf östlich von hier fallengelassen. Kein Goblin, der mir bekannt ist, würde so unvorsichtig sein.\n\nIch möchte, dass Ihr da rausgeht und diese Landminen für mich einsammelt. Ich bin sicher, dass sie vollkommen sicher und entschärft sind. Jede einzelne. Jawohl.", sourceObjective = "Sammelt 8 entschärfte Landminen im Sorgendunkel östlich von Kraulsumpf.", progress = "He, habt Ihr die Dinge beschaffen können, um die ich gebeten hatte?", completion = "Was hab' ich Euch gesagt, hm? Völlig harmlos!\n\nIch sorge dafür, dass ein paar dieser Dinger zu Euren Freunden geschafft werden, {name}. Mit Rabatt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27537] = { id = 27537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer Elementare sät, wird Sturm ernten", description = "Unsere Freunde des Irdenen Rings haben versucht, Portale zurück nach Sturmwind zu öffnen, aber sie hatten kein Glück. Thordun hier sagt mir jedoch, dass er vielleicht die Lösung für unser Problem hat.\n\nDie wahnsinnigen Wasserelementare im nahegelegenen Fluss Verrall sind in Raserei verfallen. Thordun sagt, dass wir ihre Energie kanalisieren können, um ein Portal zu schaffen.\n\nIch habe ja keine Ahnung von diesem Elementar-Schnickschnack, aber eines verstehe ich ganz deutlich: Elementare töten und ihren Strudelkern nehmen. Bringt sie zu Talaa im Hof!", sourceObjective = "Tötet matschige Wasserelementare, um 5 Strudelkerne zu sammeln.", progress = "Hallo {class}. Kurdran hat mir gesagt, dass Ihr eine Lösung für unser Portalproblem habt?", completion = "Eines könnt Ihr mir glauben, {name}. Diese Elementarenergien sind so mächtig, so chaotisch! Kein Wunder, dass der Schattenhammer seine Festung hier errichtet hat.\n\nIch sollte diese Energien in etwas Gutartigeres und Produktiveres umwandeln können. Probieren wir es...", sourceObjectiveStatus = "unverified-source-field" }
quests[27538] = { id = 27538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der perfekte Verband", description = "Geht Ihr zufällig zur Mündung des Verrall? Dann habe ich einen Rat für Euch, der Euren Männern hier sehr helfen kann… und meinem Vogel!\n\nWenn Wasserelementare sich ihren Weg durch Gestein bahnen, entsteht ein seltsamer Schlamm. Getrocknet ist er hart wie Stein, aber er enthält die erfrischende Macht des Wassers. Wenn Ihr einen Gipsverband aus diesem Schlamm herstellt, wachsen gebrochene Knochen wieder zusammen, fest wie Eisen.\n\nBringt ein wenig von diesem Schlamm zu Talaa, der Schamanin da unten. Sie wird wissen, was damit zu tun ist!", sourceObjective = "Sammelt 10 Haufen Verrallschlamm.", progress = "Was höre ich da immer über diesen Verrallschlamm?", completion = "Oh… Schlamm. Ihr habt mir Schlamm gebracht?\n\nOh, dieses Zeug pulsiert ja regelrecht vor Macht! Jetzt verstehe ich, was Thordun meint. Ich werde ihn an all unsere Heiler verteilen. Unsere Verwundeten werden im Handumdrehen wieder auf den Beinen sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[27539] = { id = 27539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werft sie auf den Haufen", description = "Ich sammle die Köpfe der Skelette, die ich besiege. Ich habe schon einen kleinen Haufen zusammen.\n\nSolltet Ihr zufällig Schädel finden, könnt Ihr sie gern dazu legen. Der Schädelhaufen scheint die Wellen der Untoten zurückzuhalten und... na ja... ich betrachte ihn auch sehr gern.", sourceObjective = "Beschafft 16 stinkende Schädel von verfluchten Magiern und Soldaten der Geißel im Pestwald.", progress = "Ihr seid ja ziemlich beladen. Sind das etwa Schädel?", completion = "Möge mein Haufen immer weiter wachsen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27541] = { id = 27541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lektionen der Vergangenheit", description = "Dieser unglückliche Forscher hat offensichtlich in letzter Zeit ziemliches Pech gehabt.\n\nDie Vernunft gebietet, dass Ihr die Leiche auf Hinweise durchsucht. Darum wird Euch niemand beneiden, aber wir brauchen Hinweise, die Licht in unsere Umgebung bringen...", sourceObjective = "Erhaltet die zerbrochene Brille.", progress = "Gibt es Neuigkeiten, {name}?", completion = "Seltsam...\n\nSieht so aus, als ob jemand Edelsteine als Linsen benutzt hat.\n\nIch sollte sie ohne großen Aufwand reparieren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[27542] = { id = 27542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An die Front", sourceObjective = "Die Stunde des Sieges rückt näher, {name}. Godfrey hat einen Plan geschmiedet, um unsere Feinde zu dezimieren. Ich schicke Euch mit ihm und seinen Männern ins Feld, um die rebellischen Aufrührer in die Knie zu zwingen und das Schicksal des Allianzabschaums zu besiegeln, der unsere Ländereien bedroht.\n\nUnser letzter Marsch beginnt, sobald Ihr bereit seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[27543] = { id = 27543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was wir getan haben" }
